const DATA = [{ "term": "Accusatio suspecti tutoris", "gloss": "обвинение срещу заподозрян настойник, който е действал против интересите на пупила", "body": "Популярен иск, произтичащ от цивилното право, предвиден в Закона на дванадесетте таблици (Lex XII [duodecim] tabularum). Той е насочен към смяна на опекуна, ако завещанието (testamentum*) на бащата е било умишлено е действал в против интересите на пупила /непълнолетния/. Вж. също tutor suspectus.", "cat": "person" }, { "term": "Alieni iuris", "gloss": "подвластни лица", "body": "Лица, подвластни синове или роби, които се намират под властта на домовладелеца (paterfamilias*).", "cat": "person" }, { "term": "Ancilla", "gloss": "робиня", "body": "Вж servus*.", "cat": "person" }, { "term": "Auctoritas", "gloss": "одобрение, помощ, подкрепа", "body": "(1) Свързана с манципацията (mancipatio) форма на гарантиране, според която отчуждителят гарантира приобретателя за иска от евентуална евикция (evictio).\n(2) Овластяване на едно лице от народното събрание или по силата на закона, с което се придава пълна валидност на правния акт. Auctoritas principis (одобряване от принцепса) е изключителната власт на Императора (princeps), чийто авторитет е всеобщ и безспорен по времето на принципата от ранната Империя. Auctoritas tutoris (одобрение на настойника) е съгласието на настойника (tutor) по извършването на правен акт от подопечния.", "cat": "person" }, { "term": "Barbari", "gloss": "варвари", "body": "Название, дадено от римляните на всички народности, живеещи извън границите на Римската империя.", "cat": "person" }, { "term": "Capitis deminutio", "gloss": "букв. „намаляване на правоспособността“", "body": "Термин, използван при изгубване /или промяна/ на един от трите статуса (status*), които определят правното положение на индивида в обществото: статуса на свободата, статуса на гражданството и фамилния статус. Намаляването на правоспособността може да бъде:\n– maxima (максимално намаляване на правоспособността): това е превръщането на едно свободно лице в роб. Произтича от продажбата на дезертьор като роб (venditio trans Tiberim), както и от пленяването на римски гражданин от враговете (captivitas*), от прелюбодеянието на една свободна жена с роб, въпреки противопоставянето и забраната на господаря на роба, а също и в случаите, когато едно лице е осдено за престъпление или пък не е включено в ценза;\n– media (средно намаляване на правоспособността): то е налице, когато се загубва римското гражданство. Това е особеният случай за осъждане на изгнание (exilium*);\n– minima (минимално намаляване на правоспособността): то е налице при превръщането на едно неподвластно лице (sui iuris*) в подвластно (alieni iuris*). Това е случаят на осиновяване (adrogatio*) на лицето от домовладелец (paterfamilias*) или на омъжване на неподвластна жена (sui iuris*) в брак с манус (matrimonium cum manu*).", "cat": "person" }, { "term": "Captivitas", "gloss": "плен", "body": "Положение на свободния римски гражданин, който е пленник на неприятеля и в резултат на това претърпява максимално намаляване на правоспособността (capitis deminutio maxima*).", "cat": "person" }, { "term": "Caput", "gloss": "глава, лице", "body": "Означава буквално „глава“, а в по-широк смисъл самият индивид, лицето. Този термин (caput*) в следкласическия период има предимно правно-техническо значение, близко до съвременното понятие за правоспособност.", "cat": "person" }, { "term": "Cavere", "gloss": "занимавам се с интересите на друго лице, предвиждам", "body": "Дейност на юристите, състояща се в изразяването на мнения и създаването правни актове, например редактиране на завещание или договор според волята на страната, която те консултират. Този израз се отнася също и до дейността по съветване, консултиране, например по време на договорни преговори.", "cat": "person" }, { "term": "Census", "gloss": "ценз", "body": "Цензът означава разпределение на гражданите според размера на тяхното имущество. Цензурирането се осъществява на всеки пет години и се извършва в различните епохи първоначално от рекса, от консулите (consules*) и от цензорите (censores*). В тази връзка гражданите са разпределени по триби (tribus*), по класи (classis*) и по центурии (centuria*).", "cat": "person" }, { "term": "Centuria", "gloss": "центурия", "body": "Военна единица, а също така и единица за упражняване на активно избирателно право. Традицията приписва на Servius Tullius (рекс на Рим, който е управлявал от 578 до 535 г. пр.Хр.) разделението на римските граждани (civis Romanus*) на 193 центурии, според критерия за тяхното имуществено положение. Центуриите са разделени на пет класи (classis*).", "cat": "person" }, { "term": "Civis", "gloss": "гражданин", "body": "Лице, което има права и е подчинено на задължения, свързани с качествата му на член на една определена гражданска община.", "cat": "person" }, { "term": "Classis", "gloss": "класа", "body": "Римските граждани (civis Romanus) се разделят на различни социални класи според техния произход и тяхното богатство. Първото разделение в римската история е свързано с разделението на гражданите на патрициат (patricii) и на плебс (plebs). То се приписва на Servius Tullius (578-535 пр.Хр.), който извършва разделение на обществото по центурии (centuria) и има за ефект разделението на гражданите според тяхното богатство. По-късно се различава сенаторско и конническо съсловие (ordo).", "cat": "person" }, { "term": "Clientes", "gloss": "клиенти", "body": "Свободни лица, които по време на царския период и в първите векове на Републиката живеят в Рим под покровителството и под властта на един пълноправен римски гражданин, който става техен патрон (patronus). Само с негово съдействие те могат да предявяват искове пред съответните органи. Институцията се превръща в инструмент за социално и политическо влияние, налагано от патрона, като загубва своя квазисакрален характер и става в средство, характерно за политическата практика (клиентилизъм).", "cat": "person" }, { "term": "Cognomen", "gloss": "когномен", "body": "Третото име (tria nomina*), което притежават обикновено римските граждани след първото име (praenomen*) и фамилното име (nomen*). Това име служи за означаване на индивидуална особеност (прякор, прозвище), но по-късно се превръща в наследствено и служи за различаване на различните клонове от един и същ род (gens*), а също така и за различните разделения на родословното дърво.", "cat": "person" }, { "term": "Collegia", "gloss": "колеги, съдружници", "body": "Това е сдружение от лица, които си поставят религиозни, политически или професионални цели. Предоставена е широка правоспособност на колегиите, особено по време на Империята. Вж. принципите tres faciunt collegium или tres sunt collegia Вж. и universitas personarum*.", "cat": "person" }, { "term": "Coloniae", "gloss": "колонии", "body": "Градове, създадени или анексирани към Рим върху територия, която е завладяна от римските армии, и които са населени с римски граждани или с жители на Лациум.", "cat": "person" }, { "term": "Contubernium", "gloss": "контуберниум – общност, съвместно съжителство", "body": "Свободно, стабилно съжителство, връзка между двама роби или между роб и свободно лице, което по принцип не създава никакво правно отношение. То не е признато или приравнено на брака (matrimonium*).", "cat": "person" }, { "term": "Cura", "gloss": "попечителство", "body": "Средство за закрила на недееспособните лица, което може да се състои в най-обща защита на техния патримониум, а също така и в ограничения (или забрани за определени правни действия) или точно определени други мерки. По принцип попечителят (curator*) действа от името на недееспособното лице и упражнява неговите права. В тази връзка при попечителство на лица, които са под 25 години (minor XXV annorum*), и които са граждански дееспособни, попечителят се ограничава само да им съдейства или да ги консултира, включително да одобрява извършените от тях действия. Различават се:\n— попечителство на лудите (cura furiosorum);\n— попечителство на лицата под 25 години (cura minorum);\n— попечителство на разточителните (cura prodigorum).", "cat": "person" }, { "term": "Curator", "gloss": "попечител", "body": "Лице, което е натоварено с попечителство (cura*).", "cat": "person" }, { "term": "Curator ventris", "gloss": "попечител на утробата", "body": "Попечител (curator*), натоварен със защита на интересите на нероденото дете (nasciturus*), когато то е изгубило своя paterfamilias* преди раждането си.", "cat": "person" }, { "term": "Deditio", "gloss": "подчинение, капитулация, изоставяне", "body": "а) Подчиняване въз основа на победения армия народ, по силата на който победените губят своята /лична/ държавна/ автономия и сключват договор /държавна/ за подчинение (похае deditio*).\nb) изоставяне на едно лице или на един роб на ноксално основание (похае deditio*).", "cat": "person" }, { "term": "Demens", "gloss": "слабоумен", "body": "Лице, което е засегнато от душевна болест с различна тежест. Това лице, подобно на лудите (furiosus*), е закриляно в правните отношения с трети лица от попечител (curator*).", "cat": "person" }, { "term": "Deminutio", "gloss": "намаляване", "body": "Виж също capitis deminutio*.", "cat": "person" }, { "term": "Dominica potestas", "gloss": "домашна власт, господство", "body": "Конкретизация на квиритската собственост (dominium ex iure Quiritium) по отношение властта на господаря (dominus) върху неговия роб (servus).", "cat": "person" }, { "term": "Excusatio tutoris", "gloss": "екскузация на настойника", "body": "Акт, с който едно лице, което може да бъде определено за настойник (tutor), релевира валидно основание, за да не бъде номинирано за такъв.", "cat": "person" }, { "term": "Favor libertatis", "gloss": "в полза на свободата", "body": "Израз, с който определен правен акт, в който се съдържа неясни или противоречива клауза, трябва да се тълкува в полза на освобождаването в смисъл, който е в полза на (срв. interpretatio*). Този принцип (libertas*) на един роб (servus*). Този принцип се прилага, дори ако основния правен акт трябва да се счете за нищожен (най-често се отнася до нищожност на завещание – testamentum*).", "cat": "person" }, { "term": "Furiosus", "gloss": "лице, засегнато от душевна болест, безумен", "body": "Лице, което е считано за душевно болно (опасен луд), спрямо което се прилага закрила под формата на попечителство (cura*).", "cat": "person" }, { "term": "Gens", "gloss": "род, родова общност", "body": "Група от семейства, чиито домовладеци по мъжка линия произхождат от общ прародител, който е бил начело на общността. Този вид общност се определя само с общото име и домашния култ.", "cat": "person" }, { "term": "Gentiles", "gloss": "гентили, членове на рода/gens", "body": "Група лица, които оформят голямото патриархално семейство с техните общи характеристики, без да се индивидуализирани. Виж родови задължения (obligatio ad genus pertinet).", "cat": "person" }, { "term": "Homo", "gloss": "човек", "body": "Използва се в негативен смисъл за означаване на роб (servus*) или лице, което няма свой статус и което не се счита за субект на правото.", "cat": "person" }, { "term": "Hospitalitas", "gloss": "гостоприемство", "body": "Привилегия, предоставена на някои германски племена, преминали границите на Римската империя, с която им се дава право на подслон и прехрана и частично усядане в завладяните земи.", "cat": "person" }, { "term": "Hospites", "gloss": "хоспити", "body": "Лица, които са от чужди градове или държави - чужденци, и които пребивават в Рим, но се намират под властта и защитата на домовладелеца (paterfamilias*), с когото ги свързва връзка на гостоприемство (hospitalitas*).", "cat": "person" }, { "term": "Hostis", "gloss": "враг", "body": "С този термин най-често се означава чужденец от държава, с която Рим е сключил договор (foedus*) по време на Републиката. Често този договор е предшестван от военни действия, откъдето идва и литературният превод на термина като „враг“.", "cat": "person" }, { "term": "Ignominiosus", "gloss": "недостойно лице", "body": "– лице, което е санкционирано от цензорите (censores) или пък е определено от консулите (consules) като недостойно да бъде включено в листата за избор на магистрати;\n– лице, което понася определените в закона неблагоприятни последици от инфамираща кондемнация (infamia) или в резултат на упражняване на недостойно занятие.", "cat": "person" }, { "term": "Impubes", "gloss": "непълнолетни", "body": "В Рим това са децата, които не са достигнали пълнолетие (pubertas) от правна гледна точка, т.е. момчетата под 14 години и момичетата под 12 години.", "cat": "person" }, { "term": "Infamia", "gloss": "инфамия", "body": "Неблагоприятни социални и правни последици по отношение на лице, което има укоримо (безчестно) поведение. Инфамията може да доведе до намаляване на гражданската дееспособност и забрана за достъп до определени магистратури. Тя е санкция за добросъвестност и честност, изискванията за някои правни сделки (напр. при настойничество – tutela*, фидуцията – fiducia*, влога – depositum*, договорът за мандат – mandatum*, societas* и договора за настойничество – mandatum*). Мярката е основана било на законови разпореждания, било на преторския едикт. В исторически план е предхождана от санкция, налагана от цензорите (nota censoria*).", "cat": "person" }, { "term": "Infans", "gloss": "дете", "body": "Израз, произхождащ от in-fari – който не говори. С този термин се означават лицата, които не са дееспособни поради ниската си възраст – от раждането до навършването на 7 години, т.е. които „не могат да говорят според правото“. Трябва да се различават от „по-големите деца“ (impubes infantia maior), които са на възраст между 7 и 12/14 години, които не са напълно недееспособни, защото в случаите, когато са неподвластни, могат да извършват правновалидни действия със съдействието на своя настойник (tutor*).", "cat": "person" }, { "term": "Ingenuus", "gloss": "свободнороден", "body": "Лице, което е родено като свободно, за разлика от освобожденеда (libertinus*), който е придобил свободата си впоследствие чрез освобождаване (manumissio*).", "cat": "person" }, { "term": "Intervalla lucidae", "gloss": "интервали на просветление", "body": "Периоди, през които лицето, страдащо от лудост (furiosus*), е в моментно съзнание и може да действа самостоятелно без съдействието на своя попечител (curator*).", "cat": "person" }, { "term": "Intuitu personae", "gloss": "с оглед на личността", "body": "Елемент на лично доверие при някои правни сделки, напр. при договора за поръчка (mandatum*) или при договора за дружество (societas*), при които личността на договарящите се страни е от решаващо значение.", "cat": "person" }, { "term": "Iura patronatus", "gloss": "патронатни права", "body": "Съвкупност от права, които едно лице притежава в качеството му на патрон (patronus*), придобито от господаря (dominus*) при освобождаване (manumissio*) на негов роб (servus*). Те се състоят основно във възможността да се иска извършването на определени услуги (operae*) от освободенеца и наследяването му при определени предпоставки.", "cat": "person" }, { "term": "Iusta servitus", "gloss": "правомерно робство", "body": "Израз във връзка с различните хипотези, при които римският гражданин изгубва своята свобода в резултат на максимално намаляване на правоспособността (capitis deminutio maxima*), наложено по силата на цивилното право (ius civile*).", "cat": "person" }, { "term": "Latinus", "gloss": "Латин, жител на Лациум", "body": "Така се определят обитателите на областта Лациум, които първоначално се ползват от особени права. По-късно така се наричат и някои освобожденци, които нямат пълните права на римски граждани, (напр. conubium*), но имат commercium*.", "cat": "person" }, { "term": "Liber", "gloss": "книга; свободно лице", "body": "(1) Част от литературно или юридическо съчинение, написано на определен свитък папирус и представляващо относително завършено изследване на определена материя. Една книга съдържа около 1500–2500 реда с около 35 букви на всеки от тях\n(2) Правно състояние на свободата, отнасящо се до едно лице (срв. libertas*).", "cat": "person" }, { "term": "Libertas", "gloss": "свобода", "body": "Правно положение на всички свободни лица, т.е. на всички, които не са под робство (servitus*).", "cat": "person" }, { "term": "Libertinus", "gloss": "освободенец", "body": "Лице, което е освободено от робство (servitus*) и има статус на освободенец (срв. manumissio*).", "cat": "person" }, { "term": "Mancipium", "gloss": "manu capere, вземам нещо с ръка", "body": "Първоначално с този термин се означава подвластен син на домовладелеца (pater familias*), който е предаден на трето лице и който се намира под негова власт, сходна с тази при робството (квази-робство). В по-широк смисъл с този термин се е означавал и роб (виж също servus* и homo*). С него се определя и самата власт, която трето пълноправно лице alieni iuris упражнява върху манципирания чужд подвластен (esse in mancipio). Тази власт може и да е временна, ако манципирането (emancipatio*) се извършва с цел освобождаване от бащина власт (paterfamilias*) на подвластния син.", "cat": "person" }, { "term": "Manumissio", "gloss": "освобождаване", "body": "Акт, с който робът (servus*) придобива статус на свободен /освобожденец/ (libertinus*).", "cat": "person" }, { "term": "Manumissor", "gloss": "лице, което извършва освобождаване на роб", "body": "С този термин се означава господарят (dominus*), който освобождава свой роб било по собствена инициатива, било по силата на завещателни разпореждания (срв. testamentum*) на своя наследодател, който до смъртта си е бил господар на роба.", "cat": "person" }, { "term": "Minor XXV", "gloss": "viginti quinque) annorum (лице, което не е навършило 25 години", "body": "Пълнолетно лице, което не е навършило 25 години, и което се ползва от особена закрила по силата на плебисцит (срв. lex Laetoria de minoribus*), а след това по силата на преторско предписание (praetor*), при която е възможно възстановяване на разменените престации в положението преди сключването на договора (in integrum restitutio ob aetatem*). По-късно се е защитавала и чрез постоянно попечителство (срв. cura minorum*).", "cat": "person" }, { "term": "Municipium", "gloss": "муниципия", "body": "Общност (в рамките на определено населено място), на която е предоставено правото на гражданство и което има самостоятелна муниципиална организация, в по-голяма или по-малка степен независима от Рим.", "cat": "person" }, { "term": "Nasciturus", "gloss": "заченато, но неродено дете, човешки зародиш", "body": "Термин, с който се означава човешкият зародиш във всеки момент на развитието му между зачеването и раждането. Това дете, макар и неродено, има права (по-специално на наследството), които се предявяват от специално определен за случая попечител (curator ventris).", "cat": "person" }, { "term": "Nemo alteri stipulari potest", "gloss": "никой не може да се задължи в полза на трето лице", "body": "Принцип, който произтича от стипулацията (stipulatio*), но който по-късно се отнася за всички договори. Той се състои в недопускането на обвързване на длъжника (promissor*) към стипуланта (stipulator*), което да е в полза на трето лице.", "cat": "person" }, { "term": "Nobilitas", "gloss": "аристокрация, благородници", "body": "Съсловие от време на Републиката, което се създава във връзка с изпълнение на магистратурите (magistratus) от членовете на т.нар. благороднически фамилии. В него се включват старите патрициански фамилии (patricii), както и плебейските фамилии (plebs), чиито членове трябва да заемат поне една курулна магистратура (срв. aediles curules). Разликата между благородни (nobiles) и неблагородни (ignobiles) замества по-старото разграничаване на патриции и плебеи.", "cat": "person" }, { "term": "Nomen gentilicium", "gloss": "родово име", "body": "С него се определя принадлежността на римския гражданин (civis Romanus) към определен род (gens). То е различно от личното име (praenomen) и прозвището (cognomen).", "cat": "person" }, { "term": "Nominatio tutoris", "gloss": "назначаване на настойник", "body": "Определяне на едно лице, което е в състояние да изпълни функция на настойник (tutor*), от магистрата (magistratus*), който има функцията да номинира настойниците.", "cat": "person" }, { "term": "Operae", "gloss": "работни дни, труд", "body": "(1) Operae servorum – трудовете на робите;\nи (2) Operae libertorum – работни дни, които освободеният роб е бил длъжен да извършва за своя бивш господар (patronus). вещта при наличието на воля да придобие собствеността ѝ. Завладяването е налице при вещ (res*), която никога не е имала собственик (res nullius*) или неманципна вещ (nec mancipi*), която е изоставена (res derelictae*).", "cat": "person" }, { "term": "Optio tutoris", "gloss": "избор на настойник", "body": "Право, предоставено на омъжената в брак с manus жена (срв. matrimonium cum manu*) сама да избере своя (tutor*), което е включено в завещанието (testamentum*) на съпруга ѝ.", "cat": "person" }, { "term": "Oratio Severi de tutela", "gloss": "", "body": "Сенатусконсулт (senatusconsultum), приет през 195 г. сл.Хр. по предложение на император Септимий Север, с което се забранява на настойника (tutor) да отчуждава или залага градските и крайградски имоти на подопечния (pupillus).", "cat": "person" }, { "term": "Ordo", "gloss": "съсловие, ред, ранг, класа", "body": "(1) Социална класа, към която принадлежи едно лице. Различават се конническо (ordo equester) и сенаторско съсловие (ordo senatorius).\n(2) Ред на наследниците (heres), по които те се призовават към наследяване по преторианското право (вж. bonorum possessio)", "cat": "person" }, { "term": "Partus ancillae", "gloss": "дете на робиня", "body": "Родено от робиня (servus*) дете, което става собственост на господаря (dominus*) на майката и се счита за плод (fructus*) в правен смисъл.", "cat": "person" }, { "term": "Patres", "gloss": "отци", "body": "Членовете на старите фамилии и по-специално техните домовладелци, които са членове на Сената (senatus*) и са наречени „patres“ според достойнството на тяхната длъжност според Тит Ливий. Членовете на тези фамилии от древни времена се наричат патриции (patricii*).", "cat": "person" }, { "term": "Patricii", "gloss": "патриции", "body": "Членове на патриархалните фамилии (срв. gens*), които са създали града Рим или впоследствие са били присъединени към неговата община. В древните времена те притежават пълна политическа и гражданска правоспособност.", "cat": "person" }, { "term": "Patrimonium", "gloss": "патримониум, имущество", "body": "От времето на Империята това е съвкупност от вещи, които притежава едно неподвластно лице (sui iuris*). В него са включени всички вещи и права (активи и пасиви), които имат парична равностойност (срв. universitas iuris*).", "cat": "person" }, { "term": "Patronatus", "gloss": "патронат", "body": "Отношението между патрон (patronus*) и освободенец (libertinus*). В по-широк смисъл това са всички права, които притежава патронът в отношенията му с неговия освободенец.", "cat": "person" }, { "term": "Patronus", "gloss": "патрон", "body": "Домовладелец, който е в определено отношение със свободни лица sui iuris*, които са в зависимо положение спрямо него, било като клиенти (срв. clientes*) или като освободенци (срв. libertinus*).", "cat": "person" }, { "term": "Peculium", "gloss": "пекулий", "body": "В опростена форма това е съвкупността от вещи, които са предоставени от paterfamilias* на подвластните му лица (alieni iuris*) – подвластен син или роб (servus*). Те имат право да ползват и най-общо да управляват това имущество, без да го притежават в собственост (dominium*), която си остава в ръцете на paterfamilias*.", "cat": "person" }, { "term": "Peculium castrense", "gloss": "лагерен пекулий", "body": "Пекулий (peculium) на подвластен син на военна служба. В него се включва имуществото, придобито при и по повод на военната служба и то се счита за собствено имущество (patrimonium) на подвластен син, с което той може свободно да се разпоражда с правни сделки между живи или по повод на смърт.", "cat": "person" }, { "term": "Peculium profecticium", "gloss": "профектичен пекулий", "body": "Пекулий (pecule), който е създаден от paterfamilias и предоставен на подвластен (alieni iuris) с цел той да развива търговска или производствена дейност. Пекулият остава собственост на paterfamilias, а подвластният (alieni iuris) може свободно да управлява имуществото (при наличието на клауза libera adunuis tratio peculii).", "cat": "person" }, { "term": "Peculium quasi castrense", "gloss": "квазилагерен пекулий", "body": "Пекулий (peculium) на подвластен син, който включва придобитото от него имущество на държавна (или на църковна) служба (заплати, възнаграждения, дарения от императора). Това имущество (patrimonium) има същия правен режим като лагерния пекулий (peculium castrense).", "cat": "person" }, { "term": "Peregrini", "gloss": "перегрини, етимологично, този, който е преминал през земите, qui per agros venit", "body": "В класическия период това са свободните жители на римската имерия, които не са нито римски граждани (civis Romanus*), нито латини.", "cat": "person" }, { "term": "Persona", "gloss": "лице", "body": "В буквален смисъл това е актьорска маска (personare – чува се през). Терминът има различно значение в зависимост от различни лица. От правна гледна точка това е означение на човека въобще, включително и робите (servus), чуж- денците (peregrini*) подвластните, които могат да придобиват права и задължения, включително и за чужда сметка. Терминът се използва и за участниците в гражданския процес – persona actoris (ищец) и persona rei (ответник).", "cat": "person" }, { "term": "Plebei", "gloss": "плебеи", "body": "Лица от плебейското съсловие (plebs*), които живеят в Рим, но не са част от фамилиите (срв. gens) на патрициите (patricii*). В по-широк смисъл това са лица от низшите съсловия.", "cat": "person" }, { "term": "Praenomen", "gloss": "лично име", "body": "Първото име на римски граждани, които имат фамилно име (nomen*) и прозвище (cognomen*). С това име се характеризира всяко лице.", "cat": "person" }, { "term": "Procurator", "gloss": "прокуратор, управител", "body": "Овластено лице, което представлява една от страните пред правораздавателния орган (procurator ad litem) или управлява имуществото на друго лице (procurator in rem suam). Виж също cognitor.", "cat": "person" }, { "term": "Prodigus", "gloss": "разточителен", "body": "Лице, което е проявило своята разточителност и по тази причина е поставено под настойничество.", "cat": "person" }, { "term": "Promissio iurata liberti", "gloss": "обещание, поето от освобожденец с клетва", "body": "Вербален договор, който представлява тържествено обещание на освобожденец към неговия патрон да извършва определена работа в негова полза.", "cat": "person" }, { "term": "Pubertas", "gloss": "пълнолетие", "body": "Възраст, при навършването на която едно лице става дееспособно. В архаичното право тя винаги е пълна (и сравнима с гражданската правоспособност на неповластното лице). В класическото право се приема фикцията, че пълнолетието настъпва на 12 г. за момичетата и 14 г. за момчетата.", "cat": "person" }, { "term": "Pupillus", "gloss": "пупил, непълнолетен", "body": "Лице под настойничество.", "cat": "person" }, { "term": "Quirites", "gloss": "квирити", "body": "С това име се наричат римските граждани, обединени в народните събрания. Правото на квиритет е това право, на което се подчиняват само римските граждани.", "cat": "person" }, { "term": "Servitus", "gloss": "робство, сервитут", "body": "Терминът има две значения:\n(1) робство: правен и социален институт на подчиняване на едно лице със статус на роб (servus*) на неговия господар. Робството има за основен източник военните завоевания на други народи (военнопленниците се превръщат в роби), както и раждането от майка – робиня.\n(2) ограничено вешно право (iura in re aliena*), което се състои в обременяване на един имот (наричан „служещ“), с което неговият собственик трябва да търпи действия на ползване от друго лице или да се въздържа сам от ползване в интерес на собственика на съседния имот (наричан „господстващ“). През следкласическия период се различават поземлени сервитути (срв. servitus praediorum*), които са сервитути в стриктен смисъл, и лични сервитути (servitus personarum*), които имат за обект правото на ползване (usus*) или на плодоприбиране (fructus*) върху чужда вещ, които се притежават от едно определено лице, различно от собственика на имота", "cat": "person" }, { "term": "Servitus personarum", "gloss": "лични сервитути", "body": "Сервитути (servitus*), които се състоят в предоставяне на ползването (usus*) или плодоприбирането (fructus*) от определена вещ в полза на едно лице, различно от собственика на поземления имот. Такива са правото на плодоползване (ususfructus*), на обитаване (habitatio*), на работа на роб или освободенец (operae*).", "cat": "person" }, { "term": "Status", "gloss": "статус, правно положение на личността", "body": "Термин за определяне на правното положение на личността в обществото, която се счита за субект на провото, с оглед на притежанието ѝ към определена общност. Различават се три статуса: статус на свободно лице (liber) – status libertatis; статус според притежаването на римско гражданство – status civitatis (срв. civis Romanus); статус на член на фамилията (familia) – status familiae. За да се притежава пълна юридическа правоспособност, едно лице трябва да е свободно, римски гражданин и paterfamilias. Всеки от трите статуса може да бъде променен при наличие на основания за намаляване на правоспособността (capitis deminutio).", "cat": "person" }, { "term": "Sui iuris", "gloss": "неподвластно лице", "body": "Лице, което има пълна правоспособност и дееспособност, т.е. не е под властта (patria potestas*) на друго лице, имащо властта (alieni iuris*).", "cat": "person" }, { "term": "Tres faciunt collegium", "gloss": "необходими са три лица за създаване на сдружение", "body": "Израз, според който римляните изискват обединяване (срв. universitas personarum) поне на три лица, за да може правомерно да възникне сдружението. Вж. също collegia.", "cat": "person" }, { "term": "Tria nomina", "gloss": "трите имена на едно лице", "body": "Система на идентификация на римските граждани, които притежават три имена, т.е лично име (praenomen), фамилно име (nomen) и прозвище (cognomen).", "cat": "person" }, { "term": "Tribus", "gloss": "триба", "body": "Териториално обединение на лицата, като броят на трибите е различен в различните епохи от развитието на римската държава.", "cat": "person" }, { "term": "Tutela", "gloss": "настойничество", "body": "Първоначално по Закона на Дванадесетте таблици (Lex XII [duodecim] tabularum*) се учредява като мярка за защита на евентуални наследници (heres*) на непълнолетното (impubes*) неподвластно (sui iuris*) лице. Настойничеството постепенно става мярка за закрила на неподвластните недееспособни лица (sui iuris*) – за подпомагане на неподвластни непълнолетни лица (tutela impuberum) или на жени (tutela mulierum).", "cat": "person" }, { "term": "Tutela dativa", "gloss": "назначено настойничество", "body": "Вид настойничество (tutela*), при което изборът на настойник (tutor*) е направен от магистрата (magistratus*). По силата на lex Atilia (между 242–186 г. пр.Хр.) градският претор (praetor urbanus*) със съдействието на плебейските трибуни (tribuni plebis*) определя настойник. По-късно има специален претор за това – praetor tutelaris.", "cat": "person" }, { "term": "Tutela legitima", "gloss": "законно настойничество", "body": "Вид настойничество (tutela*), при което настойникът е определен в Закона на Дванадесетте таблици (Lex XII [duodecim] tabularum*) като най-близкия по кръв роднина (proximus agnatus).", "cat": "person" }, { "term": "Tutela mulierum", "gloss": "настойничество над жени", "body": "Настойничество над жените, което е съществувало в древността, но е отпаднало по-късно. Дванадесетте таблици (Lex XII [duodecim] tabularum*) като най-близкия агнат (agnatus proximus; срв. agnatio*), а при липса на такъв – най-близкия по степен член на рода (gentiles*).", "cat": "person" }, { "term": "Tutela testamentaria", "gloss": "настойничество, определено в завещание", "body": "Вид настойничество (tutela*), при което според Закона на Дванадесетте таблици (Lex XII [duodecim] tabularum*), изборът на настойник (tutor*) е направен от paterfamilias като завещател. Той определя в завещанието си (testamentum*) настойници на децата си, които ще станат неподвластни (sui iuris*) след смъртта му.", "cat": "person" }, { "term": "Tutor", "gloss": "настойник", "body": "Лице, което е определено да съдейства и закриля непълнолетния (пупил), което притежава власт (vis ac potestas), подобна на бащината власт (patria potestas*) на paterfamilias*. Настойникът по принцип трябва да бъде римски гражданин или латин, свободен и пълнолетен мъж. По време на късната Империя лудите (furiosus*) и ненавършили 25 г. (minor XXV annorum*), а също и войниците не могат да бъдат назначавани за настойници.", "cat": "person" }, { "term": "Tutor suspectus", "gloss": "недостоен настойник", "body": "Настойник (tutor*), който не може повече да изпълнява тази длъжност по причини, възникнали преди или след номинирането му, по-специално, ако е извършил деяние, довело до значителни загуби на поднастойния поради умисъла (dolus*) или грубата небрежност (culpa lata*) на настойника. Срещу него може да бъде предявен пенален иск (срв. accusatio suspecti tutoris*).", "cat": "person" }, { "term": "Universitas", "gloss": "имущество", "body": "Съвкупност от имуществени вещи, чиято същност е неделимо (срв. res*, res quae ex pluribus inter se distantibus constant).", "cat": "person" }, { "term": "Universitas bonorum", "gloss": "имуществена общност", "body": "Израз за означаване на фондации (piae causae*) или съвкупности от имущества.", "cat": "person" }, { "term": "Universitas facti", "gloss": "фактическа съвкупност", "body": "Израз за означаване на икономически свързани вещи, без да съществува материална връзка между тях (стадо овце, библиотека) (срв. res*, res quae ex pluribus inter se distantibus constant).", "cat": "person" }, { "term": "Universitas iuris", "gloss": "правна съвкупност", "body": "Неримски термин за означаване на съвкупност от права, които се включват в имуществото (patrimonium*) на едно лице и подлежат на разпореждане като едно цяло.", "cat": "person" }, { "term": "Universitas personarum", "gloss": "общност от лица", "body": "Обединение от лица, които създават корпорация – например сдружение (collegia), срв. tres faciunt collegium*.", "cat": "person" }, { "term": "Universitas rerum", "gloss": "съвкупност от вещи, имущества", "body": "Съвкупност от материално обвързани, съставни вещи, чиито части са здраво и физически неделимо свързани, например кораб, къща (срв. res*, res quae ex pluribus se coherentibus constant).", "cat": "person" }, { "term": "Usucapio libertatis", "gloss": "освобождаване по давност", "body": "Обремененият с поземлен сервитут (servitus praediorum*) служещ имот може да се освободи от този сервитут, ако неговият собственик построи нещо или предприеме действия, които пречат на упражняването на сервитута от собственика на господстващия имоти, но последния търпи това определен период от време (две години в класическото римско право, десет или двайсет години в Юстиниановото Право).", "cat": "person" }, { "term": "Vulgata", "gloss": "Вулгата", "body": "Наименование на една от версиите на Дигестите на Юстиниан, която е използвана и възпроизведана в Средните векове, и която по-късно под влиянието на хуманистите от XVI век е заместена с Флорентината (littera florentina). Забележки: В Римското право няма пълно покритие между термина „pupillus“ и използвания в съвременното право термин „непълнолетен“, на което по-точно съответства термина „impuberus“. Поради различието в смисловото съдържание на римския и съвременния термин, с който се означава искът, в учебните курсове се употребяват едновременно и двата термина – „иск“ и „акция“. Паричната кондемнация според Римското право не винаги има функция на договорно обезщетение в съвременен смисъл, поради което е запазено латинизираната терминология. В романистиката съществува дискусия доколко класическите римски юристи са възприемали съществуването на идеални части на съсобствениците по време на съществуване на съсобствеността или те се имат предвид само при делбата на съсобственото имущество. Искът е насочен срещу собственика на вещта, върху която е учреден сервитутът. Авторите възприемат класическото разграничение, според което като „servitus“ се възприема само поземленият сервитут. Затова е направено препращане към този термин. В някои учебни курсове тези искове се превеждат също като „искове с добавъчно качество“, което е буквален превод, или като „искове с тренспозиций“, при което е налице отклонение от римскоправното понятие за сметка на обяснението на процесуалната характеристика на иска. Авторите правят разграничение между подвластните и неподвластните синове – срв. filius familis. По принцип в романистиката се приема предоставянето на пекулий само на подвластни лица. В учебните курсове на български език pater familias обикновено се превежда като домовладелец. но също и като домоначалник, глава на фамилията или се изписва само на латиница. Обикновено наименованието на този иск не се превежда, тъй като то е описателно относно съдържанието на формулата, която се съставя при неговото предявяване. Римската прескрипция като съставна част на формулата няма аналог в съвременното право. Правните режими на настойничеството и попечителството в Римското право се различават в детайли от тези по съвременното право, поради което използването на терминологията в превод е в известен смисъл условно. Неточно в някои случаи те се превеждат като „лични искове“. Римскоправният смисъл на този термин е в съответствие със специфичното понятие за иск (actio), който при вещните искове е насочен към самата вещ, а при облигационните – срещу личността на длъжника. Срв. actiones in rem/actiones in personam. Неточно в някои случаи те се превеждат буквално като „реални искове“. В случая прилагателното „реален“ е производно от римската лексема за вещ – „res“. Има се предвид, че при исковете на добросъвестността съдията има по-голяма свобода на преценка на предявените обстоятелства и факти. Обикновено терминът не се превежда, тъй като в римското право има и друг вид осиновяване – adrogatio. Този вид осиновяване е също с цел осигуряване на наследник по закон на осиновителя и постепенно изчезва с отмирането на функциите на народните събрания (комиции) в областта на частното право. В различните исторически епохи ролята на адвокатите в гражданския и наказателния процес е различна. Тя е по-второстепенна – като помощници на ораторите, по времето на Републиката, но значи- телно нараства по време на Империята. Специализираният защитник се отделя на т. нар. advocati, държавната хазна. От същата епоха, особено ако страните не са в състояние, дидатура. В по-широк смисъл съпругът и съпругата, както и техните дъщери се считат за sui iuris и personae in potestate. Прилагането на извънредни процедури премахва intercessio и provocatio по отношение на дела, свързани по-често с действията на съдиите, отколкото с характера на самия спор. В някои случаи – съдебен сараф. Имущественото състояние не обезпечава правен интерес. Във всички останали случаи, която и да е от страните, може да бъде призована от съда да потвърди текира или фактите. Правните последици от сключване на лични договори при съдебни спорове. Тези изисквания са съществени изисквания, които се изискват в случаите на предявяване на иск. телно нараства в процесите по времето на Империята. Специално внимание в кодификациите се отделя на т. нар. държавни адвокати (адвокати на държавната хазна) – срв. advocatus fisci. От същата листа преторът назначава съдията, ако страните не са постигнали съгласие за обща кандидатура. В по-широк смисъл като подвластни се третират и съпругата, омъжена в брак с manus, неомъжените дъщери и омъжените в брак без manus, а също и personae in mancipio. Прилаганите по времето на Републиката процедури пред народните събрания (комициите) – provocatio ad populum, revocatio ad populum, са свързани предимно с наказателния процес в случаите на съдебна грешка и не представляват по свой характер същинско обжалване В някои случаи се превежда и като лихвар или сараф. Имат се предвид случаите, когато поръчителят не обезпечава целия дълг. Тя се дава на собственика на вещта, върху която е учредена общата ипотека – това може да бъде както самият длъжник, така и трето лице, ипотекирало имущество за обезпечаване на чужд дълг. Римскоправното понятие за имущество е различно от съвременното, до което се доближава по съдържание другия термин – „patrimonium“. Преводът не е прецизен от гледна точка на съвременното право. В повечето учебни курсове изразът се свързва с преторския институт на въвод във владение на имуществото на наследодателя. Има се предвид липсата на специфичен иск за защита. Понякога неточно римският рекс, който е върховен военачалник и висше длъжностно лице, се превежда като „цар“, без да се имат предвид особеностите на структурата и управлението на римската държава в началния период от съществуването ѝ до провъзгласяването на Републиката през 509 г. пр.Хр. Неточно е превеждането в някои случаи на центурията като „стотня“, тъй като броят на лицата, включени в центуриите е бил различен и се е определял според имущественото положение на тези лица. Има се предвид римската гражданска община. Има се предвид източната част на Римската империя. Преводът не е съвсем точен, но от обяснението е ясен смисълът, която се влага в това определение на второто издание на Юстиниановия кодекс По-късно е допустимо и лица със статус на латини (вж. latin*i) да създават колонии. Признаването на ius latii* на колонистите се отразява на техния статус. В някои случаи commercium се определя като правото да се участва в гражданския оборот или като пълна гражданска дееспособност, което обаче не е съвсем точно. В Римското право освен правото да се сключват правни сделки към гражданската дееспособност се включва и правото за сключване на законен римски брак (conubium*) и правото да се съставя или да се получава имущество по завещание (testamenti factio activa vel passiva). Авторите in fine са имали предвид само съдебната компенсация. В случая авторите са имали предвид само смисъла на това понятие в гражданския процес. То се отнася предимно до осъдителните искове. Кондемнацията може да включва както задължение за заплащане на определена сума пари (тогава тя изпълнява функции по обезщетяване на ищеца), за връщане на вещта или за извършване на определено действие в зависимост от вида на предявения иск. Според съвременните схващания, въпреки че договорът за наемане на услуги прилича на договора за наемане на вещи, при него наемателят (работодателят) взема под наем чужда работна сила, за да използва своя труд и да стигне до резултат, като извърши някаква услуга. Според съвременните схващания, въпреки че договорът за наемане на услуги прилича на договора за наемане на вещи, при него наемателят (работодателят) взема под наем чужда работна сила, за да използва своя труд и да стигне до резултат, като извърши някаква услуга. В повечето случаи авторът има предвид възможността за упражняване на власт върху новите придобити вещи. В някои от изложените теории авторите определят сключването на брака като право съгласно правото, което поражда този вид договор. В учебниците по право бракът се определят като съпружеска общност, възникваща вследствие действия, които трябва да бъдат доброволни и без пороци в съгласието. В римското право бракът се разглежда предимно като право на брак и юридическа неизпълнимост на неговите цели в случай на (умисъл) или измама, или при отсъствие на умисъл. на господарската власт. В Римското право, подобно на други правни системи, отношенията между робите и техните господари са строго регламентирани. Според съвременната класификация на договорите това е договорът за изработка, като в позициите на наемателя е изработващият, който сякаш взема под наем чужд материал, за да вложи в него своя труд и да създаде една нова вещ или да извърши някаква услуга. Според съвременната класификация на договорите това е трудовият договор, при който работодателят е наемател на работната сила, т.е. на труда на работника. В повечето учебни курсове се включва и възможността за придобиване на право на собственост върху новата вещ от собственика на главната вещ. В някои учебни курсове като контракти се определят само санкционираните от цивилното право съглашения в съответствие с определението за този вид договори, дадено от класическите юристи. В учебните курсове обикновено те се разглеждат като способи или форми за придобиване на съпружеска власт и се различават от ритуалите и действията за сключване на брак, който може да бъде и без manus. В Римското право като culpa се има предвид предимно небрежността, за разлика от умишленото неизпълнение или увреждане, означавано като dolus (умисъл, но също и измама) или dolus malus (злоумисъл). В случая той се явява фактически в позицията на пряк представител на лицето под настойничество. В Римското право обаче не е съществувало понятие, няма и специални термини за означаване на прякото представителство. Обикновено това се обяснява с възможността робите и подвластните фактически да действат като преки представители на домовладелеца (paterfamilias*). Става въпрос за публичноправен договор, който не е в писмена форма поради факта на военна- та капитулация на противника, но е сключен с произнасяне на определени тържествени изрази. Той се различава от вербалните договори в частното право – вж. stipulatio*\nНастойникът действа като пряк представител на закриляното лице.\nВ учебните курсове демонстрацията се определя и като съществена част на формулата при някои видове искове.\nПостепенно се използва възможността за продължаване на срока на диктатурата, което води до промяна на същността на тази магистратура в Късната Република.\nВ източниците се разграничава правото на собственост върху робите от властта, която се упражнява върху тях. В романистиката се акцентира и върху социалния аспект на dominica potestas.\nПри емфитевзата рентата се нарича още „canon“ или „emphyteuma“.\nВ някои текстове като exercitor се определя роб или подвластен на корабособственика, който е натоварен с функции по управление на извършваните с кораба превози и сключването на сделки във връзка с това.\nНякои автори считат тази система на правото за идентична на ius civile*, според други това е най-древното право на римските граждани, което е в основата на ius civile.\nСъщия вид кражба осъществява и залогоприемателят, който ползва заложената вещ преди или след падежа, без да я предлага на публична продан. Срв. pignus*\nВ учебните курсове imperium се разглежда и като висша административна и съдебна власт.\nНаименованието на интердикта е според началния израз, с който започва преторската заповед и се отнася само за недвижими вещи. началния израз, с който започва преторската заповед и се отнася само за недвижими вещи.\nПредставен в правната теория във връзка с концепциите на германската и швейцарската школа, за развитието на правото се е отдалечила от догматичното съотношение между владение и собственост.\nНякои автори предлагат сравнително правно-историческо изследване, тъй като в много от предходните народните събрания, както и в другите, но и в съвременните личноправни и вещноправни отношения, осиновяването има сходен характер.\nОсобено внимание се отделя на търсващите форма на социална справедливост, които често чрез облекло, жестове или дори с жестовете на вежливост, маскират дребната кражба или измамата. Особено се акцентира върху разграничението на Таблиците от XII.\nчесто в правната практика не се ограничава само до тези обстоятелства, нямащи нищо общо с добросъвестността\nи съществени морални категории, като например в отношенията между наследниците, морални съображения, които са важни за решаване на спорни въпроси. Наименованието на интердикта е според началния израз, с който започва преторската заповед и се отнася само за движими вещи. Представеното определение от авторите е във връзка с концепцията за владението във френското и швейцарско законодателство, която в резултат на развитието на юриспруденцията през вековете се е отдалечила от класическото римско схващане за съотношението между владение (possessio*) и право на собственост (dominium*). Някои автори го определят като активно избирателно право, което е по-тясно по своето съдържание, тъй като римските граждани, участвайки в народните събрания, не само са избирали магистратите, но и са гласували по редица въпроси от публичноправен или частноправен характер (завещания, осиновявания и др.). Особените изисквания за външния вид на претърсващия са били продиктувани от съображения за справедливост – държейки съд в ръце и с оскъдно облекло, той не е могъл да внесе привидно откраднатата вещ и да я подхвърли в дома на обвинения в кражба. Във връзка с тази процедура някои автори акцентират на зачитания още в Закона на XII-те Таблици принцип на неприкосновеност на жилището. Това наименование е условно и поради това често се поставя в кавички, тъй като римският рекс няма правомощията на монарха, определян като цар. Imperium се схваща и като висша гражданска и съдебна власт. Тук авторите акцентират на военната власт, защото само магистрати с империум могат да предвождат римската войска и това е най-важният елемент от тази власт. Въз основа на този закон запазената част от наследството се нарича и в съвременното наследствено право „фалцидиева четвърт“. Преди въвеждането на паричното обръщение късчето бронз е имало функцията на прачен еквивалент. дент и неговото тегло всъщност е била цената на недвижимия имот. В текста по-долу mancipium има и друго съдържание, но в случая авторите са го употребили само във връзка с манципацията. Някои автори считат, че manus се упражнява само от съпруга, а неговият paterfamilias има само patria potestas по отношение на снаха си. В някои случаи муниципията се превежда и като община или град, които имат самоуправление. Има се предвид както териториалната, така и социалната общност, която е автономна в различна степен от Рим. Има се предвид, че за част от едно и също наследствено имущество не може да има наследник по завещание, а за останалата част да се открие наследяване по закон. Принципът има разширено приложно поле във вещното право, като недопуска промяна на основанието на владението от самия владелец. В учебните курсове се подчертава връзката на института с дълговото робство, при което длъжниците са превръщани в роби – nexi. В класическия период в имуществото се включват и задълженията, т.е. пасивите. Някои автори считат, че при залога се прехвърля само държане, но защитено по целесъобразност с владелчески интердикти. В повечето учебни курсове те се определят като държатели, на които по целесъобразност е предоставена владелческа защита. Приема се, че фидепромисията е достъпна и за чужденци. В романистиката терминът „интестатно наследяване“ се използва като синоним на наследяването по закон, т.е. прилагането на принципа, че наличието на завещание изключва наследяването по закон. Придобили суперфициар върху спорно за класическите юристи, утвърждава в следващите. В класическото римско право остава наемател на земята, строи постройка и заплаща рента, това се запазва действащо чрез приращението. Сакралната форма на обвързване на съпрузите, съвместно съжителство. По-често се използва за държавната и провинциалната земя. Придобиването на правото на собственост от суперфициаря върху построената от него сграда е спорно за класическите юристи, но постепенно се утвърждава в следващите епохи. В класическото римско право суперфициарят остава наемател на земята, върху която е изградил постройка и заплаща рента, наречена sularium. С това се запазва действието на принципа за присъединяването чрез приращение. Сакралната формула изразява взаимното обвързване на съпрузите и задължението за съвместно съжителство и следване. По-често се използва по отношение на бонитарната и провициалната собственост.", "cat": "person" }, { "term": "Actio rei uxoriae", "gloss": "иск относно имуществото на съпругата /зестрата/", "body": "Облигационен иск (actiones in personam*), предоставен на жената или на нейните наследници срещу съпруга или неговите наследници за връщане на зестрата (dos*), като се задържат някои вземания (retentiones*) на мъжа. Искът се предявява след прекратяване на брачната връзка (при развод или смърт на съпруга).", "cat": "family" }, { "term": "Adoptio", "gloss": "адопция, осиновяване", "body": "Процедура на осиновяване, при която бащината власт върху подвластното лице (alieni iuris*) преминава от домовладелеца (paterfamilias*) върху осиновителя.\nЮстиниан различава:\n- adoptio minus plena (непълна адопция): най-разпространеният начин на осиновяване, при който осиновеният не излиза от фамилията си по произход и чийто единствен ефект е да се създаде наследник по закон (ab intestato) на осиновителя;\n- adoptio plena (пълна адопция): начин на осиновяване, при който окончателно се прекъсва връзката на родство и власт на домовладелеца (paterfamilias*) с осиновеният, в резултат на което осиновеният влиза в семейството и попада изцяло под властта на осиновителя.", "cat": "family" }, { "term": "Affectio maritalis", "gloss": "съпружеска вярност, съпружеска обич, отношение между съпрузите", "body": "Обща и трайна воля на две лица да живеят като съпрузи. Тази воля е необходима за създаването и запазването на брачния съюз.", "cat": "family" }, { "term": "Agnati", "gloss": "агнати", "body": "Група лица, обединени от връзка на агнатство (agnatio*).", "cat": "family" }, { "term": "Agnatio", "gloss": "агнатство, от ad-nasci „раждам се след“", "body": "Система на родство по цивилното право, според която роднини са само лицата, които се намират под една и съща фамилна власт или са се намирали под нея докато paterfamilias* е бил жив.", "cat": "family" }, { "term": "Bonus paterfamilias", "gloss": "добросъвестен, добър стопанин", "body": "Израз, използван за определяне на степента на дължимата грижа (diligentia*), която длъжникът може да осъществи. Тя съответства на степента на внимание и умение, които се притежават от обикновения човек, действащ според предписанията на добросъвестността (bona fides*).", "cat": "family" }, { "term": "Civis Romanus", "gloss": "римски гражданин", "body": "Така се наричат квиритите (Quirites). Това определение се отнася първоначално само за жителите на Рим, а по-късно и до цялата област Лациум. През 212 г. сл.Хр. конституцията на император Каракала (Constitutio Antoniniana) дава римско гражданство на всички жители на Римската империя с изключение на дедитициите (dediticii). Римското гражданство се състои от множество права и задължения за гражданите. Правото на пълно гражданство включва граждански права като например правото да се сключва законен римски брак (conubium) и да се извършват правни действия (commercium), както и политически права като правото да се гласува (ius suffragii) и правото да бъде избиран за магистрат (ius honorum).", "cat": "family" }, { "term": "Cognatio", "gloss": "когнатство, кръвно родство", "body": "Връзка на родство, която обединява лица, които по мъжка или по женска линия имат един общ прародител и които са част от едно и също семейство (кръвно родство). Този вид родство се различава от това, създадено въз основа на агнатство (agnatio*).", "cat": "family" }, { "term": "Cognatus", "gloss": "когнат", "body": "Роднина по бащина или майчина линия, с когото съществува кръвно-родствена връзка (cognatio*).", "cat": "family" }, { "term": "Confarreatio", "gloss": "конфареация", "body": "Начин на придобиване на съпружеска власт (manus*) от бъдещия съпруг върху неговата съпруга. Конфареацията е един свещен религиозен и тържествен акт за сключване на брак с manus (matrimonium cum manu*), който се използва от патрицианските семейства (patricii*) и от някои жреци. За церемонията се приготвя специален обреден хляб (farreus).", "cat": "family" }, { "term": "Conubium или ius conubii", "gloss": "брачна дееспособност", "body": "Способност да се сключва валиден брак (matrimonium iustum*), т.е. да се създаде валидна брачна връзка. Това право се дава на римските граждани (civis Romanus*), но също и по отношение на латини (Latini*), а по-късно – и на перегрини (peregrini*). Робите имат само контуберниум (contubernium*).", "cat": "family" }, { "term": "Conventio in manum", "gloss": "попадане под manus", "body": "Попадане на пълнолетната съпруга под властта на своя съпруг, който е неподвластен (persona sui iuris*), във връзка с брак cum manu (matrimonium cum manu*); това попадане под manus може да се осъществи въз основа на три различни действия: usus maritalis*, coemptio* или confarreatio*.", "cat": "family" }, { "term": "Detentio", "gloss": "детенция, държане", "body": "Израз, използван за определяне на положението на т.нар. естествен владелец, който няма правно защитено владение за разлика от интердиктия (ad interdicta) владелец (срв. ssessio ad interdicta*).", "cat": "family" }, { "term": "Dictator", "gloss": "диктатор", "body": "По време на републиката магистрат (magistratus*), който е облечен от консулите (consules*) с пълната военна, административна и съдебна власт и встъпва в изключително тежки обстоятелства (извънредна ситуация) за държавата само за период от шест месеца. (repidium — натъжване): с прекратяването на съвместния съпружески живот се слага край на брака и от този момент насетне не може да се претендира съществуването на брачно обвързване (и намерение страните да се представят като съпрузи) (affectio maritalis*). Разводът е съпроводен често с произнасянето на определен израз в смисъл „Вземи си своите вещи (tibi res tuas habeto).", "cat": "family" }, { "term": "Diffarreatio", "gloss": "дифареация", "body": "Религиозна церемония в случаите на прекратяване на брака, която има за цел да прекрати съпружеската власт (manus*) върху съпругата. Прилага се в случаите, когато manus е установен чрез церемонията на конфеерация (confarreatio*).", "cat": "family" }, { "term": "Divortium", "gloss": "развод", "body": "Разторгване на брачната връзка. Разводът се извършва по определена форма и без съдебно решение. Той произтича от взаимното съгласие на страните, или пък въз основа на едностранно волеизявление на една от двете страни ния на абсолютна власт върху една вещ. Dominium е термин, който изразява най-характерната черта на правото на собственост.", "cat": "family" }, { "term": "Domus", "gloss": "дом", "body": "Фамилна общност, която се състои от домовладелец (paterfamilias) и всички, които са под неговата власт (patria potestas). Първоначално в древната епоха всички са живели под един покрив.", "cat": "family" }, { "term": "Dos", "gloss": "зестра", "body": "Имуществени блага, предоставени от бащата или дядото на бъдещата съпруга (paterfamilias*), както и от самата неподвластна съпруга (sui iuris*) или от трето лице на бъдещия съпруг, с цел да се облекчи тежестта по издръжката на жената и на децата в семейството. Зестрата има за цел също така да осигури издръжката на жената след прекратяване на брака и по тази причина тя трябва да й бъде върната (срв. actio rei uxoriae*).", "cat": "family" }, { "term": "Dotis datio", "gloss": "прехвърляне на правото на собственост върху зестрата [dos*]", "body": "Един от начините за учредяване на зестра в римското право, който трябва да се различава от dotis dictio. Dotis datio може да се осъществи чрез манципация (mancipatio*), или чрез привиден процес (in iure cessio*) по отношение на манципни вещи res mancipi* или чрез традиция (traditio*) за неманципни вещи res nec mancipi*", "cat": "family" }, { "term": "Dotis dictio", "gloss": "обещание за зестра [dos*]", "body": "Един от начините на създаване на зестра, заедно с dotis datio. Dotis dictio се състои в тържествено вербално задължение, (вж. obligationes verbis contracta*) за даване на зестра, поето от лицето, което ще предостави съответното имущество.", "cat": "family" }, { "term": "Emancipatio", "gloss": "еманципация", "body": "Процедура, чрез която домовладелецът (paterfamilias*) добросъвестно се отказва от бащината власт (patria potestas*) върху своя подвластен син, с което му дава възможност да промени своя статус от подвластно в неподвластно лице (sui iuris*).", "cat": "family" }, { "term": "Familia", "gloss": "фамилия, семейство", "body": "В класическото римско право, според патриархалните схващания, фамилната власт включва всички лица, които са подчинени на властта на владеене на една вещ (possessio*), било защото недобросъвестно е изоставил вещта или пък погрешно е считан за владелец (с цел да се увреди ищеца, „dolus pro possessione“).", "cat": "family" }, { "term": "Filia familias", "gloss": "повластна дъщеря", "body": "Дъщеря, която е под властта на своя баща или на негов възходящ родственик (patria potestas*).", "cat": "family" }, { "term": "Filius familias", "gloss": "повластен син", "body": "Син, който е подвластен на своя баща или на негов възходящ родственик (patria potestas*).\nFlumen publicum (публична река)", "cat": "family" }, { "term": "Genus", "gloss": "род", "body": "Термин за определяне на вещи от един и същи род, включително и такива, които по волята на страните са определени с техните общи характеристики, без да се индивидуализирани. Виж родови задължения (obligatio ad genus pertinet).", "cat": "family" }, { "term": "Ius conubii", "gloss": "брачна дееспособност", "body": "Право на сключване на законен брак (matrimonium*) според римските закони (ius civile*). Първоначално това право е принадлежало само на римските граждани, а по-късно е предоставено и на други общности. Съществуването на conubium* е предпоставка за валидността на брака.", "cat": "family" }, { "term": "Lex Papia Poppaea", "gloss": "nuptialis", "body": "Закон, гласуван през 9 г. сл.Хр., който частично възпроизвежда нормите от lex Iulia de maritandis ordinibus*. С него се задължават мъжете на възраст от 25 до 60 години и жените на възраст от 20 до 50 г. да сключват брак или да се сгодят. Ако някой от съпрузите почине, както и при развод (divortium*), преживелият съпруг или разведените съпрузи трябва да сключат нов брак в определен срок, който е различен за отделните епохи (vacatio). Lex Publilia de sponsu\nЗакон, датиран към 150 г. пр.Хр. и приложим за архаичните форми на поръчителство (срв. fidepromissio* и sponsio*), който позволява поръчителят, платил дълга, да извърши принудително изпълнение върху личността на длъжника (manus iniectio*), ако той не му върне платеното в шестмесечен срок. Lex Rhodia de iactu\nЗакон, свързан с морската търговия в Средиземноморието и вероятно произхождащ от остров Родос, който е датиран към 30 г. пр.Хр. Според него в случай на необходимост от спасяване на кораба по време на буря може да се изхвърли през борда част от товара в морето. Тогава собствениците на останалите на кораба стоки заедно с корабния предприемач (exercitor*) трябва да обезщетят пропорционално, според загубите, собствениците на пожертваните стоки.", "cat": "family" }, { "term": "Liberi", "gloss": "деца", "body": "Непосредствени низходящи на определено лице, независимо дали са под или извън бащината власт (patria potestas*).", "cat": "family" }, { "term": "Manus", "gloss": "„ръка“, символ на власт, надмощие", "body": "Първоначално с този термин се означава абсолютно господство на paterfamilias* върху членовете на неговата (familia*). В следващата епоха с него се означава само властта на съпруга върху омъжената за него в брак cum manu жена (срв. matrimonium cum manu* и manus maritalis*).", "cat": "family" }, { "term": "Manus maritalis", "gloss": "съпружеска власт).", "body": "Власт, която съпругът, ако самият той е неподвластен (sui iuris*), или неговият paterfamilias*, ако е подвластен (alieni iuris*), упражнява върху съпругата в брак cum manu (matrimonium cum manu*).", "cat": "family" }, { "term": "Mater familias", "gloss": "майка на фамилията", "body": "Термин за означаване на майката на фамилията, която е юридически самостоятелна и напълно правоспособна (sui iuris*).", "cat": "family" }, { "term": "Matrimonium", "gloss": "брак", "body": "Фактическо състояние със социално значение, при което мъж и жена изразяват взаимната си воля (affectio maritalis*) да се отнасят помежду си като съпрузи и да живеят съвместно.", "cat": "family" }, { "term": "Matrimonium cum manu", "gloss": "брак с manus", "body": "Най-старата форма на римски брак, при който жената прекъсва връзката със своите агнати (agnatio*) от семейството по произход и преминава под властта (manus*) на своя съпруг или на неговия paterfamilias*. Установяването на manus става чрез conventio in manum*.", "cat": "family" }, { "term": "Matrimonium iustum", "gloss": "законен римски брак", "body": "Брак, който отговаря на изискуемите форми за валидност и най-вече който предполага наличието на римска брачна дееспособност (conubium*).", "cat": "family" }, { "term": "Matrimonium sine manu", "gloss": "брак без manus", "body": "Форма на брака, която става всеобща от I в. сл.Хр., при която жената, която се омъжва, не губи връзката със своите агнати (agnatio*) от семейството по произход и запазва статуса си на подвластна (alieni iuris*) на своя paterfamilias или на неподвластна (sui iuris*), ако преди брака е еманципирана (emancipatio*) от своя paterfamilias*.", "cat": "family" }, { "term": "Matrona", "gloss": "матрона", "body": "Термин за означаване на mater familias*, която има достолепно поведение.", "cat": "family" }, { "term": "Partus", "gloss": "дете, зародиш", "body": "Дете (infans*), което все още не е родено, но вече се счита, че има статус на лице и някаква правна сфера, но не е родено. Не е лице, но има определени права (срв. nasciturus*).", "cat": "family" }, { "term": "Paterfamilias", "gloss": "домовладелец, глава на фамилията", "body": "Домовладелецът (paterfamilias) е неподвластно лице (sui iuris*), което упражнява власт (patria potestas*) върху включените във фамилията лица (familia*), и което не е подчинено на властта на свой пряк възходящ по бащина линия.", "cat": "family" }, { "term": "Patria potestas", "gloss": "бащина власт", "body": "Специфична правна връзка между бащата (paterfamilias*) и неговите деца. правна способност, ако се роди живо и нормално. Нероденото дете временно има някакви права (срв. nasciturus*).", "cat": "family" }, { "term": "Praesumptio Muciana", "gloss": "", "body": "Правна презумпция (praesumptio iuris*), създадена от юриста Q. Mucius Scaevola, по силата на която се предполага, че придобитото от съпругата имущество по време на брака (matrimonium*), чийто произход не може да се докаже от съпруга, е дадено от него като дарение.", "cat": "family" }, { "term": "Promissio dotis", "gloss": "обещание за зестра", "body": "Учредяване на зестра с неформално обещание, за разлика от dotis dictio.", "cat": "family" }, { "term": "Remancipatio", "gloss": "реманципация", "body": "Обратен на манципацията (mancipatio) акт, с който приобретателят връща получената вещ или лице на отчуждителя. Това се отнася и до връщането на подвластното лице (alieni iuris). поставено под властта (mancipium) на приобретателя, на неговия домовладелец (paterfamilias), който да го еманципира (emancipatio). Същата процедура се използва и отношение на омъжената в брак с manus жена (срв. matrimonium cum manu), която в момента на развода (divortium) трябва да се освободи от manus и да се върне под властта на своя paterfamilias.", "cat": "family" }, { "term": "Res uxoriae", "gloss": "зестрално имущество", "body": "Имущество, придобито от съпруга в резултат на учредяване на зестра (dos*) или в резултат на придобиване на съпружеска власт (manus*). То трябва законно да се върне на съпругата при прекратяване на брака чрез развод (divortium*) или при смърт на съпруга. Жената разполага със специален иск (actio rei uxoriae*) за връщане на зестриалното имущество.", "cat": "family" }, { "term": "Retentiones dotis", "gloss": "задържане на част от зестрата", "body": "Израз за означаване на правото на съпруга при прекратяване на брака (divortium*), да задържи част от зестрата (dos*), върху което му е прехвърлено правото на собственост (dominium*) по повод на брака (matrimonium*). Размерът на това имущество е определено в проценти въз основа на различни критерии, най-често във връзка с вината на съпругата за прекратяване на брака. Различават се следните видове задържане на зестрата:\n– propter impensas (част, свързана с разходите): за разходите, направени от съпруга за запазване или увеличаване стойността на зестрата;\n– propter liberos (част, свързана с децата): съответства на 1/6 част за всяко дете, но не повече от 1/2 от зестрата, ако жената е виновна за развода;\n– propter mores (част, свързана с обичая): съответства на 1/6 част, ако има голямо нарушение (прелюбодеяние на жената) и 1/8 част при по-малки нарушения (сводничество (lenocinium) и т.под.) на обичая и обществения морал;\n– propter res amotas (част, свързана с отнетите от съпруга вещи): съответства на стойността на вещите, които жената вече е взела от съпруга си при развода, като своеобразна гаранция за тяхното връщане;\n– propter res donatas (част, свързана с направени дарения между съпрузите): съответства на стойността на подарената от съпруга вещ (срв. donatio*), тъй като даренията между съпрузите са нищожни, а с това жената се е обогатила.", "cat": "family" }, { "term": "Si pater ter filium venum duit, filius a patre liber esto", "gloss": "ако бащата три пъти продаде сина си, нека синът бъде свободен от властта на бащата", "body": "Основно правило в Закона на Дванадесетте таблици (Lex XII [duodecim] tabularum*), според което с трикратното отчуждаване на подвластния син от неговия paterfamilias* той окончателно се освобождава от бащината власт - patria potestas*. По-късно правилото се адаптира за извършване на еманципация (emancipatio*) на всички подвластни (alieni iuris*) от техния домовладелец (paterfamilias*). Вж. mancipium*.", "cat": "family" }, { "term": "Sponsalia", "gloss": "годеж", "body": "Обещание за брак, което се поема с вербален договор (sponsio*) или с простото съгласие на двамата домовладелци, или между домовладелеца (paterfamilias*) на годеницата и самия годеник в различните епохи. В класическия период при учредяването на зестрата се предполага мълчаливото съгласие на домовладелеца (paterfamilias*) на годеницата.", "cat": "family" }, { "term": "Tollere liberos", "gloss": "вдигам деца", "body": "Формален акт на бащата да признае новороденото, като го вдигне и го стрира в семейството, с което се придобива бащинство.", "cat": "family" }, { "term": "Tollere liberum", "gloss": "да се издигне детето", "body": "Формален акт, с който paterfamilias* издига новороденото дете, като по този начин демонстрира включването му във фамилията и придобиване на patria potestas* върху него С този термин се определят две различни правни фигури, които понякога се допълват взаимно:", "cat": "family" }, { "term": "Ubi tu Gaius, ego Gaia, ubi tu Gaia, ego Gaius", "gloss": "където си ти, Гай, и аз ще бъда Гая, където си ти и Гая, и аз ще бъда Гай", "body": "Формула, произнасяна по време на брачния ритуал (matrimonium*) от всеки от съпрузите.", "cat": "family" }, { "term": "A non domino", "gloss": "от несобственик", "body": "Израз, използван в случаите, в които едно лице придобива вещ от несобственик. По изключение придобителят може да стане собственик (dominus*) на вещта чрез придобивна давност (usucapio*).", "cat": "thing" }, { "term": "Accessio principali cedit", "gloss": "второстепенната вещ следва режима на главната", "body": "Основен принцип, който определя режима на присъединяването (accessio*), според който собственикът на главната вещ придобива право на собственост върху второстепенната. Едно допълнение от Средните векове потвърждава същата идея: „Accessorium naturam sequi congruit principalis“. Вж. също правилото superficies solo cedit*.", "cat": "thing" }, { "term": "Accessoria", "gloss": "второстепенни/акцесорни/вещи", "body": "Движими вещи, предназначени (propter) за ползване или за трайно обслужване на една главна вещ (res*).", "cat": "thing" }, { "term": "Accipiens", "gloss": "приобретател", "body": "Лице, което придобива право на собственост в резултат на traditio* или на mancipatio* (mancipatio accipiens*).", "cat": "thing" }, { "term": "Adiunctio", "gloss": "присъединяване, адюнкция", "body": "Оригинерен /първичен/ способ за придобиване на право на собственост (dominium*) под формата на сливане (accessio*) на две движими вещи, който се осъществява, когато една движима вещ (считана за второстепенна) се свързва с друга движима вещ (считана за главна) по начин двете да представляват едно цяло.", "cat": "thing" }, { "term": "Adplumbatio", "gloss": "адпломбация, запояване, заваряване", "body": "Хипотеза за свързване на материали, принадлежащи на две различни лица чрез пломбиране. Тя се различава от случаите на спояване с желязо (ferruminatio*), където от правна гледна точка има сливане на двата материала (на движимите вещи), тъй като те не могат да се отделят. Тук няма сливане (accessio*) на двата материала (на движимите вещи), тъй като те могат да се отделят без да се накърни обектът, с който са свързани. Собственикът на материала, който притежава новата вещ, към която са прикрепени частите, чрез иск за връщане на една вещ (actio ad exhibendum*).", "cat": "thing" }, { "term": "Aes", "gloss": "бронз", "body": "Метал, първоначално използван под формата на необработени слитъци, след това като отсечени от държавата монети, които са били единствени в употреба в Рим до въвеждането на сребърните монети.", "cat": "thing" }, { "term": "Aes et libra", "gloss": "бронз и везни", "body": "Слитък бронз и везни, които трябва да са налични и да се използват за валидността на някои формални юридически актове, наричани либрални (per aes et libram*), напр. манципацията (mancipatio*).", "cat": "thing" }, { "term": "Ager publicus", "gloss": "публични земи", "body": "Поземлен фонд, принадлежащ на римския народ, който е изключен от придобиване на квиритска собственост върху него в полза на частни лица (dominium ex iure Quiritium*).", "cat": "thing" }, { "term": "Ager vectigalis", "gloss": "вектигален имот, имот за който се плаща поземлен данък или рента", "body": "Особена форма на концесия за обработване на публични земи (ager publicus*) от частни лица. Концесията е дългосрочна или с неограничен срок и изисква бенефициентът да поддържа и подобрява земите и да заплаща рента или данък, наречен вектигал (vectigalium*).", "cat": "thing" }, { "term": "Agere", "gloss": "водя дело пред съд", "body": "Дейност на юристите (iurisconsulti*), състоящата се в даване на съвети на страните по избора на процедура или процесуална стратегия, но без явяване и пледиране пред съда като оратор-адвокат (advocatus*).", "cat": "thing" }, { "term": "Alluvio", "gloss": "алувий, нанос", "body": "Случай на присъединяване (accessio*) на две недвижими вещи, при който има оригинерно /първично/ придобиване на право на собственост в резултат на добавяне на речни наноси към един имот, които стават част от него с трайното им закрепване и постепенно го увеличават по размер.", "cat": "thing" }, { "term": "Animus derelinquendi", "gloss": "намерение за изоставяне", "body": "Воля за неотменимо и неотменно изоставяне на собствена вещ; вж. res derelictae*.", "cat": "thing" }, { "term": "Animus possidendi", "gloss": "намерение за владеене", "body": "Намерение за установяване на владение (possessio*) върху една вещ.", "cat": "thing" }, { "term": "Avulsio", "gloss": "нанос", "body": "Случай на съединяване (accessio) на два недвижими имота, при който се придобива право на собственост (dominium) по деривативен (производен) начин. При него част от земята от един участък е отнесена от водата и се закрепва към другия имот. Добавените трайно части се придобиват от собственика на имота, към който те са присъединени.", "cat": "thing" }, { "term": "Bona", "gloss": "имущество", "body": "Съвкупност от блага, които принадлежат на едно лице, като се отделят от тях дълговете.", "cat": "thing" }, { "term": "Brevi manu traditio", "gloss": "прехвърляне на владение на „къса ръка“", "body": "Опростен начин на прехвърляне на владение (possessio*) без материално /фактическо/ предаване на вещта, чрез което при наличие на правно основание държателят на една вещ (detentio*) става неин владелец.", "cat": "thing" }, { "term": "Causa", "gloss": "кауза", "body": "Смисълът, в който се използва терминът „causa“, е нееднозначен. Могат да се споменат най-важните значения:\n- при традицията (traditio*), каузата е всъщност основанието за прехвърляне на правото за собственост, което мотивира и определя преминаването на собствеността и е свързано с предаването на владението върху вещта;\n- при придобивната давност (usucapio*), каузата е правното основание, правният акт, с който лицето, за което тече давността, придобива вещта;\n- при договорите или във връзка с плащането по тях causa е непосредствената цел, към която е насочено договарянето на страните или изпълнението на престацията: напр. кауза с цел плащане (solvendi causa) или с цел дарение (donandi causa);\n- при неоснователното обогатяване causa е мотивът (или самият правен акт), който обуславя прехвърлянето на сума или друга престация в имуществото на приобретателя (accipiens*) без основание (sine causa) и води до неоснователното обогатяване (срв. напр. condictio indebiti*).", "cat": "thing" }, { "term": "Cautio usufructuaria", "gloss": "гаранция при плодоползване", "body": "Обещание, гаранция, дадена от плодоползвателя (usufructuarius*) по искане на претора (praetor*). Плодоползвателят се задължава чрез стипулация (stipulatio*) да се ползва от обекта на плодоползването (ususfructus*) като добър стопанин (bonus paterfamilias*) и да върне след изтичане на срока на плодоползването цялото имущество, което е останало. Вж. също понятието за гаранция при плодоползването (satisdatio usufructuaria*).", "cat": "thing" }, { "term": "Cessio bonorum", "gloss": "отстъпване, прехвърляне на имуществото", "body": "Това е отстъпване на цялото имущество на неплатежоспособния длъжник на неговите кредитори, за да го подложат на публична продажба и да се удовлетворят от получената продажбата цена. Това прехвърляне помага на длъжника да избегне инфамиращите последици на процедурата за разпродажба на имуществото му (bonorum venditio*).", "cat": "thing" }, { "term": "Commercium", "gloss": "право или способност да се извършват правни сделки", "body": "Право, което е предоставено предимно само на римските граждани (civis Romanus*) да сключват правни сделки, като използват различни юридически форми според цивилното право (ius civile*), също да извършват манципация (mancipatio*), да стават квиритски собственици (срв. dominium ex iure Quiritium*), или пък да използват правните средства въз основа на легисакциите (legis actiones*).", "cat": "thing" }, { "term": "Commixtio", "gloss": "смесване", "body": "Това е една особена форма на смесване (confusio*), при която се придобива право на собственост в случаите на смесване на суми пари, които принадлежат на различни собственици. В резултат на това различните суми са смесени по начин, че не могат да бъдат идентифицирани и те принадлежат на този, който ги е приел и който ги е смесил със своите собствени пари. По тази причина се казва, че „парите са в ръцете на този, който ги притежава“.", "cat": "thing" }, { "term": "Confusio", "gloss": "смесване", "body": "Терминът има три различни значения:\n(1) Начин на първично (оригинерно) придобиване на правото на собственост (dominium*), който предполага смесване на течности, на твърди вещества или пък смесване на метали, които принадлежат на различни собственици. Когато разделянето на смесените елементи не е възможно, новата вещ остава съпритежание на собствениците на елементите, които са смесени.\n(2) Начин на погасяване на ограничено вещно право (iura in re aliena*), когато едно лице става титуляр на правото на собственост и на ограничено вещно право на една върху същата вещ.\n(3) Начин на погасяване на облигационно отношение в хипотезата, когато едно лице придобива /при наследяване или изкупуване на дълга/ качеството едновременно на длъжник и на кредитор за един и същи дълг.", "cat": "thing" }, { "term": "Constitutum possessorium", "gloss": "владелчески конститут", "body": "Опростен начин на прехвърляне на владение (possessio*) без материално предаване на вещта, при който вещта остава в ръцете на владелеца, който я притежава на предходно основание като държател (detentio); това е случаят, в който едно лице прави в писмена форма дарение на поземлен имот на трето лице и след това го наема от същото това лице.", "cat": "thing" }, { "term": "Corpore possidere", "gloss": "притежание с фактически действия, с телесно въздействие върху вещта", "body": "Означава състоянието на лицето, което владее една вещ (possessio) чрез осъществяване на ефективна власт върху нея (corpus); това лице има фактическата власт върху вещта.", "cat": "thing" }, { "term": "Corpus", "gloss": "тяло, материален елемент", "body": "Означава фактическото действие, фактическата власт на владелеца върху вещта; corpus (заедно с animus) е един от двата конститутивни елементи на владението (possessio).", "cat": "thing" }, { "term": "Derelictio", "gloss": "изоставяне", "body": "Начин на погасяване на правото на собственост (dominium*), който се състои в изоставянето на една вещ (res derelictae*), която от този момент насетне би могла да бъде обект на завладяване от всяко трето лице (occupatio*).", "cat": "thing" }, { "term": "Dominium", "gloss": "власт, собственост", "body": "Включва в най-общ план (в следкласическия смисъл на понятието) съвкупността от отношение. насрещна престация предоставянето на правото на собственост върху друга вещ. Типичният случай е замяната (permutatio*).", "cat": "thing" }, { "term": "Dominium ex iure Quiritium", "gloss": "квиритска собственост или собственост според правото на римските граждани", "body": "Правото на собственост (ius civile), което притежават само римските граждани (civis Romanus), и което предоставя на своя титуляр абсолютната власт на ползване и разпореждане с вещта, която е обект на това право. Вж. също ius Quiritium.", "cat": "thing" }, { "term": "Dominus", "gloss": "господар, собственик", "body": "Термин, използван в две различни значения:\n(1) титуляр на правото на собственост (срв. dominium и dominium ex iure Quiritium), също така и господар един роб (servus).\n(2) титла, използвана от римските императори в епохата на домината (Dominatus).", "cat": "thing" }, { "term": "Emphyteusis", "gloss": "емфитевза", "body": "Договор, който от времето на император Зенон (477-484 г. сл.Хр.) се сключва като просто съглашение между собственика на недвижим имот и едно лице, наречено емфитевт (emphyteuticarius), с което емфитевтът поема задължението да обработва имота за неопределен период от време и да плаща ежегодна рента (pensio). Правото да се ползва имота е подчинено на изискването той да се обработва.", "cat": "thing" }, { "term": "Ex iure Quiritium", "gloss": "по силата на квиритското право/правото на римските граждани", "body": "Израз, използван за определяне на правоотношенията, уреждани според приложимото за римските граждани (civis Romanus) право, т.е. така нареченото право на квиритите (ius Quiritium).", "cat": "thing" }, { "term": "Ferae bestiae", "gloss": "диви зверове", "body": "Считани за безстопанствени животни (res nullius*), върху които може да се придобива право на собственост чрез окупация (occupatio*).", "cat": "thing" }, { "term": "Ferruminatio", "gloss": "спояване с желязо", "body": "Вид присъединяване на две движими вещи (accessio*), което води до първично (оригинерно) придобиване на право на собственост. Създадената нова вещ не може да се раздели, и това води до окончателната загуба на правото на собственост за собственика на второстепенната (акцесорна) вещ в полза на собственика на главната вещ.", "cat": "thing" }, { "term": "Ficta possessio", "gloss": "фиктивно владеене", "body": "Създадена от римските юристи конструкция за признаване на владението на владелец (possessor*), който всъщност не притежава вещта. Воден поток, който е държавна собственост. Това са големите и малки реки, които са пълноводни и течащи през цялата година, независимо от техния воден дебит.", "cat": "thing" }, { "term": "Fiducia", "gloss": "фидуция", "body": "Правен акт, защитен с произтичащ от договора за фидуция иск (actio fiduciae*), с който фидуциантът прехвърля правото на собственост на една вещ на фидуциария чрез манипулация (mancipatio*) или по съдебен ред (in iure cessio*) при условие приобретателят-фидуциар да му върне собствеността на вещта на определена дата или при изпълнение на определени условия. Различават се fiducia cum amico (с приятел) от fiducia cum creditore (с кредитор).", "cat": "thing" }, { "term": "Fructus", "gloss": "плод", "body": "Продукт на една плодоносна вещ (res*), който се появява периодично в зависимост от нейния характер. Различават се:\n- fructus extantes (съществуващи плодове): плодове, които още не са консумирани и се притежават в естествен вид от този, който добросъвестно ги е събрал и дължи предаването им на собственика на плодоносната вещ.\n- fructus pendentes (неприбрани плодове): плодове, които още не са отделени от плодоносната вещ и които са неразривна част от нея. Те принадлежат на собственика на плодоносната вещ.\n- fructus percepti (прибрани плодове): плодове, които реално са прибрани от лицето, което има право на това, и което по силата на това ефективно действие е станало техен собственик.\n- fructus percipiendi (годни за прибиране плодове): плодове, които би трябвало да са прибрани от владелеца. Недобросъвестният владелец носи отговорност за тяхното погиване по отношение на собственика на плодоносната вещ.", "cat": "thing" }, { "term": "Fundus", "gloss": "поземлен имот", "body": "Термин, който по времето на Републиката служи за означаване на недвижим имот, включително и на сграда, както и за означаване само на незастроен имот в противоположност на сграда или застроен имот.", "cat": "thing" }, { "term": "Habitatio", "gloss": "обитаване", "body": "Вещно право върху чужда вещ (iura in re aliena*), вид личен сервитут (servitus personarum*), което дава право на своя титуляр да живее в къща, която е чужда собственост и евентуално да я отдава под наем на трето лице по силата на сключен с него договор за наем (locatio-conductio rei*).", "cat": "thing" }, { "term": "Hypotheca ou pignus conventum", "gloss": "ипотека или върнат залог", "body": "Наименование с гръцки произход, което римските юристи използват от II в. сл.Хр. Ипотеката е вещна гаранция върху чужда вещ. За разлика от обикновения залог (pignus datum*), при който се извършва предаване на владението (possessio*), ипотеката се учредява с консесуален договор без предаване на владението (pignus conventum*) на кредитора (creditor*). Ипотекарният кредитор може да предизвика продажба на ипотекираната вещ по специален ред, ако на падежа дългът не бъде платен (ius distrahendi*). дира за наследството или пък срещу друго лице, което притежава наследствено имущество, претендира наследствено право или само владение върху наследството.", "cat": "thing" }, { "term": "Immissiones in alienum", "gloss": "увреждания, причинени в чужд имот", "body": "Реални или възможни увреждания, причинени от ползването извън уговорените граници на един чужд имот. Собственикът (dominus) на имота може да се противопостави на такива действия при определени условия.", "cat": "thing" }, { "term": "Implantatio", "gloss": "засаждане, засяване", "body": "Начин на първично (оригинерно) придобиване на право на собственост чрез присъединяване (accessio) на движима към недвижима вещ чрез засаждане (засяване) на растения, които се вкореняват в почвата.", "cat": "thing" }, { "term": "In bonis esse", "gloss": "притежавам, имам в своя патримониум", "body": "Израз, с който се определя положението на една вещ, която е част от имуществото на едно лице, което не е непременно цивилен собственик. То е ник (срв. dominium ex iure Quiritium) както ако би защитено от претора (praetor) както ако би придобило цивилна собственост, напр. на основание на давностно владение (срв. usucapio).", "cat": "thing" }, { "term": "In iure cessio", "gloss": "съдебно прехвърляне на правото на собственост", "body": "Способ за производно (деривативно) придобиване на правото на собственост (dominium*), използвано за прехвърляне както на манципни (res mancipi*), така и на неманципни вещи (res nec mancipi*). Състои се в симулативен процес, като отчуждителят не се противопоставя на предявения от приобретателя фиктивен ревандикационен иск (reivindicatio*) и преторът (praetor*) веднага присъжда вещта на приобретателя, който става неин (dominus*).", "cat": "thing" }, { "term": "Inaedificatio", "gloss": "това, което е построено върху, застояване", "body": "Начин на първично (оригинерно) придобиване на право на собственост чрез присъединяване (accessio) на движима към недвижима вещ чрез издигане на постройка върху чужда земя с материали на едно трето лице. Сградата става собственост в който тя е свързана трайно с нея (срв. superficies solo cedit).", "cat": "thing" }, { "term": "Instrumentum", "gloss": "инструмент, средство, документ", "body": "(1) Писмен акт, с който се удостоверява едно правно действие или правна сделка (напр. instrumentum donationis — документ, удостоверяващ извършено дарение;\n(2) Съвкупност от второстепенни вещи, свързани с ползването на главната вещ (instrumentum fundi съвкупността от роби, добитък и земеделски инвентар, предназначени и необходими за обработването на поземлен имот).", "cat": "thing" }, { "term": "Insula in flumine nata", "gloss": "остров, появил се сред реката", "body": "Способ за първично (оригинерно) придобиване на правото на собственост, основан на естественото образуване на остров в средата на воден поток; островът става собственост на собствениците на крайбрежните имоти, като се разделя по линии, минаващи през средата на реката и като продължение на границите на крайбрежните имоти (pars pro diviso).", "cat": "thing" }, { "term": "Intercessio tribunicia", "gloss": "право на вето на трибуните", "body": "Право на вето, с което разполагат плебейските трибуни (tribunus plebis*) срещу актовете на римските магистрати (magistratus*), което се упражнява в интерес на плебса (plebs*).", "cat": "thing" }, { "term": "Interversio possessionis", "gloss": "изменение на владението", "body": "от претора (praetor*) формула (formula*), която му е предоставена след приключване на първата фаза на процеса – in iure. Ако се докажат предявените факти, съдията осъжда ответника, в противен случай го оправдава. В екстраординарната процедура (cognitio extra ordinem*) съдията е държавен служител, пред който се развива изцяло процесът по решаване на един гражданскоправен спор.", "cat": "thing" }, { "term": "Inventio thesauri", "gloss": "откриване на съкровище", "body": "Способ за първично (оригинерно) придобиване на право на собственост (dominium*), от който, въз основа на различни изисквания, се ползва лицето, което е открило съкровище (thesaurus*) – вещ или вещи със значителна стойност, които са скрити от незапомнени времена.", "cat": "thing" }, { "term": "Iura in re aliena", "gloss": "права върху чужда вещ", "body": "Ограничени вещни права, които се състоят в частичното ограничаване на правомощията на собственика (dominus*) на една вещ в полза на друго лице, което придобива ограничена власт върху същата вещ (напр. ex. servitus*, usus*, ususfructus*, habitatio*).", "cat": "thing" }, { "term": "Iura praediorum", "gloss": "поземлени права", "body": "Синоним на поземлени сервитути – вж. servitus praediorum*.", "cat": "thing" }, { "term": "Iusta causa", "gloss": "правно основание", "body": "1) Придобивно основание (iustus titulus), което се състои в едностранна сделка или договор, с които се придобива право на собственост от владелеца на вещта, при наличие на добросъвестност и след изтичане на определен срок (usucapio*).\n2) Позволената цел, преследвана от отчуждителя и приобретателя с оглед прехвърляне на правото на собственост чрез прехвърляне на владението върху една вещ (iusta causa traditionis). Вж. също causa*.", "cat": "thing" }, { "term": "Iusta possessio", "gloss": "правомерно владение", "body": "Предоставянето на владечески интердикт (interdictum*) на ищеца е свързано с наличието на правомерно владение (possessio*), т.е. което владението не е опорочено. Когато ищецът е придобил владението от насрещната страна чрез насилие, тайно или прекарно (vi, clam, precario), преторът му отказва интердиктна защита (exceptio vitiosae possessionis*).", "cat": "thing" }, { "term": "Lex Scribonia", "gloss": "de usucapione servitutibus", "body": "Закон, датиран към 40 г. пр.Хр., с който се забранява създаването на поземлен сервитут (servitus praediorum*) по давност (usucapio*). Lex venditionis\n(1) Допълнителна (акцесорна) клауза или съвкупност от клаузи в договора за покупко-продажба (вж. също leges emptionis et venditionis*).\n(2) Клауза при принудителното изпълнение (bonorum venditio*) срещу несъстоятелния длъжник, която съдържа опис на подложеното на продан имущество, името на кредиторите и сроковете, в които приобретателят (bonorum emptor*) трябва да ги удовлетвори.", "cat": "thing" }, { "term": "Libripens", "gloss": "везномерец", "body": "Лице, което играе централна роля в ритуала на правния акт, осъществяван с бронз и везни (actes per aes et libram*) и по-специално в процедурата на манципацията (mancipatio*).", "cat": "thing" }, { "term": "Limes", "gloss": "граници", "body": "Граници на римската държава, които са определящи за postliminium*.", "cat": "thing" }, { "term": "Longa manu traditio", "gloss": "традиция на дългата ръка", "body": "Опростен начин на прехвърляне на владение (possessio*) без пряко предаване, чрез което отчуждителят в присъствието на приобретателя му показва от разстояние обекта на прехвърлянето (например с една обиколка на имота).", "cat": "thing" }, { "term": "Mala fides superveniens non nocet", "gloss": "породената след определен момент недобросъвестност не вреди", "body": "Принцип, който се прилага във връзка с придобивната давност (usucapio*), и изисква добросъвестно владение (bona fides*) само към началото на давностния срок, т.е. към момента, в който се придобива узукапионното владение (possessio*). Последвалото изчезване на добросъвестността на владелеца не е пречка за придобиването на вещта по давност.", "cat": "thing" }, { "term": "Mancipatio", "gloss": "манципация, от manu capere = вземам нещо в ръце", "body": "Начин на производно (деривативно) придобиване на цивилна собственост (dominium ex iure Quiritium*), извършвано в абстрактна и тържествена форма, със соленелни изрази и действия. Приобретателят (mancipio accipiens*) хваща с ръка вещта, която му се отчуждава от собственика (mancipio dans*), а везномерецът (libripens*) удря по везните с късче бронз (aes et libra*).", "cat": "thing" }, { "term": "Mancipio accipiens", "gloss": "този, който придобива mancipium", "body": "Термин за означаване на приобретателя на една вещ, прехвърляна с манципация (mancipatio*).", "cat": "thing" }, { "term": "Mancipio dans", "gloss": "този, който предоставя mancipium", "body": "Термин за означаване на отчуждителя, който прехвърля с манципация (mancipatio*) правото на собственост на една своя вещ.", "cat": "thing" }, { "term": "Nec vi nec clam nec precario", "gloss": "нито с насилие, нито тайно, нито прекарио", "body": "Израз, с който се изисква правомерно, неопорочено владение (iusta possessio*) за получаване на владелческа защита чрез интердикти (interdictum*) или за валидно предоставяне по давност (срв. usucapio*).", "cat": "thing" }, { "term": "Nemini res sua servit", "gloss": "никой не може да се ползва от сервитут върху своя вещ", "body": "Основен принцип в режима на сервитутите (servitus*), по силата на който собственикът (dominus*) не може да създаде или да ползва за себе си сервитутно право върху своя собствен имот. Ако бенефициентът на сервитут в полза на господстващия имот придобие правото на собственост върху служещия имот, сервитутът се погасява поради сливане (confusio*).", "cat": "thing" }, { "term": "Nemo plus iuris ad alium transferre potest quam ipse haberet", "gloss": "никой не може да прехвърли другиму повече права, отколкото сам притежава", "body": "Основен принцип при наследственото и вещното право, според който не може да се прехвърлят на трето лице права, които не се притежават от отчуждителя. Правилото се отнася до прехвърлянето на вещни права с правни актове както между живи, така и по повод на смърт.", "cat": "thing" }, { "term": "Nemo res suas iactare praesumitur", "gloss": "не може да се предполага изоставянето на една своя вещ", "body": "Принципи, по силата на които не се допуска изоставяне (derelictio) на една вещ, ако не се докаже волята (animus) на собственика за това изоставяне.", "cat": "thing" }, { "term": "Nemo sibi ipse causam possessionis mutare potest", "gloss": "никой не може сам да промени основанието на своето владение", "body": "Правилото забранява на лицето, придобило владение (possessio) върху една вещ (res) в резултат на частно правоприемство (срв. titulus и causa), впоследствие да променя това основание, като претендира придобиване на основание като наследник (heres) или легатар (legatarius).", "cat": "thing" }, { "term": "Non usus", "gloss": "неизползване", "body": "В материята на ограничените вещни права (iura in re aliena*) това е израз за означаване на автоматично погасяване (usucapio libertatis*) на един селски поземлен сервитут (servitus praediorum*), който не е осъществяван през определен период от време.", "cat": "thing" }, { "term": "Numerus clausus", "gloss": "изчерпателно изброяване", "body": "Основен принцип във вещното право, чиято устойчивост в римското право е относително. Според него страните не могат да учредяват вещни права, които не са предвидени и изрично уредени в закона.", "cat": "thing" }, { "term": "Nummo uno", "gloss": "за една монета", "body": "Израз за означаване на фиктивна цена (pro nummo uno) по договора за покупко-продажба (emptio venditio*), като с този договор се прикрива дарение.", "cat": "thing" }, { "term": "Nuntiatio operis novi", "gloss": "предизвестие за нова работа", "body": "Извънсъдебно обявяване (денонсиране) от собственика или титуляра на вещно право върху недвижим имот, насочено към неговия съсед, с цел да му забрани да продължи без предизвестие вече предприето строителство или разрушаване на сграда, ако с това може да се причини вреда на денонсиращия.", "cat": "thing" }, { "term": "Occupatio", "gloss": "окупация, завладяване", "body": "Първичен (оригинерен) начин на придобиване на право на собственост (dominium*), при който лицето става собственик в момента на придобиването на владение (possessio*) върху вещта при нейната безстопанственост или ако е вещ (res*), която не принадлежи на никого (res nullius*), подлежаща на (nec) mancipi*), която е никоя.", "cat": "thing" }, { "term": "Pignus", "gloss": "залог", "body": "Едностранен реален договор (срв. obligationes re contractae*), който се сключва с предаване на владението (possessio*) на една движима вещ (res*) от длъжника (debitor*) или от трето лице на кредитора (creditor*) с цел обезпечаване на вземането, при което се прехвърля само държането, а не и собствеността, освен ако дългът не бъде платен. За разлика от „pignus“ се означава и като реален източник на вещното обезпечение.", "cat": "thing" }, { "term": "Pignus conventum", "gloss": "върнат залог", "body": "Често срещана форма на залог (pignus*) при която предметът на залога остава в разположение на длъжника (hypotheca*).", "cat": "thing" }, { "term": "Pignus datum", "gloss": "обикновен залог", "body": "Най-древната форма на залог (pignus*), при която предметът на залога се предоставя на заложния кредитор.", "cat": "thing" }, { "term": "Possessio", "gloss": "владение", "body": "Фактическа власт върху вещите (res*), която владелецът упражнява (самостоятелно или чрез другиго). Тя има два аспекта: намерение за владение (animus*), – субективен елемент и фактическо господство, (corpus*), – обективен елемент.", "cat": "thing" }, { "term": "Possessio ad interdicta", "gloss": "интердиктно владение", "body": "Владение (possessio*), което е защитено с преторски интердикт (interdictum*). Освен добросъвестният и недобросъвестният владелец с него се защитават и владелци, които владеят от чуждо име: заложен кредитор (срв. pignus*), секвестиар (срв. depositum sequester*), прекарист (срв. precarium*), вектигалист (ager vectigalis*), емфитевт (emphyteusis*), суперфициар (срв. superficies*).", "cat": "thing" }, { "term": "Possessio ad usucapionem", "gloss": "узукапионно /давностно/ владение", "body": "Особена форма на владение, основана на придобивен титул (iusta causa; causa*), който дава възможност на едно лице да придобие право на собственост (dominium*) по давност върху една вещ, когато са налице други предпоставки за придобивна давност (usucapio*).", "cat": "thing" }, { "term": "Possessio animo solo", "gloss": "retenta) (владение, запазвано само с намерение да се владее", "body": "Ситуация, в която владелецът на една вещ запазва владението (possessio*), независимо че временно няма ефективната власт върху вещта (corpus*). Тази форма на запазване на владението само с намерението да се владее се прилага за естествените обекти (зимни и летни пасища saltus hiberni et aestivi*) или за случаите, когато владелецът може да възстанови фактическата власт по всяко време и не се допуска завладяване от трето лице.", "cat": "thing" }, { "term": "Possessio civilis", "gloss": "цивилно владение", "body": "Владение, основано на правно основание (causa*), необходимо за придобиване на правото на собственост върху една вещ по давност (usucapio*).", "cat": "thing" }, { "term": "Possessio iusta / iniusta", "gloss": "законно / незаконно владение", "body": "Владението е законно (iusta), ако е придобито без насилие, без тайно отнемане и без да е назаем (vi, clam, precario) от лицето, спрямо което се иска защита. Придобитото по този начин владение се нарича незаконно (iniusta) и не е защитено срещу лицето, от което е отнето (interdictum*). Владението е незаконно спрямо трети лица, ако е придобито с насилие, тайно или безвъзмездно. В тези случаи се прилагат забранителни интердикти (interdicta retinendae possessionis).", "cat": "thing" }, { "term": "Possessio longi temporis", "gloss": "владение от дълго време", "body": "Основание за придобиване на собственост върху провинциални земи чрез давностно владение (praescriptio longi temporis).", "cat": "thing" }, { "term": "Possessio naturalis", "gloss": "естествено владение, държане", "body": "То обхваща случаите, в които правото не дава правна защита на лицето, което упражнява ефективна власт върху вещта. Това са хипотезите на арендатора по аренден договор (locatio conductio rei*), на влогоприемателя по договор за влог (срв. depositum*) или мандатаря по договор за поръчка (срв. mandatum*).", "cat": "thing" }, { "term": "Possessio vacua", "gloss": "свободно, необезпокоявано владение", "body": "Израз, използван за уточняване на основно задължение на продавача (venditor*), който трябва да прехвърли на купувача (emptor*) спокойното владение на продадената вещ, т.е. освободена от всяка възможност за евикция от страна на трето лице (evictio*).", "cat": "thing" }, { "term": "Possessio vitiosa", "gloss": "опорочено владение", "body": "Владение, което е придобито тайно (clam*), насилствено (vi*) или прекарно (precarium*) от лицето, което търси интердиктна защита (interdictum*) от претора. Ответникът по интердикта може също да се позове на опорочено владение и да отблъсне претенцията, ако самият той е жертва на порочно отнемане на владението (срв. exceptio vitiosae possessionis*).", "cat": "thing" }, { "term": "Postliminium", "gloss": "постлиминиум, буквално: и отвъд границата", "body": "Първоначално се свързва със завръщането в Рим на римски гражданин (civis Romanus*), който е бил военнопленник на неприятеля (срв. captivitas*). В класическия период това е правото на пленения от врага римски гражданин, който в резултат на това е бил подложен на максимално намаляване на правоспособността (capitis deminutio maxima*), да получи с обратна сила всички права, което е притежавал, ако се върне действително и окончателно в Рим. Това право е основано на фикцията, че римският гражданин винаги е бил в границите (limes*) на римската територия.", "cat": "thing" }, { "term": "Precarium", "gloss": "прекарий", "body": "Съглашение, по силата на която едно лице – концедент (precario dans) се задължава да предостави владение (possessio*) на една вещ (по принцип недвижимост) на друго лице – прекарист (precario accipiens), за ползване до момента, когато концедентът едностранно поиска връщането ѝ. От своя страна прекаристът може да се задължи за някаква контрапрестация – да даде (dare*) или да направи (facere*) нещо по-друго споразумение с концедента. Вж. също patronus* и clientes*.", "cat": "thing" }, { "term": "Proprietas", "gloss": "собственост", "body": "Термин, с който в класическия период се означава голата собственост на едно лице, чието имущество изцяло или отчасти е обременено с право на плодоползване. По време на Юстиниан този термин се използва и означава собственост, която по своята същност е пълна.", "cat": "thing" }, { "term": "Quasi usufructus", "gloss": "квазиплодоползване", "body": "Особен вид плодоползване върху потребими вещи (ususfructus*) за разлика от общата хипотеза на учредяване на плодоползването само върху непотребими вещи (res quae usu consumuntur, виж res*).", "cat": "thing" }, { "term": "Reivindicatio", "gloss": "ревандикационен иск", "body": "Вещен иск (actiones in rem), предоставен на квиритския собственик (срв. dominium ex iure Quiritium) на една вещ, на която не е владелец. Искът се предявява срещу лицето, което има владение (possessio) на вещта в момента на литисконтестацията (litiscontestatio) или я притежава фиктивно (ficta possessio). Целта на иска е да установи правото на собственост на ищеца и да отнеме вещта от ответника. В противен случай ищецът е осъден да заплати на ответника определена под клетва (iusiurandum in litem) искане.\nReivindicatio (ревандикационен иск) - Създаден на основата на формуларния процес, иск (reivindicatio) за връщане на вещта, който собственикът (който не е същевременно владелец) предявява срещу лицето (което владее вещта), специфично, за да може да докаже собствеността си и нейната стойност (valoris).", "cat": "thing" }, { "term": "Reivindicatio utilis", "gloss": "полезен ревандикационен иск", "body": "Създаден от претора (praetor) иск по модела на формулата (formula) на ревандикационния иск (reivindicatio), който се дава по съображения за равнопоставеност на бившия собственик, който е изгубил формално своето право на собственост (dominium) при първично (оригинерно) придобиване на собствеността от трето лице (при смесване commixtio; или сливане specificatio). С този иск бившият собственик може да иска обезщетяване в размер на стойността на вещта, която е изгубил (pro rata valoris – пропорционално на стойността).", "cat": "thing" }, { "term": "Rem habere licere", "gloss": "да бъде позволено да се притежава вещта", "body": "Виж stipulatio rem habere licere и habere licere.", "cat": "thing" }, { "term": "Repudium", "gloss": "изгонване, напъждане", "body": "Първоначално това е обявяване на волята на един от съпрузите на другия да се прекрати брачната връзка и представлява форма на развод (divortium). По-късно това е всяка форма на прекратяване на брака по едностранно волеизявление на един от съпрузите Вещи, които са изключени от гражданския оборот и не могат да се включат в имуществото (patrimonium) на лицата, защото не служат за задоволяване на частни или индивидуални нужди и интереси. В тях се включват, от една страна, res divini iuris (вещ, която се определя от сакралното право) като храмове, гробове, от друга страна – res publicae humani iuris (тези, които са публични вещи по светското право), като имуществото под управление на римската държава или общите вещи (res communes), които са притежание на всички – въздухът, водата в реката и пр.", "cat": "thing" }, { "term": "Res", "gloss": "вещ", "body": "Определена част от материалната действителност или право (res incorporales), което може да се присвоява и притежава от човека и да има полезност за него. Може да се класифицират и различни вещи по различни критерии:\n(1.1) res in commercio, res in nostro patrimonio (вещ в обръщение, в нашия патримониум): Вещта, която е притежание на едно частно лице и може да се включи в имуществото му (patrimonium).\n(1.2) res extra commercium, res extra nostrum patrimonium (вещ извън обръщение): (2.1) res corporales (телесни вещи): Вещи, които могат да се докоснат (res quae tangi possunt) и спрямо които може да се осъществява непосредствена ефективна физическа власт (господство); (2.2) res incorporales (нетелесни вещи): Вещи, които не могат да бъдат обект на пряко физическо въздействие (res quae tangi non possunt) като: правни, вземания. Те се притежават по непряк начин чрез вещни права или квазивладение (3.1) res quae pondere, numero, mensura consistant (вещи, които могат да се претеглят, преброят или измерят): Вещи, които могат лесно да се заменят с други от същото естество, които не са преценявани по качество, а по количество, тегло, брой или размер. (3.2) singula corpora (телесни еднородни вещи): Вещи, чиито индивидуални качества са от обективно значение и които не могат да се заменят с вещи със същия произход. (3.3) res quae in genere functionem recipiunt (родово определени вещи): Вещи, които субективно са определени от страните по правоотношението по техните родови белези, без да са индивидуализирани (3.4) species (видове, видово-определени вещи): Вещи, които са определени по вид и индивидуализирани от страните по правоотношението (4.1) res quae usu consumuntur (консумируеми вещи, потребими вещи): Предназначени за консумиране вещи, за пряка употреба, като в резултат на това се разрушават или престават да съществуват (4.2) res quae non usu consumuntur (неконсумируеми, непотребими вещи): Вещи с продължителна трайност и за многократно употреление. (4.3) res quae usu minuuntur (вещи, които се изхабяват при ползването им): Вещи, които не се унищожават при употреба, но постепенно се изхабяват и разрушават. (5.1) res quae uno spiritu continentur (вещи, които представляват единство, прости вещи): Вещи, които нямат обособени части, които да могат да се отделят, като се възприемат и съществуват само като едно цяло по силата на определено смесване на съставните им елементи, което обуславя тяхното съществено единство. (5.2) res quae ex pluribus (съставни вещи): Вещи, които се състоят от различни части, всяка от които може да има и самостоятелно съществуване и обосо- беност, но които са свързани повече или по-малко неразделно едни с други в цяло. Различават се res quae ex pluribus inter se cohaerentibus constant (вещи, които са съвкупност от кохерентни вещи) и res quae ex pluribus inter se distantibus constant (вещи, които са съставени от множество материално отделени вещи).\n(6) res quae sine interitu dividi non possunt (неделими вещи): Вещи, които не могат да се разделят на части без да се разрушат като цяло. (7.1) res mancipi (маниципни вещи): Основни по своето значение за земеделското общество вещи (поземлено имение, обработваеми земи, поземлени сервитути, роби, впрегатен или ездитeн добитък), чието непосредствено прехвърляне изисква манципация (mancipatio*) или съдебно прехвърляне (in iure cessio*). (7.2) res nec mancipi (неманципни вещи): Вещи с по-малко значение, които не са включени в категорията на манципните res mancipi*, и чието прехвърляне на правото на собственост не изисква манципация (mancipatio*) или съдебно прехвърляне (in iure cessio*), а само просто предаване (traditio*). (8.1) res immobiles (недвижими вещи, недвижи-мости): Закрепени за земята вещи, които не могат да се преместват без разрушаване (следкласическо понятие). (8.2) res mobiles (движими вещи): Вещи, които могат да се преместват от едно място на друго без промяна на тяхната същност (следкласическо понятие).", "cat": "thing" }, { "term": "Res derelictae", "gloss": "изоставени вещи", "body": "Вещи, които са били на едно лице и което след това ги е изоставило (вж. derelictio*). Те са особен вид вещи, различни от тези, които не са били никому (res nullius*) и заедно с тях могат да бъдат придобивани в собственост чрез завладяване (occupatio*).", "cat": "thing" }, { "term": "Res furtiva", "gloss": "крадена вещ", "body": "Вещ, която е придобита в резултат на кражба и поради това не може да се придобие в собственост по давност (срв. res habilis* et usucapio*).", "cat": "thing" }, { "term": "Res habilis", "gloss": "вещ, годна за придобиване по давност", "body": "Това е обективно необходима предпоставка за действително придобиване по давност на една вещ (usucapio*). Изключени за придобиване по давност са публичните вещи (res publicae humani iuris, вж. res*), вещите по сакралното право (res divini iuris, вж. res*), крадените вещи (furtum*), придобитите тайно (срв. clam*) или насилствено (vi; срв. nec vi nec clam nec precario*). За крадената вещ (res furtiva*) е допустимо да се придобие по давност, ако тя отново попадне у собственика (dominus*) и той разпознае в нея същата вещ, от която е бил лишен чрез кражбата (reversio in potestatem domini).", "cat": "thing" }, { "term": "Res hostium", "gloss": "вещ, притежание на враговете", "body": "Вид безстопанствени (ничии) вещи (res nullius*), в които се включват всякакви предмети, притежавани от вражеския народ и завладени от римляните.", "cat": "thing" }, { "term": "Res nullius", "gloss": "ничия вещ", "body": "Вещ, която не принадлежи никому и която може да се придобие в собственост (dominium*) по първичен (оригинарен) начин чрез завладяване (occupatio*).", "cat": "thing" }, { "term": "Res perit domino", "gloss": "вещта погива за собственика", "body": "Основен принцип, според който рискът (periculum*) от погиване или увреждане на вещта (dominus*) се носи от нейния собственик (dominus*). Виж също casum sentit dominus*.", "cat": "thing" }, { "term": "Res praestanda", "gloss": "дължима вещ", "body": "Предмет на дължимото поведение. Понякога се използва за риска (periculum), който е длъжен да поеме собственикът. Също се отнася до искове, свързани с предаване на вещта или изпълнение на задължение.", "cat": "thing" }, { "term": "Saltus hiberni et aestivi", "gloss": "зимни и летни пасища", "body": "Поземлен имот, високопланинско пасище, което се използва част от годината, но владеенето върху него се запазва само чрез намерението да се владее (possessio animo solo retenta) през останалата част от годината.", "cat": "thing" }, { "term": "Salva rerum substantia", "gloss": "със запазване на същността /съдържанието/ на вещта", "body": "Принцип, който се прилага при плодоползването (ususfructus), по силата на който плодоползвателят трябва да запази същността /съдържанието/ на вещта, върху която упражнява своето право. Вж. също satisdatio usufructuaria.", "cat": "thing" }, { "term": "Satisdatio usufructuaria", "gloss": "обещание, свързано с правото на плодоползване", "body": "Обещание, свързано с поръчителство, направено от плодоползвателя по искане на претора (praetor*), с което той се задължава чрез стипулация (stipulatio*) да се ползва от обекта на плодоползването с грижата на добър стопанин (bonus paterfamilias*) и да върне вещта и нейните принадлежности с изтичането на срока на плодоползването (ususfructus*). Виж cautio usufructuaria*.", "cat": "thing" }, { "term": "Servitus altius non tollendi", "gloss": "сервитут да не се издига сграда на определена височина", "body": "Поземлен сервитут (servitus praediorum*), който забранява построяване или надстрояване на сграда в обслужвания имот с цел да се осигури пространство и осветеност на господстващия имот.", "cat": "thing" }, { "term": "Servitus altius tollendi", "gloss": "сервитут да се издига по-високо", "body": "Поземлен сервитут (servitus praediorum*), позволяващ на собственика на господстващия имот да строи на своя терен сграда, по-висока от предишните сгради.", "cat": "thing" }, { "term": "Servitus in faciendo consistere nequit", "gloss": "сервитутът никога не може да бъде за задължение да се направи нещо", "body": "Основен принцип в режима на сервитутите (servitus*), според който собственикът на служещия имот може да се задължи само за бездействие, а не за действие.", "cat": "thing" }, { "term": "Servitus oneris ferendi", "gloss": "сервитут, свързан с понасяне на определена тежест", "body": "Този поземлен сервитут (servitus praediorum*) задължава собственика на служещия имот да поддържа и поправя опорната стена, използвана от собственика на господстващия имот за подпора на неговата сграда (при строеж на калкан). Това не е същинско изключение от принципа servitus in faciendo consistere nequit*. Работата по поддържане на стената, с което е обременен собственикът, не е обект на сервитута, а само необходима предпоставка за упражняването му.", "cat": "thing" }, { "term": "Servitus praediorum", "gloss": "поземлени сервитути", "body": "Сервитути (servitus*), чиито бенифициент е настоящият собственик на съседния имот. Различават се селски (iura praediorum rusticorum) и градски (iura praediorum urbanorum) поземлени сервитути според имота, върху който са учредени – селски или градски (застроен).\nServututis vindicatio (виндикиране на сервитут)\nВж. vindicatio servitutis*.\nServus (роб)\nРобът е лице, което се намира в робска зависимост (servitus*) и е лишено от status libertatis (срв. status*). Той не притежава права, подложен е на едностранна и абсолютна власт на своя господар (срв. patria potestas*) и юридически се третира като вещ – манципна вещ (срв. res*, res mancipi*). В женски род ancilla*; (вж. също partus ancillae*).\nServus fugitivus (роб-беглец)\nРоб (servus*), който въпреки че е избягал, се счита, че е във владение (possessio*) на своя господар до момента на залавянето му от трето лице. Вж. също possessio animo solo retenta*.\nSestertius (сестерций)\nМонетна единица, чиято стойност е различна в различните епохи – от 2 ½ аса по Закона на Дванадесетте таблици (Lex XII [duodecim] tabularum*), до 4 аса към 130 г. сл.Хр. Теглото на сестерция е 1 унция (27,3 гр) от времето на Август до монетната реформа на Диоклециан (293 г.), когато тази монета изчезва.\nSignum (печат)\nSine pretio, nulla venditio (няма действителен договор за покупко-продажба без определяне на цената)\nОсновен принцип, според който цената (pretium*) е съществен елемент на договора за покупко-продажба (emptio venditio*), защото тя е основно задължение на купувача (emptor*). С това договорът за покупко-продажба се различава от замяната (permutatio*).", "cat": "thing" }, { "term": "Solarium", "gloss": "солариум /вид рента/", "body": "Рента, дължима от суперфициаря за правото да изгради постройка (superficies*) върху частен имот на трето лице. Подобна е арендата на публичен имот (ager vectigalis*), който се отдава срещу заплащане на поземлена рента (данък) (vectigalium*).", "cat": "thing" }, { "term": "Specificatio", "gloss": "спецификация, преработване", "body": "Способ на първично (оригинерно) придобиване на право на собственост (dominium), при което се получава нова вещ чрез преработка на материал, който е пълно или поне частично притежание на трето лице. За сабинианците (Sabiniani), които дават предпочитание на материята, новата вещ е притежание на собственика на материала; за прокулеанците (Proculiani), които дават предпочитание на формата /респ на труда, вложен в преработването/, новата вещ е притежание на преработващия. Според юриста Paulus, чието разрешение е възприето и от Юстиниан, трябва да се изследва дали новата вещ може да се върне в първоначалното си състояние – тогава тя е притежание на собственика на материала, ако не може – тя е притежание на преработващия.", "cat": "thing" }, { "term": "Spoliatus ante omnia restituendus", "gloss": "лишеният от владение трябва да си възстанови владението преди всички други", "body": "Основен принцип при владелческите интердикти (interdictum*), според което в случай на отнемане на владението с насилие (vi) или тайно (clam) лицето, от което то е отнето, трябва да си възстанови владението (possessio*) върху отнетата вещ, преди да се установи кой е действителният собственик върху тази вещ (dominus*). Вж. exceptio vitiosae possessionis*.", "cat": "thing" }, { "term": "Superficies", "gloss": "букв. „повърхност“, суперфиция, право на строеж", "body": "Особено право, сходно на ограничено вещно право – iura in re aliena, с което се дерогира принципът на присъединяването (accessio), по силата на което прикрепеното за земята следва статута на земята (superficies solo cedit). С притежаване на това право суперфициарят (superficiarius), може да построи и да ползва сграда, в качеството на собственик (dominus), макар и да е издигната върху чужда земя, при условие, че плаща уговорена рента (solarium).", "cat": "thing" }, { "term": "Superficies solo cedit", "gloss": "прикрепеното за земята следва статута на земята", "body": "Основен принцип, свързан с първичното (оригинерно) придобиване на право на собственост (dominium) чрез присъединяване на движима към недвижима вещ (срв. accessio и inaedificatio), Според него построеното с чужд материал става собственост на собственика на земята от момента на трайното прикрепване на сградата към нея. Вж. също tignum iunctum.", "cat": "thing" }, { "term": "Tempus ad usucapionem", "gloss": "срок за придобивна давност", "body": "Необходим срок за владелеца (вж. possessio*) за придобиване на право на собственост върху една вещ по давност (usucapio*), която по Закона на Дванадесетте таблици (Lex XII [duodecim] tabularum*), е една година за движима вещ и две години за недвижима вещ.", "cat": "thing" }, { "term": "Terrae motus", "gloss": "земетресение", "body": "Земетресението се счита за непреодолима сила (vis maior*).", "cat": "thing" }, { "term": "Thesaurus", "gloss": "съкровище", "body": "Вещ със значителна стойност, поставена на скрито място от незапомнено време, за която се счита, че няма собственик. От момента на откриването ѝ при определени условия може да се придобие право на собственост (срв. inventio thesauri*).", "cat": "thing" }, { "term": "Tignum iunctum", "gloss": "вградена /подпряна/ греда", "body": "Този израз е за означаване на специални случай, уреден в Закона на Дванадесетте таблици (Lex XII [duodecim] tabularum*), при който се използват чужди материали за построяване на сграда. Това е изменение на принципа, че това, което е закрепено за земята, следва статута на земята (superficies solo cedit*). Всъщност собственикът на материала запазва латентното си право на собственост върху него и може да го материализира само при разрушаване на сградата, ако материалите могат да бъдат индивидуализирани. Докато те са вградени в сградата, собственикът им не може да ги ревандикира, но може да предяви специален иск – actio de tigno iuncto* (иск за вградената греда), с който може да иска двойната стойност на своя материал.", "cat": "thing" }, { "term": "Titulus ad usucapionem", "gloss": "придобивно основание", "body": "Основание (causa*) за придобиване на владение (possessio*), което е необходимо за придобиване на право на собственост по давност (usucapio*).", "cat": "thing" }, { "term": "Tradens", "gloss": "този, който предава", "body": "Това е отчуждителят при просто предаване (traditio*).", "cat": "thing" }, { "term": "Traditio", "gloss": "просто предаване, материално прехвърляне на една вещ", "body": "(1) деривативен (производен) начин за придобиване на владение (possessio) срещу материално предаване на вещта от отчуждителя (tradens) на приобретателя (accipiens). Отчуждителят демонстрира своята воля да се откаже от владението, докато приобретателят демонстрира съответната воля да придобие владението.\n(2) деривативен (производен) начин на придобиване на право на собственост (dominium), който е каузален (срв. causa) и неформален. Той е свързан с материално предаване на вещта от отчуждителя (tradens) на приобретателя (accipiens) при изразена воля за отчуждаване и придобиване на правото на собственост и при наличието на основание за прехвърляне на собствеността (iusta causa traditionis), което мотивира и оправдава преминаването на правото. При традицията е налице прехвърляне на владението (possessio). Първоначално този начин на прехвърляне е допустим само за неманципни вещи (res nec mancipi – срв. res); по-късно става основен начин на производно придобиване на право на собственост. Когато се използва за прехвърляне на манципни вещи (res mancipi – срв. res), той е свързан с придобивната давност (usucapio) върху вещта, за да може приобретателят да стане квиритски собственик (dominium ex iure Quiritium).", "cat": "thing" }, { "term": "Traditio brevi manu", "gloss": "традиция на къса ръка", "body": "Виж brevi manu traditio.", "cat": "thing" }, { "term": "Traditio longa manu", "gloss": "традиция на дълга ръка", "body": "Виж longa manu traditio.", "cat": "thing" }, { "term": "Usque ad sidera", "gloss": "до звездите", "body": "Израз, свързан с вертикалното деляне на поземления имот (правото на собственика върху земята, недрата и въздушното пространство над имота в дълбочина и височина), утвърдено в римското право.", "cat": "thing" }, { "term": "Usque ad sidera, usque ad inferos", "gloss": "чак до звездите, чак до ада", "body": "Израз от феодалното право, използван за определяне на пространствените граници на правото на собственост (dominium*) върху една недвижима вещ във вертикала във височина и в дълбочина във връзка с упражняването на това право (срв. също superficies solo cedit*).", "cat": "thing" }, { "term": "Usucapio", "gloss": "придобивна давност", "body": "Първичен начин на придобиване на право на собственост (dominium*), основан на оригинерно владение (possessio*), което е непрекъснато през давностния срок и е налице валидно придобивно правно основание. При придобивната давност трябва да са налице кумулативно пет предпоставки:\n(a) res habilis*: вещ (res*), годна за придобиване на давност;\n(b) iusta possessio*: правомерно придобито (по принцип по деривативен способ) владение, което е цивилно и непорочно (c) iusta causa/titulus*: правно валидно основание (срв. causa*);\n(d) tempus: непрекъснато владение, което е за движима вещ – една година, а за недвижим – две години.\n(e) bona fides*: добросъвестност, което е субективно изискване по отношение на приобретателя, който не трябва по никакъв начин да засяга права на други лица. Това условие се изисква само към началото на давностния срок (mala fides superveniens non nocet*).", "cat": "thing" }, { "term": "Usufructuarius", "gloss": "плодоползвател", "body": "Бенефициент на право на плодоползване (ususfructus*).", "cat": "thing" }, { "term": "Usureceptio", "gloss": "повторно придобиване на собственост", "body": "Вид придобита давност (usucapio*) при фидуциарните сделки (срв. fiducia*), при които при наличие на определени условия фидуциантът може отново да придобие правото на собственост на фидуциарната вещ след придобиване на непрекъснато владение върху нея в продължение на 1 г. (дори за недвижима вещ).", "cat": "thing" }, { "term": "Usus", "gloss": "ползване, право на ползване", "body": "Ограничено вещно право върху чужда вещ (iura in re aliena*) под формата на личен сервитут (servitus personarum*). Това право дава възможност на своя титуляр да ползва вещта, но не и да придобива плодовете от нея (fructus*).", "cat": "thing" }, { "term": "Usus maritalis", "gloss": "придобиване на съпружеска власт чрез продължително съвместно живеене", "body": "Една от трите форми на придобиване на съпружеска власт наред с coemptio* и confarreatio*. Властта (manus*) се придобива автоматично и без особена форма, ако съпрузите живеят заедно без прекъсване в продължение на една година (usus maritalis*).", "cat": "thing" }, { "term": "Ususfructus", "gloss": "право на плодоползване", "body": "Ограничено вещно право върху чужда вещ (iura in re aliena*), под формата на личен сервитут (servitus personarum*). Неговият титуляр може да полва вещта (ususfructu*) и да придобие плодовете от нея (fructus*), без да я уврежда (salva rerum substantia).", "cat": "thing" }, { "term": "Uti, frui", "gloss": "ползване и ползване", "body": "се ползва и да се придобива плодовете.", "cat": "thing" }, { "term": "Uti, frui, habere, possidere", "gloss": "да се ползва, да се прибират плодовете, да се притежава и да се владее", "body": "Формулировка, с която се описват в пълнота правомощията на собственика на една вещ (dominus*).\nUxor (съпруга, омъжена жена) Vacare\nСитуация, при която едно правоотношение няма правен субект.\nVacatio legis\nПериод от времето между обнародването на един закон и неговото влизане в сила.", "cat": "thing" }, { "term": "Vacua possessio", "gloss": "спокойно владение", "body": "Ситуация, при която притежаваната във владение (possessio*) вещ не е обект на ничия претенция.", "cat": "thing" }, { "term": "Venia aetatis", "gloss": "пълнолетие", "body": "Придобивка, предоставяна понякога на лицата, ненавършили 25 години (срв. minor XXV anno-). rum*), с която им се признава пълнолетие с навършване на 18 години за момичетата и 20 години за момчетата, освен за някои специфични сделки – (дарения, отчуждаване на недвижими имоти, учредяване на ипотека).", "cat": "thing" }, { "term": "Vindicatio servitutis", "gloss": "ревандикация на сервитут", "body": "Вещен иск, предоставен на собственика на господстващия имот по отношение на учреден в негова полза поземлен сервитут за да се релевира произтичащото от сервитута право. Искът се предявява срещу собственика на служещия имот. В случаите, когато с иска се цели признаване на съществуването на положителен сервитут (сервитут за действие), той се нарича actio confessoria, а когато се отнася до... признаването на отрицателен сервитут (сервитут за бездействие), искът се нарича actio negatoria.", "cat": "thing" }, { "term": "Accidentalia negotii", "gloss": "допълнителни/случайни, второстепенни/елементи на договора", "body": "Допълнителни клаузи на договора, които не са считани за съществени за валидността му и които страните могат да договорят или да не договорят.", "cat": "obl" }, { "term": "Actio mandati", "gloss": "иск по договор за поръчка /мандат/", "body": "Облигационен иск (actiones in personam*), предоставен на манданта срещу мандатаря за получаване на парична кондемнация при неизпълнение или лошо изпълнение на задълженията по договор за поръчка (mandatum*); както и за предаване на вещите или прехвърляне на ползите, получени в резултат на изпълнение на поръчката (actio mandati directa). Той може да се предостави и на мандатаря срещу манданта за получаване на обезщетение за направените разходи при изпълнение на договора за мандат (actio mandati contraria).", "cat": "obl" }, { "term": "Ad impossibilia nemo tenetur", "gloss": "никой не може да бъде отговорен за невъзможни неща", "body": "Никой не може да бъде отговорен за неизпълнение на невъзможна престация.", "cat": "obl" }, { "term": "Adiectus solutionis causa", "gloss": "лице, включено с цел получаване на изпълнението по облигационното отношение", "body": "Лице, допълнително включено по една стипулация (stiptulatio*), а по-късно и по всякакъв друг вид договор, но не като кредитор (creditor*), а като лице, в полза на което длъжникът (debitor*) изпълнява дължимата престация и облигационното отношение валидно се погасява.", "cat": "obl" }, { "term": "Adpromissor", "gloss": "адпромисор; който се задължава наред с длъжника", "body": "Лице, което се задължава наред с друго лице чрез вербален договор (stipulatio*) и с което става солидарен длъжник. Adrogatio или adoptio populi auctoritate (адрогация или осиновяване по волята на народа)\nОсобен начин на осиновяване (adoptio*), който изисква формално решение на народното събрание (comitia*), чрез което едно неподвластно лице paterfamilias* се поставя под властта на друго неподвластно лице, също paterfamilias, с цел да му стане син от правна гледна точка.", "cat": "obl" }, { "term": "Adstipulatio", "gloss": "допълнителна, акцесорна стипулация", "body": "Допълнителен договор към една една стипулация (stipulatio*), който е различен от нея, но е със същия обект, и чрез който длъжникът се задължава към един допълнителен кредитор (adstipulator*).", "cat": "obl" }, { "term": "Adstipulator", "gloss": "допълнителен, акцесорен кредитор, адстипулант", "body": "Допълнителен кредитор, който има същите права като основния кредитор по отношение на длъжника и чието право е породено от вербален договор (adstipulatio*). Длъжникът обещава да осъществява по отношение на него същата престация, която вече е обещал на главния кредитор по предходната стипулация (stipulatio*).", "cat": "obl" }, { "term": "Aestimatum", "gloss": "констигнационен договор", "body": "Вид ненаименован договор (conventiones sine nomine*), с който отчуждителят след предварително оценяване на една своя вещ, я прехвърля на приобретателя. Приобретателят от своя страна трябва да продаде вещта на трето лице на не по-ниска от определената цена която да предаде на отчуждителя, или пък да му върне вещта, ако продажбата не се осъществи или стане неизгодна.", "cat": "obl" }, { "term": "Affectio societatis", "gloss": "вярност към съдружниците", "body": "Обща и трайна воля на съдружниците в едно дружество (societas*) да обединят усилията и средствата си за постигане на общата цел.", "cat": "obl" }, { "term": "Aliud pro alio", "gloss": "едно вместо друго", "body": "Израз, използван за означаване, че изпълнението на дължимата престация не съответства на уговореното между страните.", "cat": "obl" }, { "term": "Animus contrahendi", "gloss": "намерение за договаряне", "body": "Воля за сключване на определен договор (contractus*).", "cat": "obl" }, { "term": "Animus donandi", "gloss": "намерение за надаряване", "body": "Воля за оказване на щедрост, за извършване на безвъзмезден юридически акт.", "cat": "obl" }, { "term": "Beneficium divisionis", "gloss": "привилегия за разпределение на имуществото", "body": "Въведена от император Хадриан привилегия, при която лицето, което обезпечава дълга като поръчител, може да иска разпределянето му между другите платежоспособни поръчители към момента на литисконтестацията (litis contestatio*).", "cat": "obl" }, { "term": "Bona fides", "gloss": "добросъвестност", "body": "Става въпрос за нормативно определено понятие, основано на критерии от етиката и психологите, неразривно свързано с понятието за честност на почтения римски гражданин (bonus vir*). Добросъвестността се изразява по два начина:\n(1) лоялно и честно поведение според общоприетите социални норми (honeste vivere) (в съвременното право: обективна добросъвестност); тя има значителна роля при пораждането на договорни задължения и се противопоставя на измамата (dolus malus)*.\n(2) вътрешно убеждение да не се накърнява чуждо право (в съвременното право: субективна добросъвестност); тя има значителна роля при владението (possessio*) и при придобивната давност (usucapio*); противопоставя се на недобросъвестността (mala fides).", "cat": "obl" }, { "term": "Bonorum emptor", "gloss": "купувач на имуществото", "body": "Приобретател на цялото имущество на неплатежоспособния длъжник при публична про- дажба на търг (bonorum venditio*). Купувачът на имуществото (bonorum emptor*) встъпва /субституира се/ в правата на длъжника и поема задължението да плати определен процент от дълговете му към отделните кредитори.\nBonorum possessio (владение на имущество)\nИнститут на наследственото право, който се състои в предоставяне от претора (praetor*) на владение (possessio*) върху цялото имущество (bonorum possessio*) на починало лице на един от евентуалните наследници, който е поискал това, с което му позволява да придобие изцяло или отчасти наследството.", "cat": "obl" }, { "term": "Bonorum venditio", "gloss": "продававане на имуществото, публична демаркиране", "body": "Прототип на процедура по фалит, която се състои в продаване на търг на имуществото (bonorum venditio*) на неплатежоспособен длъжник на един купувач (bonorum emptor*), който придобива целия актив на длъжника, но се задължава към кредитора /или кредиторите/ му за погасяване на определен процент от дълговете. Процедурата е инфамираща за длъжника (infamia*).", "cat": "obl" }, { "term": "Casum sentit debitor", "gloss": "длъжникът носи последиците от случайното събитие", "body": "Правило, според което длъжникът, който е в забава (mora*), носи имуществените последици от настъпването на случайно събитие (casus fortuitus*), което прави невъзможно изпълнението на дължимата престация.", "cat": "obl" }, { "term": "Casum sentit dominus", "gloss": "собственикът носи последиците от случайното събитие", "body": "Правило, според което собственикът носи имуществените последици от настъпването на случайно събитие (casus fortuitus*), което води до разрушаването или погиването на една вещ. Вж. също res perit domino*.", "cat": "obl" }, { "term": "Casus fortuitus", "gloss": "случайно събитие", "body": "Събитие, което настъпва случайно, което изключва вина на страните и срещу което те не могат да се противопоставят. То настъпва извън всякаква предвидимост и при невъзможност за противодействие (например: бягство на роб, разрушаване на вещ от трето лице по време на инцидент). Традиционно случайното събитие се различава от непреодолимата сила (vis maior*), въпреки че по принцип и в двата случая са налице еднакви правни последици.", "cat": "obl" }, { "term": "Casus maiores", "gloss": "значителни събития", "body": "Това е израз, еквивалентен на този за непреодолима сила (vis maior*).", "cat": "obl" }, { "term": "Cautio", "gloss": "поръчителство, гаранция за изпълнение", "body": "(1) Задължение на едно лице, поето чрез стипулация (stipulatio*), за гарантиране на изпълнението на задължение на длъжника, както и за изпълнение на задължение, което не е защитено от закона. В случаите на лошо изпълнение на облигационното отношение това лице трябва да понесе имуществените последици, ако длъжникът се освободи от отговорност.\n(2) Писмен акт, който констатира създаването или погасяването на едно правно действие, споменавайки или не (discreta, indiscreta) мотива за това правно действие.", "cat": "obl" }, { "term": "Caveat emptor", "gloss": "нека купувачът да бъде внимателен", "body": "Израз, свързан с последиците от липса на гаранция за недостатъци на продадената вещ. Става въпрос купувачът (emptor*) да бъде особено внимателен относно състоянието на продаваната вещ, тъй като само той носи риска за недостатъци или за погиването ѝ (periculum*).", "cat": "obl" }, { "term": "Chirographum", "gloss": "хирографа", "body": "Правен институт с източен или гръцки произход, въведен в римското право чрез от правото на народите (ius gentium*) и прилагащ се по отношение на перегрините (peregrini*). Хирографът е вид признаване на дълга, което длъжникът прави в писмена форма съставеният в един екземпляр документ и го предава на кредитора. Вж. също syngrapha* (признаване на дълг).", "cat": "obl" }, { "term": "Circumscriptio", "gloss": "измама, заблуда", "body": "Действие на едно лице с цел да измами или да извлече полза, като склони друго лице да сключи неефективен договор. Circumscriptio на лице, което не е навършило 25 години (minor XXV annorum) отваря пътя за санкции по Lex Laetoria de minoribus.", "cat": "obl" }, { "term": "Clausula", "gloss": "клауза", "body": "Клауза, която е включена в правен акт, в законодателен акт или във формула.", "cat": "obl" }, { "term": "Clausula rebus sic stantibus", "gloss": "клауза за обстоятелствата, които остават такива, каквито са при сключване на договора", "body": "Принцип, развит в Средновековието и по-специално от Коментаторите Bartolus и Baldus, според който всяко обвързване имплицитно включва клауза, че то съществува само при обстоятелства, които се запазват такива, каквито са в момента на обвързването на страните.", "cat": "obl" }, { "term": "Coemptio", "gloss": "коемпция", "body": "Основна форма на римския брак с придобиване на съпружеска власт – manus (matrimonium cum manu*). Коемпцията се състои в прехвърляне на властта на paterfamilias* върху неговата дъщеря на бъдещия ѝ съпруг. Извършва се чрез ритуал на манципация (mancipatio*) и с произнасяне на специални тържествени думи.", "cat": "obl" }, { "term": "Commodatum", "gloss": "заем за послужване", "body": "Реален договор (срв. obligationes re contractae*), който е двустранен и несъвършен. Сключен е с предоставянето на една вещ от комоданта (заемодател) на комодатаря (заемател), за да я ползва и със задължението да я върне с изтичането на срока на договора. Communio или condominium (съсобственост)\nФорма на колективна собственост, в която всеки от съсобствениците (dominus*) е титуляр на едно право, което се упражнява върху цялата вещ, но съответства на някаква идеална част от цялото /при делба/.", "cat": "obl" }, { "term": "Compensatio", "gloss": "компенсация", "body": "Средство, чрез което ответникът може да претендира дължима на него от ищеца сума, като по този начин намали размера на кондемнацията. Като се има предвид процесуалната характеристика на компенсацията според римското право и различните видове искове в класическия период, съществуват различни видове компенсации по пътя на възражението за измама (exceptio doli*) за искове по стриктното право, чрез agere cum deductione на купувача на имуществото на длъжника на публичен търг (bonorum emptor*), чрез agere cum compensatione на банкера (argentarius*) и чрез осъществявана от съда компенсация при исковете на добросъвестността (iudicium bonae fidei*).", "cat": "obl" }, { "term": "Compensatio lucri cum damno", "gloss": "компенсация на ползите спрямо вредите", "body": "Принцип, който изисква оценката на загубите и ползите и съответно намаляването на ефективните загуби в зависимост от ползите, които увреденото лице може да извлече от правния акт.", "cat": "obl" }, { "term": "Condicio", "gloss": "условие", "body": "(1) Бъдещо несигурно събитие, с чието настъпване (incertus an) и от чието осъществяване зависи създаването (суспензивно условие) или прекратяването (резолутивно условие) на един правен акт.\n(2) Статус на едно лице (status*).", "cat": "obl" }, { "term": "Condictio", "gloss": "кондикция, рекламация", "body": "Облигационен иск (actiones in personam*) по цивилното право или по стриктното право, който се характеризира с факта, че в неговата формула (formula*) са включени абстрактни изрази, т.е. не се споменава каузата на облигационното отношение. Кондикцията се дава на кредитора, който иска една определена сума пари или друга определена вещ, напр. когато неговото искане е основано на един договор за обикновен заем (mutuum*), на основа една стипулация (stipulatio*), от кражба (furtum*) или от неоснователно обогатяване (condictio indebiti). Римското право познава различни форми на кондикции (condictio), чиято класификация варира между класическата епоха и юстиниановото право. Между тях най-важните са:\n- condictio causa data causa non secuta (кондикция за нещо, което е изпълнено, но насрещната престация не е последвала): това е иск за връщане на дадена престация въз основа на един ненаименован договор (conventiones sine nomine) с цел да се получи насрещната (кореална) престация, която обаче до този момент не е извършена;\n- condictio certae creditae pecuniae (искане за определена сума пари): иск, който позволява да се получи предаването на определена сума, която е дадена в обикновен заем (mutuum);\n- condictio certae rei (искане на определена вещ): това е иск, който позволява да се получи връщането на определена вещ, която не е парична сума, в количеството и качеството, в което тя първоначално е предоставена в резултат на един обикновен заем за потребление (mutuum); кондикцията също така се нарича condictio triticaria;\n- condictio ex causa furtiva (кондикция във връзка с извършена кражба): иск, предоставен на увредения от една кражба (furtum) срещу извършителя на деликта (delictum) или срещу неговите наследници с цел той или те да бъдат осъдени да платят глоба, равна на по-високата стойност на откраднатата вещ към деня на извършването на деликта;\n- condictio ex iniusta causa (кондикция въз основа на една неправомерна цел): иск, предоставен на този, който е извършил една престация и чиято кауза има неправомерен характер /за получаващия/, за да може да получи връщане на предоставеното;\n- condictio incerti (неопределена кондикция за връщане на престацията): това е общ термин, с който се обозначават различните искове, които служат за санкциониране на граждански задължения, които са свързани с една неопределена престация; обектът на престацията може да бъде действие, било някакъв правен акт или придобиване на владение;\n- condictio indebiti (кондикция за връщане на недлъжимо платеното): иск, с който се санкционира връщането на даденото от този, който поради грешка (error) е изпълнил дадена престация, породена от търговски взаимоотношения (negotium) с цел да плати дълг, който не съществува или който той не е бил длъжен да погаси;\n- condictio liberationis (кондикция за освобождаване): иск, предоставен на едно лице с цел то да бъде освободено от поето от него задължение без основание за това;\n- condictio ob rem dati (кондикция за връщане на това, което е дадено с цел да се получи друга вещ): иск за връщане на вещта, която е предоставена с цел да се извърши размяна или друга контрапрестация под формата на някаква услуга или действие, извършено от едно лице по ненаименован договор; кондикцията се дава в случая, в който целта, преследвана от двете страни по договора, се явява невъзможна за изпълнение и контрапрестацията не може да бъде осъществена;\n– condictio ob turpem causam (кондикция за връщане на нещо, което е придобито въз основа на неморално действие): иск, който е свързан с връщането на една престация, която има неморален характер за този, който я е получил;\n– condictio sine causa (кондикция за връщане на нещо, дадено без основание): това е определението, дадено от Юстиниан на някои искове, предоставени на лицата, за да могат да предотвратят неоснователното обогатяване в най-широк смисъл;\n– condictio triticaria (кондикция за връщане на зърно): име, дадено от Юстиниан на condictio certae rei*, което в по-общ смисъл се използва за задълженията, които имат за обект някакви хранителни продукти и най-вече за зърно.", "cat": "obl" }, { "term": "Conductor", "gloss": "наемател, „този, който взема със себе си“", "body": "В договора за наем (locatio-conductio*), това е една от страните, която взема вещта или приема услугата, извършвана от наемодателя (locator*); според вида договор за наем това е наемателят по договор за наем на вещ (locatio-conductio rei*), извършителят на работата по договор за наем на трудов резултат (locatio-conductio operis*) или предприемачът (работодател) по договор за наем на работа (locatio-conductio operarum*).", "cat": "obl" }, { "term": "Consensus", "gloss": "съгласие", "body": "Необходим елемент за съществуването на всеки договор (contractus*); съгласието, схващано като съвпадение на насрещните волеизявления на страните, е необходимо и достатъчно условие за консенсуалните договори (срв. obligationes consensu contractae*). За другите типове договори (obligationes litteris contractae*, obligationes re contractae* и obligationes verbis contractae*) е необходимо освен съгласието да има изпълнение на акта (или предаването на вещта), или пък някаква специфична форма.", "cat": "obl" }, { "term": "Contractus", "gloss": "контракт, договор", "body": "Термин, определящ всякакъв вид договор или казано по-точно съглашение между две лица, насочено към пораждането на едно или повече задължения (obligationes ex contractu). Под общия термин за конвенция, съглашение (conventio), Ulpianus различава от една страна договорите (наименовани и ненаименовани), а от друга страна всякакви съглашения, определени с термина пакт (pactum).\nДоговорните задължение се класифицират според начина на постигане на съгласие и специфичните необходими действия за това.\nРазличават се следните договори:\n– consensu: договори, които изискват само постигането на съгласие между страните;\n– litteris: договори, които изискват освен постигането на съгласие между страните и специфично вписване (в сметководните книги на кредитора) (най-вече в codex accepti et expensi от страна на paterfamilias);\n– re: договори, които изискват, освен постигането на съгласие между страните, и реалното предаване на вещта;\n– verbis: договори, които изискват, освен постигането на съгласие между страните, и произнасянето на определени тържествени слова.", "cat": "obl" }, { "term": "Contrahere", "gloss": "договор", "body": "Сключване на договор или на правна връзка, която води до задължения. но със създаването на новите магистратури компетентността им постепенно е ограничена. Последно най-висше стъпало в йерархичната стълбица на магистратите (cursus honorum).", "cat": "obl" }, { "term": "Contrarius consensus", "gloss": "„обратно“ съгласие, съгласие в противоположен смисъл", "body": "Начин на погасяване на договорно задължение, което е основано на постигане на съгласие в противоположен смисъл от същите страни, които са създали облигационното отношение. По принцип страните изразяват (без да е необходима определена форма) тяхното съгласие да се погаси правната връзка, която те са създали преди това.", "cat": "obl" }, { "term": "Conventio", "gloss": "съглашение, съгласие", "body": "Общ израз за договаряне, което не е договор, но е основа. Между тези, които имат идентични съглашения, е налице техническа ситуация, която сама по себе си не изпълнява изискванията за някакво конкретно име (напр. договор с име или без име), а има авторитета на страните, които са вани договори. \n– договори, които не създават задължения; \n– правни сделки, които се основават на други договори; \n– договори, които пораждат правни последствия, въпреки че са нетипични. създадени от преторския едикт (наименовани договори; срв. contractus* и edictum*), също така по отношение на договори, създадени въз основа на някаква кауза (ненаименовани договори – conventiones sine nomine*), или договори – съглашение без специална кауза, пакт (pactum*).", "cat": "obl" }, { "term": "Conventiones sine nomine", "gloss": "ненаименовани съглашения", "body": "Общ израз, определящ всяко съглашение, което не е „типизирано“ в преторския едикт. Между тези съглашения се намират синалагматични съглашения, които са придобили юридическа сила тогава, когато една от страните е изпълнила своята престация по силата на някакво правно основание. Те се наричат ненаименовани договори. Според византийските автори се различават четири типа ненаименовани договори:\n– do ut des: прехвърляне на право на собственост от едната страна с очакване за прехвърляне на право на собственост от другата;\n– do ut facias: прехвърляне на право на собственост от едната страна срещу задължение на другата страна да извърши някакво правно действие;\n- facio ut des: действие, което е извършено от една от страните в очакване другата страна да прехвърли право на собственост;\n- facio ut facias: действие, извършено от една от страните срещу задължение на другата страна да извърши съответно действие.", "cat": "obl" }, { "term": "Creditor", "gloss": "кредитор", "body": "Активната страна по едно облигационно отношение (obligatio), титуляр на вземането, което трябва да се изпълни от длъжника (debitor).", "cat": "obl" }, { "term": "Culpa", "gloss": "вина", "body": "Общ критерий за пораждане на договорна (срв. contractus) или извъндоговорна (срв. Lex Aquilia de damno) отговорност. В областта на договорите вината (culpa) отговаря на всяко укоримо поведение (небрежност), което може да породи невъзможност от изпълнение или лошо изпълнение на облигационното отношение.\nСпоред интензивността на последиците от виновното поведение се различават:\n- culpa lata (тежка небрежност, която е необяснима и не може да бъде извинена);\n- culpa levis (лека небрежност);\n— culpa levissima (най-лека небрежност).\nПри леката небрежност (culpa levis) вината се състои в поведение, което не би имал един един идеален длъжник, един модел за сравнение. Когато моделът за сравнение е абстрактен индивид – например добросъвестният домовладелец (bonus paterfamilias*), се говори за culpa levis in abstracto. В противоположната хипотеза, когато вината или небрежността е определяна по отношение на обикновеното поведение на един точно определен длъжник, свързана е с конкретни обстоятелства, индивидуални негови действия, юристите от след класическата епоха говорят за culpa levis in concreto.", "cat": "obl" }, { "term": "Culpa in contrahendo", "gloss": "грешка или вина на лицето, което сключва договора, преддоговорна отговорност", "body": "Съвременен израз, който означава задължението на една от страните да обезщети вредите, които е нанесла на другата страна при неспазване на преддоговорно съглашение.", "cat": "obl" }, { "term": "Custodia", "gloss": "пазене, отговорност за пазене", "body": "Този термин означава едновременно дейността по пазене на една вещ (материално пазене) и отговорността, която произтича от това (отговорност за пазене). Някои длъжници всъщност са натоварени със задължение за полагане н", "cat": "obl" }, { "term": "Damnum emergens", "gloss": "материална вреда – /щета/, претърпяна загуба", "body": "Ефективно намаляване на имуществото /патримониума/ на потърпештвата страна. Става въпрос за вреда с имуществен характер, които се различават от пропуснатите ползи (lucrum cessans*).", "cat": "obl" }, { "term": "Damnum iniuria datum", "gloss": "вреда, причинена от противоправно действие, противоправно увреждане", "body": "Обобщен израз за определяне на общия режим на извъндоговорната (деликтна) отговорност (срв. obligationes ex delicto*), а също и т.нар. аквилиева отговорност, основана на lex Aquilia de damno – пребисцит (plebiscitum*), приет през 286 г. пр.Хр.", "cat": "obl" }, { "term": "Dare", "gloss": "давам, прехвърлям право на собственост", "body": "В правно-технически смисъл dare означава прехвърляне на право на собственост (dominium*) върху една вещ. особено голяма грижа (diligentia*), което ги прави отговорни за всяка загуба или разрушаване на обекта, който те трябва на всяка цена да върнат, с изключение на хипотезите на непреодолима сила (vis maior*).", "cat": "obl" }, { "term": "Dare, facere oportere ex fide bona", "gloss": "това, което е прехвърлено по силата на добросъвестността", "body": "Клауза, включена в някои искове (actio*), за ограничаване на задължението, което е предмет на спора. Исковете, които съдържат тази клауза, са наречени искове на добросъвестността (actiones bonae fidei*), тъй като добросъвестността (bona fides*) е основната мярка за изпълнение на задължението на длъжника, съответно на правата на неговия кредитор.", "cat": "obl" }, { "term": "Datio in solutum", "gloss": "даване вместо плащане", "body": "Начин на погасяване на облигационното отношение, чрез който длъжникът (debitor*) със съгласието на кредитора (creditor*) предоставя една вещ, различна от тази, която първоначално е определена в договора (вж. също obligatio cum solutionis facultate* – задължения за факултативно изпълнение).", "cat": "obl" }, { "term": "Debitor", "gloss": "длъжник", "body": "Пасивната страна на облигационното отношение (obligatio*), от която може да се изисква изпълнение на престацията в полза на другата (активната) страна-кредитор (creditor*).", "cat": "obl" }, { "term": "Delegatio", "gloss": "делегация или цесия", "body": "Правен акт, чрез който едно лице (делегант) поканва едно друго лице (делегат) да изпълни по отношение на едно трето лице (делегатар) определена престация (delegatio solvendi), или да се ангажира към това лице да извърши престацията (delegatio obligandi). Този юридически акт може да има новационен характер (delegatio novatio) тогава, когато съществува едно предходно облигационно отношение било между делегата към делегата, и след това то се замества чрез задължението на делегата към делегатаря (цесия на задължението, или пък признаване на задължението).", "cat": "obl" }, { "term": "Delictum", "gloss": "деликт", "body": "Понятие, свързано с неправомерно действие, което се състои в посегателство върху личността или върху имуществото на друго лице, и", "cat": "obl" }, { "term": "Depositum", "gloss": "договор за влог", "body": "Двустранен несъвършен реален договор (срв. obligationes re contractae), който се състои в прехвърляне на държането на една движима вещ от депонента (влогодателя) на депозитаря (влогоприемателя), по силата на което влогоприемателят трябва да я пази и да я върне на влогодателя в уговорения срок. Различават се няколко типа влог:\n– depositum miserabile (нередовен влог): особен вид влог, който се характеризира с прехвърляне на право на собственост върху една потребима вещ, по принцип парична сума, от влогодателя на влогоприемателя, да със задължението влогоприемателят да върне същата сума или същия вид или род вещи от същото качество като получените (tantundem).\n– depositum necessarium (необходим влог): особен вид договор за влог, който се характеризира с предоставяне на държането (detentio) на една вещ от влогодателя на влогоприемателя в някаква особена ситуация на опасност – пожар, корабокрушение или други подобни, която не позволява на влогодателя да избира влогоприемателя. Това води до едно осъждане в двоен размер срещу влогоприемателя в случаи на неизпълнение на облигационното отношение.\n– depositum sequester, или in sequestrem (секвестър): особен вид договор за влог, който се характеризира с цялостното предоставяне (in solidum) на трето лице на вещ, за която две страни водят спор за правото на собственост, за да я пази за чиято санкция е основана върху закона за влог (obligationes ex delicto).", "cat": "obl" }, { "term": "Dicta et promissa", "gloss": "гарантирани и обещани качества", "body": "В договора за покупко-продажба (emptio venditio*) особени качества, които продавачът (venditor*) гарантира изрично (dicta) на купувача (emptor*) и/или му обещава (promissa), че съществуват.", "cat": "obl" }, { "term": "Dies", "gloss": "ден, срок", "body": "Бъдещо събитие, чието настъпване е сигурно (certus an); може да бъде свързан с пораждането (dies a quo или суспензивен срок) или погасяването (dies ad quem, или прекратителния срок) или на едно облигационно отношение. Срокът е определен, когато се знае точната дата на настъпването (dies certus an certus quando) или пък неопределен, когато не се знае този момент, но е сигурно, че той ще настъпи (dies certus an incertus quando).", "cat": "obl" }, { "term": "Dies interpellat pro homine", "gloss": "срокът има предимство пред човека", "body": "По принцип след изпадане на длъжника (debitor*) в забава (mora*) е необходимо кредиторът да направи съответното предизвестие. Но при задълженията, които са с определен срок (dies*), е достатъчно изтичането му, за да се счита длъжникът в забава.", "cat": "obl" }, { "term": "Diligentia", "gloss": "дължима грижа", "body": "Грижливост, действия, които всеки добър стопанин полага за управлението и запазване на своето имущество. По времето на Късната империя се счита, че съществуват степени на тази грижа, така както съществуват и по отношение на вината (culpa*). Diligentia exactissima е синоним на отговорността за пазене (срв. custodia*).", "cat": "obl" }, { "term": "Diligentia quam", "gloss": "debitor) in suis rebus adhibere solet (дължима грижа, която длъжникът полага по отношение на своите лични дела", "body": "Критерий за оценка на договорната отговорност, според който се очаква длъжникът (debitor*) да се отнася със същата грижливост към предмета на договора, като тази, която прилага спрямо своите собствени дела. Критерият се прилага също при дружествата (societas*), а в следкласическото право и по отношение на отговорността на настойника (tutor*). Изразът понякога се използва и в съкратена версия-грижа като свое (diligentia quam suis).", "cat": "obl" }, { "term": "Do ut facias", "gloss": "давам, за да направиш", "body": "Една от четирите форми на наименованите договори според класификацията на византийските юристи (conventiones sine nomine*), която се състои в предоставяне на правото на собственост върху една вещ, с цел да се получи от насрещната страна извършване на определено действие (facere*).", "cat": "obl" }, { "term": "Dolus", "gloss": "malus) (умисъл, злоумисъл", "body": "Термин, който има различни значения:\n— порок на съгласието при договорите: хитрост, манипулиране и всеки подобен акт, с който се уврежда едно лице или се измамава, за да бъде принудено да сключи определен договор;\n— всякакво поведение, което се противопоставя на изискването за добросъвестност (bona fides*);\n— критерии за договорна отговорност: умисъл или злоумисъл, които водят до неизпълнение или лошото изпълнение на едно облигационно отношение; към него понякога се приравнява по правни последици и неизпълнението поради груба небрежност.", "cat": "obl" }, { "term": "Dolus causain dans", "gloss": "измама като правно основание", "body": "Понятие, създадено през Средновековието, което определя измамата (dolus*), като начин фрагменти от текстовете на класическите римски юристи, събрани и класифицирани от специална комисия, председателствана от юриста Трибониан (срв. Corpus iuris civilis*).", "cat": "obl" }, { "term": "Dolus incidens", "gloss": "инцидентна измама", "body": "Израз, който не е използван автентично в римското право, за означаване на упражнена от една от страните по договора измама, която не е с такава тежест, че да доведе до недействителност на волеизявлението. Инцидентната измама най-често води до намаляване на дължимата престация.", "cat": "obl" }, { "term": "Dolus semper praestatur", "gloss": "винаги трябва да се носи отговорност за измама", "body": "Израз, който означава, че при всеки договор и при всички обстоятелства се отговаря за измама (dolus).", "cat": "obl" }, { "term": "Donatio", "gloss": "дарение", "body": "Правен акт без определена форма, с който едно лице, което има намерение да дари (animus donandi), се отказва от части от своето имущество в полза на друго лице, което се обогатява. на въздействие върху волеизявлението на другата страна, при което тя сключва договор и при липсата на което той никога не би бил сключен. Dolus causam позволява договорът да бъде обявен за нищожен, за разлика от dolus incidens /случайна измама/.", "cat": "obl" }, { "term": "Emptio rei speratae", "gloss": "покупка на бъдеща вещ", "body": "В случая, когато договорът за покупко-продажба (emptio venditio*) е за една бъдеща вещ (emptio rei speratae), която може да не възникне или да", "cat": "obl" }, { "term": "Emptio spei", "gloss": "алеаторна покупка, покупка на простия шанс", "body": "В случаите, когато договорът за покупко-продажба е за една вещ, чието съществуване е алеаторно (emptio spei), купувачът всъщност купува простия „шанс“, надеждата, че вещта ще съществува, без да има сигурност за това. Договорът (emptio venditio) е в т.нар. опростен вид по съвременното право и има всички белези за алеаторен договор.", "cat": "obl" }, { "term": "Emptio tollit locationem", "gloss": "покупко-продажбата прекратява наемния договор", "body": "Правило, свързано с продажбата на една отдадена под наем вещ от наемодателя на трето лице. В резултат на това наемателят губи правото на ползване на вещта, ако третото лице претендира тя да му бъде предадена във владение.", "cat": "obl" }, { "term": "Emptio venditio", "gloss": "покупко-продажба", "body": "Двустранен съвършен консенсуален договор (срв. obligationes consensu contractae*), по силата на който продавачът (vendor*) се задължава да предостави на купувача (emptor*) владението и необезпокояваното ползване на една вещ (merx*), срещу определена в пари цена (pretium*), върху която се придобива право на собственост.", "cat": "obl" }, { "term": "Emptor", "gloss": "купувач", "body": "Страна по договора за покупко-продажба (emptio venditio*), която получава вещта от продавача (venditor*) срещу определена сума пари.\n– error in negotio (грешка в същността на договора);\n– error in persona (грешка в личността на договарящите се страни);\n– error in quantitate (грешка в количеството на дължимата престация);\n– error in substantia (грешка в съдържанието, в същността на престираната вещ).", "cat": "obl" }, { "term": "Errantis voluntas nulla est", "gloss": "нищожна е волята на лицето, което е изпаднало в грешка", "body": "Правило за подчертаване на грешката, която не създава задължение за лицето, спрямо което съществува.", "cat": "obl" }, { "term": "Error", "gloss": "грешка", "body": "Порок на съгласието (consensus*), който се състои в погрешна представа за действителността и това води до липса на съгласие между договарящите страни. Ако грешката се отнася до съществен елемент на договора, тя води до неговата нищожност.\nСъществуват различни видове грешки:\n- error in corpore (грешка във физическата идентичност на вещта); не съществува, договорът се сключва под отлагателно (суспензивно) условие (condicio*). Той не поражда пълен ефект, ако вещта не съществува или в крайна сметка не възникне.", "cat": "obl" }, { "term": "Essentialia negotii", "gloss": "съществени елементи на правния акт", "body": "Това са съществени елементи на правния акт, за които трябва да се отнася волеизявлението или съгласието на страните (consensus*), за да бъде той валиден.", "cat": "obl" }, { "term": "Evictio", "gloss": "евикция", "body": "Ситуация, в която купувачът (emptor*) на една вещ, за която продавачът (venditor*) му е прехвърлил владението, е лишен от него в резултат на уважаване на иска на нейния действителен собственик (срв. reivindicatio*), или на титуляра на ограничено вещно право върху нея (частична евикция). Купувачът може да получи гаранция от продавача срещу евентуална евикция чрез два вида стипулации – stipulatio duplae* или stipulatio rem habere licere*.", "cat": "obl" }, { "term": "Exercitor", "gloss": "екзерцитор, корабен предприемач", "body": "С този термин се означава лицето, което наема кораби, с цел извършване на морски превоз и търговия, и които по силата на преторски едикт (edictum) носи пълна отговорност за всички. най-стария жив родственик по мъжка линия (срв. agnatio*), който е същност е домовладелец (paterfamilias*).", "cat": "obl" }, { "term": "Expensilatio", "gloss": "експенсилация, вписване на разход", "body": "Използвана от III век сл.Хр. насетне писмена форма, с която кредиторът (creditor) внася в своята сметководна книга (codex accepti et expensi) едно задължение като разход. По този начин той създава литерално задължение (obligationes litteris contractae), основано на фиктивен заем.", "cat": "obl" }, { "term": "Facere", "gloss": "да направя, да извърша някакво действие", "body": "Облигационно отношение (obligatio*), което е свързано с извършване на някакво действие, най-вече с извършване на услуги.", "cat": "obl" }, { "term": "Facio ut des", "gloss": "правя, за да дадеш", "body": "Една от четирите форми на ненаименованите договори според класификацията на византийските юристи (срв. conventiones sine nomine*), която се състои в извършване на някакво действие (facere*), с цел насрещната страна да извърши прехвърляне на право на собственост върху една вещ (dare*).", "cat": "obl" }, { "term": "Facio ut facias", "gloss": "правя, за да направиш", "body": "Една от четирите форми на ненаименованите договори според класификацията на византийските юристи (срв. conventiones sine nomine*), която се състои в извършване на някакво действие (facere*), с цел насрещната страна да извърши реципрочно действие.", "cat": "obl" }, { "term": "Favor creditoris", "gloss": "в полза на кредитора", "body": "Израз, с който определен правен акт, в който се съдържа неясни или противоречива клауза, трябва да се тълкува в смисъл (срв. interpretatio*), който гарантира по най-добър начин интересите на кредитора (creditor*).", "cat": "obl" }, { "term": "Favor debitoris", "gloss": "в интерес на длъжника", "body": "Израз, с който определен правен акт, в който се съдържа неясна или противоречива клауза, трябва да се тълкува в смисъл (срв. interpretatio*), който гарантира по най-добър начин интересите на длъжника (debitor*).", "cat": "obl" }, { "term": "Favor promissoris", "gloss": "в полза на гарантиращия", "body": "Израз, с който една стипулация (stipulatio*), която не е ясна, трябва да се тълкува в смисъл", "cat": "obl" }, { "term": "Fenus", "gloss": "лихва", "body": "В обикновения заем /заем за потребление/ (mutuum*) лихвата е уговорена в процент върху заетия капитал и се начислява месечно в полза на заемодателя. Лихвеният заем се нарича също и морски заем (fenus nauticum*), или pecunia traiecticia.", "cat": "obl" }, { "term": "Fenus nauticum", "gloss": "морски заем", "body": "Израз, използван по времето на Късната Империя за определяне на съглашението, с което едно лице заема пари на един корабен предприемач (exercitor*), с цел осъществяване на морска търговия при свободно определена лихва, която е била между 22% и 33% годишно.", "cat": "obl" }, { "term": "Fideiussio", "gloss": "фидеюсия", "body": "Договор за поръчителство (срв. cautio*), сключен с произнасяне на тържествени изрази (contractus verbis*). С него поръчителят изрази задължението да плати на кредитора (creditor*) задължението на главния длъжник (id quod debet), ако той не го изпълни.", "cat": "obl" }, { "term": "Fideiussio indemnitatis", "gloss": "обезщетителна фидеюсия", "body": "Наименование, дадено в съвременната романистика, за означаване на поръчителство (fideiussio*), при което поръчителят приема (cautio*) да плати не целия дълг на главния длъжник, а само това, което длъжникът не е успял да плати, след осъждането му по иска на кредитора (creditor*).", "cat": "obl" }, { "term": "Fidepromissio", "gloss": "фидепромисия", "body": "Архаична форма на поръчителство, осъществявана чрез произнасянето на тържествени изрази (срв. interpretatio*), който гарантира най-добре интересите на промитента (promissor*).", "cat": "obl" }, { "term": "Fides", "gloss": "доверие, лоялност, спазване на обещанието).", "body": "Морален и правен принцип, според който трябва да се изпълняват поетите задължения, като се спазва критерият за добросъвестност (bona fides*). Принципът еволюира в различните периоди от историята на римското право.", "cat": "obl" }, { "term": "Foedus", "gloss": "договор", "body": "Международно съглашение, договор, сключен в тържествена форма и с ритуални церемонии между две държави и поставен по тази причина под закрилата на боговете.", "cat": "obl" }, { "term": "Forum", "gloss": "форум, обществено място", "body": "(1) Обществено място в Рим, което е център на политически и правен живот. Там са се събирали трибутните комиции (comitia tributa*), там преторите (praetor*) и съдиите (iudex*) са осъществявали правораздаването.\n(2) Компетентен съд, пред който ищецът трябва да представи спора, съответно да заведе своята искова молба. зи (contractus verbis*), чрез която (cautio*) поръчителят се задължава да плати същото, което се дължи от главния длъжник (idem quod debet). Този тип поръчителство е допустим както за чужденци (perigrini*), така и за римски граждани (civis Romanus*) за разлика от sponsio*, която може да бъде използвана само от римски граждани (civis Romanus*).", "cat": "obl" }, { "term": "Fraus", "gloss": "измама", "body": "Всякакъв акт на измама от една страна по договора по отношение на другата, основано на умисъл (dolus malus*).", "cat": "obl" }, { "term": "Furtum", "gloss": "кражба", "body": "Деликт (delictum*), който се състои в умишлено и тайно отнемане (кражба) или ползване на една чужда вещ в своя полза (злоупотреба с доверие).", "cat": "obl" }, { "term": "Furtum manifestum", "gloss": "флагрантна кражба", "body": "Деликт (delictum*), състоящ се в кражба или в злоупотреба с доверие (furtum*), при която извършителят е заловен на местоизвършването. Този деликт води до осъждането му за четворната стойност на откраднатата вещ.", "cat": "obl" }, { "term": "Furtum nec manifestum", "gloss": "обикновена кражба", "body": "Деликт (delictum*), извършен от крадеца, който не е заловен на местоизвършването. Той е осъждан на двойната стойност на откраднатата вещ.", "cat": "obl" }, { "term": "Furtum possessionis", "gloss": "кражба на владеене", "body": "Деликт (delictum), извършван от собственика на една вещ, която се намира в притежание на друго лице, имащо интерес да я задържи, и от което собственикът противоправно я отнема-например залогодателят (срв. pignus*), плодоползвателят (срв. ususfructus*), заемателят за послужване (срв. commodatum*).", "cat": "obl" }, { "term": "Furtum usus", "gloss": "кражба на ползване", "body": "Деликт (delictum), свързан с ползване без правно основание на една чужда вещ, без намерение тя да се присвои. Този деликт се осъществява например от влогоприемателя, който ползва вложената вещ без позволението на влогодателя (срв. depositum). измени смисълът на определени думи, изрази или целия текст. Така наречената Основна глоса (glossa ordinaria), наричана още Глосата на Acursius, е компилация от многобройни глоси, включени в полетата на ръкописите на Corpus iuris civilis от докторите по право от XII и XIII век. Тя е съставена от Акурсий към 1250 година от новата ера.", "cat": "obl" }, { "term": "Genera non pereunt", "gloss": "родовете никога не погиват", "body": "Принцип, според който никога не може да е невъзможна за изпълнение престация за родово определени вещи, защото длъжникът винаги може да намери вещ от същия род (genus), с която да изпълни задължението си (сходен израз: genus nunquam perit).", "cat": "obl" }, { "term": "Gestio", "gloss": "управление", "body": "Правни или фактически действия на едно лице, които го извършва в чужд патримониум.", "cat": "obl" }, { "term": "Habere licere", "gloss": "в притежание", "body": "Обещание, дадено от продавача (venditor*), на купувача (emptor*), че той може да ползва необезпокоявано продадената вещ (rem habere licere). В случаите на евикция (evictio*) купувачът има право да получи равностойността на вещта. Вж. и stipulatio rem habere licere*.", "cat": "obl" }, { "term": "Honorarium", "gloss": "хонорар", "body": "Заплащане, направено от манданта (mandator*) на мандатаря (mandatarius*) в благодарност за извършвани от него действия по изпълнение на договора за мандат (mandatum*).", "cat": "obl" }, { "term": "Id quod interest", "gloss": "това, което е мой интерес", "body": "Общ израз за определяне на размера на обезщетението за вреди като функция от законния интерес на страната, която ги е претърпяла. В договорните отношения обезщетението е съответно на интереса, който страната има от точното и пълно изпълнение на договора и който в съвременното право се нарича „положителен интерес“.", "cat": "obl" }, { "term": "Impensae", "gloss": "разходи, разноски", "body": "Направите разходи по отношение на една чужда вещ. Различават се три вида разходи:\nа) impensae necessariae (необходими разходи) – които са направени за поддръжката на вещта и с оглед да се избегне нейното разрушаване или унищожаване;\nб) impensae utiles (полезни разноски) – които имат за резултат увеличаването на стойността на вещта;\nв) impensae voluptuosae или voluptariae (луксозни разноски) – които имат за резултат разкрасяването или придаването на по-приятен вид на вещта.", "cat": "obl" }, { "term": "Imperitia", "gloss": "несръчност", "body": "Специфичен критерий във връзка с договорната отговорност на длъжника (debitor*), който се е задължил по силата на един договор (contractus) за изпълнение на някаква техническа работа според занятието му (най често по договор за наем на трудов резултат – locatio-).", "cat": "obl" }, { "term": "Impossibilium nulla obligatio est", "gloss": "Нищожно е облигационното отношение с невъзможна за изпълнение престация", "body": "Принцип от договорното право (contractus), според който е налице нищожност на облигационното отношение (obligatio), ако дължимата престация е невъзможна към момента на установяването ѝ от страните (начална невъзможност).", "cat": "obl" }, { "term": "In diem addictio", "gloss": "съглашение за разваляне на договора", "body": "Допълнителна (акцесорна) клауза в договор за покупко-продажба (emptio venditio), създадена с добавен пакт (pactum adiectum), с която продавачът (venditor) може до опреде- conductio operis или договор за наем на работа, locatio-conductio operarum). В случаите, когато той няма (или не прояви) изискуемите професионални качества, отговаря за причинените в резултат на неговата несръчност технически грешки при изпълнение на договора.", "cat": "obl" }, { "term": "Iniuria", "gloss": "инюрия", "body": "Терминът има две значения:\nлен срок да развали договора, ако друг купувач (emptor*) му предложи по-висока цена.", "cat": "obl" }, { "term": "Intercessio", "gloss": "интерцесия, право на вето", "body": "(1) Противопоставяне на магистрат (magistratus*) на мерките, които иска да предприеме неговия колега.\n(1) в по-широк смисъл: всяко противоправно действие, срв. damnum iniuria datum*;\n(2) в по-тесен смисъл: съзнателно и обидно посегателство върху личността на едно свободно лице.", "cat": "obl" }, { "term": "Interpellatio", "gloss": "интерпелация, покана", "body": "Искане на кредитора (creditor*) към длъжника (debitor*), с което го кани изрично да изпълни дължимата престация. Вж също dies interpellat pro homine*.", "cat": "obl" }, { "term": "Interpretatio contra stipulatorem", "gloss": "тълкуване срещу стипуланта", "body": "Първоначално изразът се използва предимно във връзка с договора за стипулация (stipulatio*). Когато смисълът на въпроса, зададен от стипуланта* не е ясен, съдията тълкува в по-неблагоприятен за него смисъл. В по-широк смисъл принципът означава, че когато една договорна клауза е двусмислена, тя трябва да се тълкува в по-неблагоприятен за страната, която я е поставила.", "cat": "obl" }, { "term": "Interpretatio in favorem negotii", "gloss": "тълкуване в полза на действителността на правната сделка", "body": "Принцип за тълкуване (interpretatio*) на правната сделка, при който се дава приоритет на тълкуването, чрез което се дава възможност да се запази нейната действителност.", "cat": "obl" }, { "term": "Ius noxae dandi", "gloss": "право на ноксално изоставяне", "body": "Право, предоставено на собственика (dominus*) на един роб (servus*) или на paterfamilias* на едно подвластно лице (alieni iuris*), когато това лице е извършило увреждане на трето лице.", "cat": "obl" }, { "term": "Iussum", "gloss": "нареждане, заповед", "body": "Изрично или мълчаливо нареждане или овластяване, отправено към едно трето лице, да сключи правна сделка; понякога с термина се означава и самото нареждане.", "cat": "obl" }, { "term": "Iusurandum in litem", "gloss": "съдебна клетва", "body": "Клетва, положена от ищеца по време на процеса, с която се потвърждава направената от него оценка на вещта, чието връщане се претендира. Размерът на сумата по оценката след това се включва в произнесената от съдията кондамнация.", "cat": "obl" }, { "term": "Laesio enormis", "gloss": "прекомерно ощетяване", "body": "Израз, създаден от глосаторите, с който се означава осъществяването на неизгодна юридическа операция от едно лице. В римското право прекомерното ощетяване е санкционирано едва в Късната Империя за защита на продавача (venditor*) на недвижим имот, който го е продал на цена, по-ниска от половината от действителната цена (pretium iustum*).", "cat": "obl" }, { "term": "Leges emptionis et venditionis", "gloss": "клаузи за покупка и продажба", "body": "Особени клаузи, установени от страните по договор за покупко-продажба (emptio venditio*). От този род са комисорния пакт (lex commissoria*), продажбата с уговорка за опитване (pactum displicentiae*), пактът за обратно изкупуване (pactum de retroemendo) и уговорката за разваляне на договора до определен срок (in diem addictio*).", "cat": "obl" }, { "term": "Lex commissoria", "gloss": "комисорен пакт", "body": "(1) Допълнителна (акцесорна) клауза в договор за продажба (emptio venditio*), въведена с допълнителен пакт (pactum adiectum*), с което продавачът (venditor*) може да развали договора, ако цената не е платена в определен срок\n(2) Споразумение между заложния кредитор и длъжника, по силата на което кредиторът става собственик на заложената вещ (pignus*), ако длъжникът не си плати дълга. Това споразумение е забранено от император Константин.", "cat": "obl" }, { "term": "Lex contractus", "gloss": "клауза в договора", "body": "Допълнителна (акцесорна) клауза в договора. Вж. leges emptionis et venditionis*, leges mancipii*. Lex Cornelia de sponsu\nЗакон, гласуван през 81 г. пр.Хр., който се прилага за най-древните форми на поръчителството (sponsio*) и фидеюсията (fideiussio*). Той забранява на едно лице да бъде поръчител на един и същ длъжник в рамките на една година за повече от 20 000 сестерции.", "cat": "obl" }, { "term": "Licet mercatoribus sese invicem circumvenire", "gloss": "позволено е търговците взаимно да се надхитрят", "body": "Израз, подчертаващ, че в търговските отношения е позволено всяка от страните да се опитва да получи по-благоприятни условия по сделката от своя съдоговорител. Изключение от правилото е налице при защита на лицата под 25-годишна възраст (срв. lex Laetoria de minoribus*).", "cat": "obl" }, { "term": "Locatio-conductio", "gloss": "договор за наем", "body": "Съвършен двустранен консенсуален договор (срв. obligationes consensu contractae*), при който едната страна предоставя на другата една вещ за ползване (locatio-conductio rei*), предоставя й свои услуги (locatio-conductio operarum*) или поема задължение да извърши определена работа (locatio-conductio operis*) срещу определена цена (merces locationis*).", "cat": "obl" }, { "term": "Locatio-conductio operarum", "gloss": "договор за наем на труд/ услуга", "body": "Особен вид договор за наем (locatio-conductio*), който е съвършен двустранен консенсуален договор (locatio-conductio operarum) при който една от страните – работник (locator*), се задължава да извършва определена работа за определен срок, а другата страна – предприемач (conductor*) се задължава да й плати съответно възнаграждение.", "cat": "obl" }, { "term": "Locatio-conductio operis", "gloss": "договор за наем на трудов резултат, договор за изработка", "body": "Особен вид договор за наем (locatio-conductio*), който е съвършен двустранен консенсуален договор (locatio-conductio operis), с който една- та от страните-изпълнитетел (conductor*), се задължава да извърши определена работа с материали на другата страна – клиент (locator*), срещу определено възнаграждение.", "cat": "obl" }, { "term": "Locatio-conductio rei", "gloss": "договор за наем на вещ", "body": "Особен вид договор за наем (locatio-conductio*), който е съвършен двустранен консенсуален договор (locatio-conductio rei), при който едната страна (locator*) предоставя на другата страна ползването на една вещ срещу задължението на наемателя (conductor*), да заплати определено възнаграждение под формата на наем (merces locationis*).", "cat": "obl" }, { "term": "Locator", "gloss": "наемодател", "body": "При договора за наем (locatio-conductio*) това е страната, която предоставя на другата страна една вещ, или клиентът при договора за изработка (locatio-conductio operis*), или работникът при трудовия договор (locatio-conductio operarum*).", "cat": "obl" }, { "term": "Lucrum cessans", "gloss": "пропусната полза", "body": "Пропуснато увеличение на имуществото на едно лице. Една от формите на имуществено увреждане – другата е реално претърпяната щета (damnum emergens*).", "cat": "obl" }, { "term": "Magister bonorum", "gloss": "управляващ имуществото", "body": "Лице, посочено от кредиторите на несъстоятелен длъжник със съгласието на претора (praetor*), за да подготви публичната продажба на търг на цялото му имущество (bonorum venditio*).", "cat": "obl" }, { "term": "Magister navis", "gloss": "капитан на кораб", "body": "Лице, което носи отговорност за кораба. Той е обвързан или с трудов договор (locatio-conductio operarum*), или с договор за мандат (mandatum*), който сключва с корабния предприемач (exercitor*).", "cat": "obl" }, { "term": "Mandatarius", "gloss": "мандатар", "body": "Една от страните по договор за мандат (mandatum*), която по силата на договора трябва да извърши за мандатаря (mandator*) определена работа, с която е натоварен, или услуги, които е обещал.", "cat": "obl" }, { "term": "Mandator", "gloss": "мандант", "body": "Едната от страните по договор за мандат (mandatum*), която по силата на договора натоварва мандатаря (mandatarius*) да изпълни безвъзмездно определена работа. Мандантът трябва да заплати разноските и евентуалните вреди, възникнали при изпълнение на договора.", "cat": "obl" }, { "term": "Mandatum", "gloss": "договор за мандат, договор за поръчка, от manu datum = помагам, поверявам", "body": "Несъвършен двустранен безвъзмезден консенсен договор (вж. obligationes consensu contractae*), с който една от страните – мандатар (mandatarius*), се задължава към другата-мандант (mandator*), да извърши определена работа, поръчана от манданта или услуги, които му е обещал.", "cat": "obl" }, { "term": "Mandatum pecuniae credendae", "gloss": "мандат за даване на кредит", "body": "Особен вид договор за поръчка (mandatum*), при който мандантът (mandator*) дава нареждане на мандатаря (mandatarius*) да заеме определена сума (mutuum*) пари на трето лице, което става длъжник на мандатаря. В този вид договор мандатът включва гаранционна функция спрямо мандатаря, който чрез actio mandati contraria (срв. actio mandati*), може да търси от манданта обезщетение за евентуални вреди във връзка с кредита (например невръщането на дълга от заемателя). Коментаторите наричат този договор mandatum qualificatum.", "cat": "obl" }, { "term": "Merces locationis", "gloss": "наем", "body": "Парична контрапрестация на наемателя (conductor*) към наемодателя (locator*), който му е предоставил ползването под наем на една вещ (locatio-conductio rei*).", "cat": "obl" }, { "term": "Merx", "gloss": "стока", "body": "Термин за означаване на всички движими вещи, които могат да бъдат обект на договор за продажба (emptio venditio*), с изключение на робите (homo*).", "cat": "obl" }, { "term": "Metus", "gloss": "морално насилие, страх, заплашване", "body": "Основателен страх, който се счита за един от пороците на съгласието. Той е налице, когато една от страните по договора (contractus*) или по друго съглашение (conventio*) се задължава под влияние на заплаха, отправена от друга страна, да извърши определена престация.", "cat": "obl" }, { "term": "Mora", "gloss": "забава", "body": "Различава се:\n(1) mora creditoris (забава на кредитора), mora accipiendi (забава за приемане): — когато кредиторът (creditor*) не приема на определено място и в определения момент валидно предложената му от длъжника (debitor*) престация;\n(2) mora debitoris (забава на длъжника), mora solvendi (забава за плащане): — когато длъжникът (debitor*) закъснява с изпълнението на дължимата престация.", "cat": "obl" }, { "term": "Mutuum", "gloss": "заем за потребление", "body": "Едностранен реален (срв. obligationes re contractae*) договор, който се сключва с прехвърляне на правото на собственост върху парична сума или други потребими вещи (срв. res*) от заемодателя на заемателя, който от своя страна се задължава да върне на определена дата същата сума пари или потребими вещи от същия род и качество като тези, които е получил (tantundem). Този договор е санкциониран с condictio* – иск по стриктното право.", "cat": "obl" }, { "term": "Naturalia negotii", "gloss": "естествени елементи на договора", "body": "Естествени елементи на договора (contractus*), които го характеризират (като определен договорен вид). Наред с тях има и съществени елементи на договора (essentialia negotii*).", "cat": "obl" }, { "term": "Nauticum fenus", "gloss": "морски заем", "body": "Виж fenus nauticum*.", "cat": "obl" }, { "term": "Negotiorum gestio", "gloss": "водене на чужда работа /без поръчка/", "body": "Воденето на чужда работа /без поръчка/ е правно отношение, което произтича от спонтанното действие на гестора, който без съгласието (и/или в отсъствието) на едно лице извършва едно или повече фактически или правни действия в негова полза. Ако гесторът е започнал действие, трябва да го извърши според интереса и предполагаемото намерение на това лице. То от своя страна е задължено да приеме действие (или резултатите от него) и да заплати разноските, които гестора е направил. При неизпълнение на това задължение срещу него може да се предяви actio negotiorum gestorum*. Правните последици от воденето на чужда работа без поръчка се пораждат от самите действия в чужда сфера, а не от съществуващ договор (contractus*) с гестора или съглашение между страните (вж. obligationes consensu contractae*). В Институциите на Юстиниан (свв. Corpus iuris civilis*) тези отношения са определени като квазиконтракти (срв. obligationes quasi ex contractu*).", "cat": "obl" }, { "term": "Negotium", "gloss": "сделка", "body": "Всеки позволен от правото акт, който създава облигационно отношение на възмездно основание. Задълженията могат да се пораждат било от определен договор или от едностранно волеизявление.", "cat": "obl" }, { "term": "Negotium mixtum cum donatione", "gloss": "сделка, която съдържа и елемент на дарение", "body": "Правен акт, който по принцип е възмезден, но съдържа елементи на дарение (donatio*), например, ако цената е занижена спрямо пазарната.", "cat": "obl" }, { "term": "Nexum", "gloss": "нексум", "body": "Архаичен институт, споменат Закона на Дванадесетте таблици (Lex XII tabularum), според който длъжникът (debitor) по силата на един двустранен юридически акт се задължава със своята личност към кредитора (creditor), ако не изпълни задължението си. Той се поставя физически под властта на кредитора. Считало се е, че длъжникът отдава сам себе си в залог.", "cat": "obl" }, { "term": "Nexus", "gloss": "обвързан, окован, некс", "body": "Свободно лице (liber), което се поставя под фактическата власт на своя кредитор (creditor), като така гарантира изпълнението на своя дълг. Нексът е дългов роб и работи в полза на кредитора до момента на пълното погасяване на своя дълг.", "cat": "obl" }, { "term": "Nomina arcaria", "gloss": "касов дълг", "body": "Вписване, извършено от домовладелеца (paterfamilias) в сметководната му книга (codex accepti et expensi) на направени приходи или разходи, с което той създава литерално задължение за друго лице (obligationes litteris contractae).", "cat": "obl" }, { "term": "Nomina transscripticia", "gloss": "задължения с транскрипция/замяна/", "body": "Вписване, извършено от домовладелеца (paterfamilias) в сметководната му книга (codex accepti et expensi), с което се поражда литерално задължение (obligationes litteris contractae) в негова полза било като замества дълга на едно лице с дълг на друго лице, или като замества едно обикновено задължение с литерално. Различават се:\n(1) transscriptio a persona in personam (транскрипция /замяна/ на едно лице с друго): Формално вписване в сметководната книга (codex accepti et expensi*) на домовладелеца (paterfamilias*) с цел да се породи облигационно отношение (срв. obligationes litteris contractae*), като се смени длъжникът. Така първият длъжник се вписва като платил, а новият длъжник се вписва като задължен за същата сума.\n(2) transscriptio a re in personam (транскрипция /замяна/ на дълг с лице): Формално вписване в сметководната книга (codex accepti et expensi*) на домовладелеца (paterfamilias*) с цел да се породи облигационно отношение (срв. obligationes litteris contractae*), като страните осъществяват новация (novatio*), променяйки характера на задължението на длъжника. Така например цената по един договор за покупко-продажба може да се трансформира в заем, като кредиторът вписва погасяване на стария дълг и същевременно установява нов дълг на същия длъжник, но на друго правно основание.", "cat": "obl" }, { "term": "Novatio", "gloss": "новация", "body": "Правна операция, която основно се осъществява чрез стипулация (stipulatio*), и с която съществуващото облигационно отношение се погасява, като на негово място се поражда ново със същия обект, но с някакви нови елементи (продължителност, срок и др.). Тя може да се съчетае с цесия на дълга (delegatio*).", "cat": "obl" }, { "term": "Noxa", "gloss": "ноксален режим", "body": "Архаичен термин, използван като синоним на деликт (delictum*), и по-специално за означаване на отговорност на неподвластно лице (sui iuris*) за деликти извършени от неговите подвластни (alieni iuris*). Това е отговорност на домовладелеца (paterfamilias*) за действията на децата му (alieni iuris*), както и на господаря (dominus*) за действията на неговите роби (servus*).", "cat": "obl" }, { "term": "Noxa caput sequitur", "gloss": "ноксалните искове следват лицето", "body": "Принцип, прилаган при ноксалния режим (noxa*), според който господарят или домовладелецът (paterfamilias*) на едно подвластно лице (alieni iuris*), което е извършило деликт (delictum*), носи отговорност за извършеното нарушение, дори ако това лице не е било под неговата власт в момента на извършването.", "cat": "obl" }, { "term": "Noxae deditio", "gloss": "ноксално изоставяне", "body": "Възможност за неподвластно лице (sui iuris*), което е подложено на ноксална отговорност, да изостави (предаде) своя подвластен извършител на деликта (delictum*) на потърпевшия от деликта, с което се освобождава от задължението да плати глобата и обезщетението за нанесени вреди. Ноксалното изоставяне на подвластния се извършва било чрез манципация (mancipatio*), или чрез прехвърляне под чужда власт (срв. mancipium*).", "cat": "obl" }, { "term": "Nudum pactum", "gloss": "гол пакт", "body": "Пакт (pactum*), който не е добавен към някой от основните видове контракти и по тази причина не е защитен с иск, а само с възражение (срв. nuda pactio actionem non parit, sed parit exceptionem*).", "cat": "obl" }, { "term": "Obligatio", "gloss": "облигационно отношение", "body": "Правна връзка, по силата на която едно лице - длъжник (debitor*) трябва да извърши определена престация в полза на друго лице – кредитор (creditor*). Той от своя страна може да предяви срещу длъжника иск (actio*), ако престацията не е изпълнена изцяло или е изпълнена неточно.", "cat": "obl" }, { "term": "Obligatio ad genus pertinet", "gloss": "родовоопределено задължение", "body": "Облигационно отношение, създадено по отношение на една родовоопределена (genus*), вещ (res*) или по отношение на вещ, на която страните са определили само най-общите качества.", "cat": "obl" }, { "term": "Obligatio alternativa", "gloss": "алтернативно облигационно отношение", "body": "Облигационно отношение (obligatio*), което се отнася за два или повече обекта, от които длъжникът (debitor*) може да избере свободно с кой от тях да изпълни своето задължение.", "cat": "obl" }, { "term": "Obligatio cum solutionis facultate", "gloss": "факултативно облигационно отношение", "body": "Облигационно отношение (obligatio*), което се отнася до един обект, но длъжникът (debitor*) може да се освободи от изпълнение, ако извърши друга (,,uno in obligatione, duae in solutione\") предварително уговорена с кредитора престация (факултативна възможност). Вж. също даване вместо плащане (datio in solutum*)", "cat": "obl" }, { "term": "Obligatio in solidum", "gloss": "солидарно задължение", "body": "Солидарното задължение е особен случай на облигация, при която може да има повече кре- дитори (creditor*) или повече длъжници (debitor*), които са обвързани с една единствена облигационна връзка (obligatio*). Налице е активна солидарност или активна кореалност при множество кредитори, като всеки от тях може да иска от длъжника цялостно изпълнение на вземането, а плащането на един от кредиторите освобождава длъжника по обект на другите. Пасивна солидарност или пасивна кореалност е налице при повече длъжници. Всеки от съдлъжниците носи отговорност за целия дълг към кредитора, но изпълнението на един от тях освобождава от отговорност другите.", "cat": "obl" }, { "term": "Obligatio naturalis", "gloss": "естествено задължение", "body": "Облигационно задължение (obligatio*), което е лишено от иск (actio*). Длъжникът (debitor*) може по свое осмотрение да го изпълни, но кредиторът (creditor*) няма никакъв иск, с който да го принуди да изпълни", "cat": "obl" }, { "term": "Obligationes consensu contractae", "gloss": "консенсуални облигационни отношения", "body": "Вид облигационни отношения, породени от договор по цивилно право – контракт (срв. obligationes ex contractu*), при който е достатъчно съгласието на страните (consensus*) за пораждане на облигационна връзка (това са договора за покупко-продажба (emptio venditio*), договора за наем (locatio conductio*), договора за поръчка (mandatum*), и договора за дружество (societas*). )", "cat": "obl" }, { "term": "Obligationes ex contractu", "gloss": "облигационни отношения, породени от контракт", "body": "Обща категория облигационни отношения, в които са включени всички облигации (obligatio*), породени от съглашение между страните (вж. contractus*).", "cat": "obl" }, { "term": "Obligationes ex delicto", "gloss": "облигационни отношения, породени от деликт", "body": "Обща категория облигационни отношения (obligatio*), които се пораждат в резултат на извършване на неправомерно увреждане (delictum*).", "cat": "obl" }, { "term": "Obligationes litteris contractae", "gloss": "литерални задължения", "body": "Вид облигационни отношения, породени от контракт (obligationes ex contractu*), в които се включват всички задължения, за пораждането на които освен съгласието (consensus*) на страните е необходимо особено вписване, извършено от една от страните или и от двете страни в сметководната книга (Вж. Codex accepti et expensi*).", "cat": "obl" }, { "term": "Obligationes quasi ex contractu", "gloss": "облигационни отношения, породени от квазиконтракт", "body": "Израз от Юстиниановото право, с който се означават задълженията (obligatio*), които не се пораждат от контракт (contractus*), а от друго позволено деяние, което ги доближава до контракта (например водене на чужда работа без поръчка (negotiorum gestio*) и неоснователно обогатяване (conditio indebiti*).", "cat": "obl" }, { "term": "Obligationes quasi ex delicto", "gloss": "облигационни отношения, породени от квазиделикт", "body": "Израз от юстиниановото право, с което се означават задълженията, които не са породени от деликт (delictum*) в стриктен смисъл, а от подобни деяния, или ако са извършени при лека небрежност – подкупен съдия, който не отсъжда обективно, или ако се носи отговорност за чужди деяния (напр. на ханджията за кражби в неговия хан).", "cat": "obl" }, { "term": "Obligationes re contractae", "gloss": "реални облигационни отношения", "body": "Вид породени от контракт облигационни отношения (obligationes ex contractu*), които включват задължения, създадени освен с постигане на съгласие (consensus*) между страните и с реалното предаване на вещта, която е обект на договорната връзка (заем за потребление (mutuum*), заем за послужване (commodatum*), влог (depositum*) и залог (pignus*)).", "cat": "obl" }, { "term": "Obligationes verbis contractae", "gloss": "вербални облигационни отношения", "body": "Вид породени от контракт облигационни отношения (obligationes ex contractu*), които включват задължения, създадени освен с постигане на съгласие (consensus*) между страните и с произнасянето на тържествени ритуални изрази (спонзия (sponsio*) и стипулация (stipulatio*)).", "cat": "obl" }, { "term": "Obligatus", "gloss": "обвързан, задължен", "body": "От класическия период насетне това е всяко лице, което е обвързано спрямо друго да извърши определена престация (срв. obligatio*).", "cat": "obl" }, { "term": "Officium", "gloss": "задължение, тежест, длъжност", "body": "В частното право с този термин се определя моралното задължение в сферата на фамилните или приятелските отношения (officium amicitiae). В публичното право терминът определя задачите, свързани с определена длъжност.", "cat": "obl" }, { "term": "Opus", "gloss": "труд, произведение", "body": "Работа, която е обект на задължението на предприемача (conductor*) да я заплати, при договора за наем на работа (locatio-conductio*).", "cat": "obl" }, { "term": "Os fractum", "gloss": "счупване на кост", "body": "Едно от телесните увреждания, предвидено в Закона на XII таблици, за което се предвижда [ducit] (ако е на свободен гражданин) или (delictum) (ако е на роб). Санкцията е била извънредно тежка, но по-късно през 500 г. е заменена с парична глоба, съобразена със социалното положение. траодинарната процедура (cognitio extra ordinem).", "cat": "obl" }, { "term": "Pactiones et stipulationes", "gloss": "пактове и стимулации", "body": "Съвкупност от пактове (pactum*) и стипулации (stipulatio*), които се разменят между страните, учредяващи поземлен сервитут (servitus praediorum*) или право на ползване (usufructus*) върху провинциален недвижим имот.", "cat": "obl" }, { "term": "Pactum", "gloss": "пакт", "body": "Пактът се включва в по-общото понятие за съглашение (conventio*). Той не е нито договор (contractus*), уреден в преторския едикт (edictum*), нито ненаименован договор (conventiones sine nomine*), а е неформално съглашение между страните, породено от тяхното общо намерение за създаване на облигационно отношение. Пактът не поражда иск (actio*), а само възражение (exceptio*), доколкото не е свързан (добавен) към някой контракт (pactum adiectum*) – в тези случаи той променя неговите правни последици.", "cat": "obl" }, { "term": "Pactum adiectum", "gloss": "добавъчен пакт", "body": "Неримски термин за означаване на добавъчно съглашение към един консенсуален договор (срв. obligationes consensus contractae*), с което се изменя неговото типично действие или правни последици. Ако е сключен едновременно с консенсуален договор (pactum in continenti*), той се санкционира с договорния иск (actio*). Вж. nuda pactio actionem non parit, sed parit exceptionem*.", "cat": "obl" }, { "term": "Pactum de", "gloss": "non) distrahendo (пакт за продажба, респ. за непродажба", "body": "Добавъчен пакт (pactum adiectum*) към договор за залог (pignus*) или ипотека (hypotheca*), чрез който кредиторът (creditor*) и длъжникът (debitor*) се договарят кредиторът да може (или да не може) да продаде предоставената в залога или ипотека вещ при неизпълнение на дълга на падежа и да прихване от получената цена своето вземане.", "cat": "obl" }, { "term": "Pactum de non petendo", "gloss": "пакт да не се търси чрез съд дължимото", "body": "Гол пакт (pactum nudum*), чрез който страните се договарят при определени условия кредиторът (creditor*) да не предявява към длъжника (debitor*) иск (actio*) за изпълнение на облигационно отношение (obligatio*).", "cat": "obl" }, { "term": "Pactum displicentiae", "gloss": "пакт за разваляне на договора, гаранционен пакт", "body": "Добавъчен пакт (pactum adiectum*) към договора за покупко-продажба (emptio venditio*), с който купувачът (emptor*) си запазва правото да развали договора в определен срок, ако купената вещ не му хареса. В този случай купувачът има право да получи обратно дадената цена, ако върне същата вещ на продавача (venditor*).", "cat": "obl" }, { "term": "Pactum ex intervallo", "gloss": "пакт, сключен след определено време", "body": "Пакт (pactum*), добавен след определен период към вече сключен контракт (contractus*).", "cat": "obl" }, { "term": "Pactum in continenti", "gloss": "пакт, сключен едновременно", "body": "Добавъчен пакт (pactum adiectum*), чието сключване е едновременно с това на контракта. (contractus*), към който е добавен. В този случай пактът е защитен от договорния иск (actio*).", "cat": "obl" }, { "term": "Pactum nudum", "gloss": "гол пакт", "body": "Пакт (pactum*), който не е добавен към договор (contractus*) и чието спазване се осигурява не с иск (actio*), а с възражение (exceptio*), включено във формулата (formula*) на иска на ищеца.", "cat": "obl" }, { "term": "Par condicio creditorum", "gloss": "в положението на кредитор", "body": "Принцип, според който всички кредитори (срв. creditor*) на един длъжник (debitor*) се третират по един и същ начин при принудителното изпълнение срещу длъжника (срв. bonorum venditio*).", "cat": "obl" }, { "term": "Pecunia", "gloss": "пари", "body": "Монети, с които се обслужва обръщението и които са обща мярка за стойност.", "cat": "obl" }, { "term": "Pecunia traiecticia", "gloss": "букв. „пренесени“ пари", "body": "Израз за означаване на паричен заем с цел осъществяване на морска търговия, която се нарича още и fenus nauticum.", "cat": "obl" }, { "term": "Per aes et libram", "gloss": "с бронз и везни", "body": "Така се наричат формалните правни актове на архаичното римско право, при които страни използват везни и късче бронз (mancipatio*, nexum*, nuncupatio*, coemptio, solutio per aes et libram*).", "cat": "obl" }, { "term": "Periculum emptoris perfecta emptione", "gloss": "рискът е за купувача от момента на извършване на прдoжбата", "body": "Принцип за разпределяне на риска при договора за продажба (emptio venditio*). След извършването на договора продавачът (venditor*) се освобождава от задължението си да предаде вещта (merx*), ако тя погине при непреодолима сила (vis maior*) или случайно събитие (casus fortuitus*), но купувачът (emptor*) остава задължен да плати уговорената цена (pretium*).", "cat": "obl" }, { "term": "Periculum in mora", "gloss": "риск при забава", "body": "Принцип, според който страната в забава (mora*) носи риска (и отговорността за неизпълнение) при случайни събития (casus fortuitus*) или непреодолима сила.", "cat": "obl" }, { "term": "Permutatio", "gloss": "замяна", "body": "Ненаименован договор, с който всяка от страните реципрочно се задължава да прехвърли на другата правото на собственост на една или повече вещи. Замяната е най-важният договор от типа do ut des (вж. conventiones sine nomine). При сключването му е необходимо, освен постигането на съгласие (consensus), поне една от страните по договора да е извършила своята престация.", "cat": "obl" }, { "term": "Perpetuatio obligationis", "gloss": "перпетуиране на облигационните отношения", "body": "Правна формула, според която, при невъзможност за изпълнение на облигационните отношения по вина на длъжника (debitor), то продължава да съществува. Това позволява той да бъде осъден на заплащане на стойността на вещта по това облигационно отношение. Тази фикция се използва в римското право в случаите на забава (mora) на длъжника до момента на предявяване на иска (actio) срещу него; така в случаите на виновна невъзможност на длъжника той носи отговорност за погиване или влошаване на състоянието на вещта при случайно събитие (срв. casus fortuitus и periculum in mora).", "cat": "obl" }, { "term": "Plebs", "gloss": "плебс", "body": "Политейски термин, използван за плебеите, които са се противопоставяли на патрициите. След дълга политическа борба трибуните на плебса са признати за народни представители. вземането, при задължение на кредитора, наричан също и заложен кредитор, да върне вещта, ако дългът се изпълни изцяло. С термина „pignus“ се означава както самият договор като източник на облигационни отношения, така и вещното обезпечение, създадено с този договор.", "cat": "obl" }, { "term": "Pollicitatio", "gloss": "полицитация, едностранно обещание", "body": "Извъндоговорното облигационно отношение, което се поражда от позволен правен акт (срв. obligationes quasi ex contractu*). Полицитацията (pollicitatio) се състои в едностранно обещание на римски гражданин (civis Romanus*) в полза на римската гражданска община (civitas*) за извършване на действия в обществен интерес, например издигане на сграда. Тя обвързва лицето, което е направило обещанието, когато работите вече са започнали.", "cat": "obl" }, { "term": "Praestare", "gloss": "гарантирам, нося отговорност за", "body": "Гаранционно задължение за постигане на определен резултат. То се явява като допълнително (акцесорно) към основните задължения за прехвърляне на правото на собственост (dare*) или за извършване на определено действие (facere*) и с него се изменят правните последици от изпълнение или неизпълнение на облигационни отношения.", "cat": "obl" }, { "term": "Pretium", "gloss": "цена", "body": "Съществен елемент на договора за покупко-продажба (emptio venditio*). Тази престация, дължима от продавача (venditor*), трябва да е действителна (verum), определена (certum) и в пари, а по отношение на продажбата на поземлен имот според Конституцията на Диоклециан (294 г. сл.Хр.) тя трябва да е и справедлива (iustum) (вж. (laesio enormis*).", "cat": "obl" }, { "term": "Promissor", "gloss": "промитент, този, който обещава", "body": "Промитентът е страната, която обещава престацията (т.е. длъжникът) със стипулация.", "cat": "obl" }, { "term": "Quasi contractus", "gloss": "квазиконтракт", "body": "Неримски термин за определяне на облига- ционни отношения, които се пораждат от пра- номерно действие, но не са договори (obligationes quasi ex contractu*).", "cat": "obl" }, { "term": "Quasi delictum", "gloss": "квазиделикт", "body": "Неримски термин за определяне на облигационни отношения (obligationes quasi ex delicto*), породени от сходно на деликта (delictum*) неправомерно поведение.", "cat": "obl" }, { "term": "Querela non numeratae pecuniae", "gloss": "жалба за неброена сума", "body": "Правно средство за защита на длъжника (debitor*) срещу лицето, което претендира, че е негов кредитор. Псевдо-длъжникът твърди, че исканата сума всъщност никога не му е давана в заем. Той трябва да установи липсата на дълг по договор за заем, съответно и на задължение за изплащането му.", "cat": "obl" }, { "term": "Quod sine die debetur, statim debetur", "gloss": "това, което се дължи без е... се дължи веднага", "body": "Правило за изискуемостта на вземанията.", "cat": "obl" }, { "term": "Rapina", "gloss": "грабеж", "body": "Форма на кражбата (furtum*), съчетана и с насилие върху личността (vis).", "cat": "obl" }, { "term": "Ratihabitio", "gloss": "потвърждение, ратифициране", "body": "Проява на волята на едно лице с цел да се потвърдят сключени от друго лице, но за негова сметка и в негова полза действия и правни сделки, напр. при воденето на чужда работа без поръчка (срв. negotiorum gestio*). По отношение на тях се прилагат правилата по договора за мандат (mandatum*).", "cat": "obl" }, { "term": "Receptum", "gloss": "рецепт, приемане на задължение", "body": "Термин, свързан с различни случаи, общото при което е, че се създава облигационно отношение по преторите (pactum*), в което страната натоварва да изпълни определена работа или приема за пазене чужда вещ и поема отговорност.\n(1) Receptum argentariorum: Съгласие на банкер да поеме съвместно със своя клиент задължение за плащане на дълг.\n(2) Receptum nautarum, cauponum, stabulariorum:\nСпоразумението на превозвачи (argenti), ханджии (caupones) или собственици на конюшни (stabularii) да поемат отговорност пред клиента за запазването на внесените при тях вещи. Тази отговорност е строга и обективна (sine culpa), като тя обхваща и щетите, нанесени от подчинените им.\n(3) Receptum arbitri:\nПриемане от страна на избрано лице (арбитър) да разреши спора между страните (compromissum).", "cat": "obl" }, { "term": "Recuperatores", "gloss": "рекуператори", "body": "Това са съдии, които разглеждат дела, свързани с международни спорове. шение по преторското право, което е неформално (pactum*). По принцип едно лице се натоварва да извърши нещо в чужда полза или приема за пазене чужда вещ при по-висока отговорност. Различават се:\n(1) Receptum arbitrii (рецепт на арбитъра): Съгласие на арбитъра (arbiter*), избран съвместно от страните, да поеме задължението да разреши техния спор.\n(2) Receptum argentarii (рецепт на банкера): Споразумение (съглашение) между банкер (argentarius*) и един от неговите клиенти, по силата на което банкерът поема задължение да изплаща настоящите или бъдещите дългове на своя клиент до определена обща сума.\n(3) Receptum nautarum, cauponum, stabulariorum (рецепт на корабните предприемачи, ханджиите и собствениците на конюшни): Изрично или мълчаливо поемане на задължение от корабния предприемач (exercitor*), ханджията или собственика на конюшня (обор), които получават за съхранение и пазене поверените им от пътниците стоки и животни и се задължават да им ги върнат невредими. По силата на едикта (edictum*) на претора (praetor*) тези лица отговарят за кражба (furtum*) и за увреждания на вещта, дори и да нямат вина за това (вж. custodia*), с изключение на случаите на непреодолима сила (vis maior*).", "cat": "obl" }, { "term": "Redhibitio", "gloss": "редхибиция, реституиране", "body": "Връщането на продаден роб (servus) или животно в случаите, в които курулните едили (aediles curules) позволяват на купувача да иска унищожаване на правните последствия от договора за покупко-продажба (emptio venditio). По време на Юстиниан е допустимо разваляне на договора по искане на купувача за всякаква вещ, но предимно при наличие на скрити недостатъци (vitium).", "cat": "obl" }, { "term": "Relocatio", "gloss": "пренаемане /на аренда/", "body": "Израз за продължаване на договора за наем (locatio conductio) след изтичане на определения срок, при което, ако наемодателят нето възразява, се счита за продължен.", "cat": "obl" }, { "term": "Relocatio tacita", "gloss": "мълчаливо продължаване на арендния договор", "body": "Израз във връзка с продължаване на арендния договор след изтичане на срока (dies). Когато договорът за наем (locatio-conductio rei) е с определен срок, ако наемателят (conductor) продължи да ползва вещта без противопоставянето на наемодателя (locator), договорът се счита за продължен за неопределено време.", "cat": "obl" }, { "term": "Res perit creditori", "gloss": "вещта погива за кредитора", "body": "Израз, използван и в съвременното право за определяне на обстоятелството, че кредиторът носи риска по договора, свързан с погиване на предмета на този договор (periculum*).", "cat": "obl" }, { "term": "Res perit debitori", "gloss": "вещта погива за длъжника", "body": "Израз, използван и в съвременното право за определяне на обстоятелството, че длъжникът носи риска по договора, свързан с погиване на предмета на този договор (periculum*).", "cat": "obl" }, { "term": "Satisdatio", "gloss": "сатисдация", "body": "Задължение, поето от основния длъжник със стипулация, към което се добавя поръчителство (fideiussio*) като гаранция за изпълнение на задължението на основния длъжник", "cat": "obl" }, { "term": "Societas", "gloss": "дружество, договор за дружество", "body": "Двустранен или многостранен консенсуален съвършен договор (срв. obligationes consensu contractae*), с който две или повече лица – съдружници (socius*), обединяват имуществото си изцяло или отчасти с оглед постигане на обща имуществена полза.", "cat": "obl" }, { "term": "Societas ercto non cito", "gloss": "дружество, при което собствеността не е разделена, дружество при непоискана делба", "body": "Фамилна общност (consortium ercto non cito*), възникнала в резултат на смъртта на paterfamilias*, която се създава между синовете и дъщерите му, които наследяват фамилното имущество (patrimonium*). Членовете на тази фамилна общност остават в задруга (при неподелена собственост).", "cat": "obl" }, { "term": "Societas leonina", "gloss": "лъвско дружество", "body": "Нищожен договор за дружество, при който от съдружниците един само губи или съдружниците нямат право на участие в печалбите, а делят само загубите, или един получава всичко, а другите нищо.\nНаименованието идва от баснята за лъва. Societas omnium bonorum\nОсобен вид дружество, при което съдружниците влагат цялото си имущество (настоящо и бъдещо) в общността. Societas unius rei\nПублично или частно дружество, създадено за една определена сделка или вид дейност (напр. търговско дружество), като целта е да се осъществи тази дейност. Societas quaestuaria\nЕдин от видовете дружества, създадени с цел печалба (по дейност).", "cat": "obl" }, { "term": "Societas omnium bonorum", "gloss": "дружество на всички имущества", "body": "Особен вид дружество (societas*), в което съдружниците (socius*) внасят в съсобственост цялото свое имущество (patrimonium*).", "cat": "obl" }, { "term": "Societas publicanorum", "gloss": "дружество на публиканите", "body": "Дружество, което има своеобразна правосубектност и което получава от държавата правото да събира данъци в определена провинция.", "cat": "obl" }, { "term": "Solidum", "gloss": "солидарен, солидарно", "body": "Вж. obligatio in solidum*.", "cat": "obl" }, { "term": "Solutio", "gloss": "изпълнение", "body": "Прекратяване на облигационното отношение чрез изпълнение на дължимото (даване, извършване на действие или бездействие). Изпълнението може да бъде извършено от длъжника или от трето лице (с изключение на случаите, когато е необходима личността на длъжника).", "cat": "obl" }, { "term": "Solutio indebiti", "gloss": "недължимо платено", "body": "То е налице, когато едно лице е извършило плащане, което не дължи. Това лице може да иска връщане на даденото с кондикция – condictio (indebiti) при условие, че е извършило плащането при грешка относно съществуване на дълга.", "cat": "obl" }, { "term": "Solutio per aes et libram", "gloss": "плащане с бронз и везни", "body": "Формален начин на погасяване на създадените с бронз и везни облигационни отношения, при които се използва късче бронз и везни (per aes et libram), и се произнасят соленелни изрази.", "cat": "obl" }, { "term": "Sponsio", "gloss": "спонзия, тържествено обещание за поръчителство чрез стипулация", "body": "Спонзията е вид вербален договор (срв. obligationes verbis contractae*), използван първоначално в легисакционната процедура (legis actiones*). Той се състои в симетрична размяна на въпрос и отговор между бъдещия кредитор (creditor*) и бъдещия длъжник (debitor). Тя е акт по цивилно право (ius civile*), достъпен само за римските граждани (civis Romanus*) за разлика от фидепромисията (fidepromissio*). Чрез нея се създава една от най-старите форми на лично обезпечаване на дълг в римското право – поръчителството. Спонзията предшества и фидеюсията (fideiussio*).", "cat": "obl" }, { "term": "Stipulatio", "gloss": "стипулация, вербално задължене", "body": "Соленелен вербален договор (вж. obligationes verbis contractae), сключен с размяна на въпрос, поставен от кредитора – стипулант и непосредствен и симетричен отговор от длъжника – промитент (promissor). С размяната на въпроса и отговора се поражда задължение за промитента, което той трябва да изпълни в полза на стипуланта.", "cat": "obl" }, { "term": "Stipulatio Aquiliana", "gloss": "аквилиева стипулация", "body": "Форма на новационната стипулация (срв. novatio*), въведена от претора Аквилий Гал в края на Републиката, чрез която множество задължения се обединяват в едно под формата на новаторна стипулация (stipulatio*). По принцип създаването на тази стипулация е последвано от незабавно вербално изявление за погасяване на облигационното отношение (acceptilatio*). Тя позволява да се направи окончателно уреждане на сметките между две лица под формата на разписка за цялото, но като с това се покриват само онези задължения между страните, които те желаят.", "cat": "obl" }, { "term": "Stipulatio duplae", "gloss": "стипулация за двойната стойност", "body": "Първоначално доброволна, а впоследствие задължителна стипулация, с която продавачът (venditor*) на манципна вещ (res mancipi*) или на ценна вещ се задължава към купувача (emptor*) да му даде двойната сума на продажната цена, ако последва евикция (evictio*). Срв. stipulatio rem habere licere*.", "cat": "obl" }, { "term": "Stipulatio poenae", "gloss": "пенална стипулация", "body": "Добавъчна клауза в стипулация, според която промитентът (promissor*) се задължава да плати парична неустойка, ако не изпълни основното задължение или не осъществява действията, за неизпълнението на които се дължи обикновено обезщетение.", "cat": "obl" }, { "term": "Stipulatio praetoria", "gloss": "преторска стипулация", "body": "Наложена от претора (praetor*) стипулация, с която се поражда облигационно отношение (obligatio*) между две страни в определени в преторска едикт (edictum*) хипотези.", "cat": "obl" }, { "term": "Stipulatio rem habere licere", "gloss": "стипулация за позволяване на купувача да задържи вещта", "body": "Стипулация (stipulatio*) която първоначално е доброволна, а след това задължителна, и дори се презумира за сключена. С нея продавачът (venditor*) на неманципна вещ (res nec mancipi*) обещава на купувача (emptor*) да запази необезпокояваното владение на продадената вещ и да го обезщети при евентуална евикция (evictio*). Виж също stipulatio duplae*.", "cat": "obl" }, { "term": "Stipulator", "gloss": "стипулант", "body": "Стипулант е кредиторът, който кара другата страна по стипулацията (stipulatio*). да обещае нещо. Това се извършва чрез поставяне на въпрос, на който промитентът (promissor*) трябва да отговори.", "cat": "obl" }, { "term": "Synallagma", "gloss": "синалагма, реципрочност, взаимност", "body": "В римското право това е съвършен двустранен договор, например – договор за покупко-продажба (emptio venditio) или договор за наем на вещ, на работа или на трудов резултат (locatio conductio).", "cat": "obl" }, { "term": "Syngrapha", "gloss": "синграфа, признаване на дълг", "body": "За разлика от хирографа (chirographum) това е автентичен източник на писмено облигационно отношение (срв. obligationes litteris contractae) с гръцки произход, използван в търговски отношения между римляни и гърци. С нея писмено се признава съществуването на дълг, като документът е съставен по неопределен начин и съдържа констатация, че едно лице дължи на друго лице определена престация, следвано от печатите на определен брой свидетели, които вписват имената си срещу тези печати.", "cat": "obl" }, { "term": "Tacitus consensus", "gloss": "мълчаливо съгласие", "body": "Мълчаливо съгласие при консенсуалните договори (срв. contractus* и obligationes consensu contractae*).", "cat": "obl" }, { "term": "Tempus utile", "gloss": "полезно време", "body": "Интервал от време (intervallum*), през което се отчита невъзможността или затруднението на една от страните да изпълни уговорената престация, ако това се дължи на лични причини (попадане под робство, болест), на официални причини (срв. nefas*), или ако магистратът (magistratus*) не може да бъде открит. Това понякога се противопоставя на tempus continuum – продължено време (срок), който включва периода на невъзможност за изпълнение.", "cat": "obl" }, { "term": "Usurae", "gloss": "лихва", "body": "Периодични плащания върху заетия капитал. Обикновено лихвата е 1/12 от капитала (uncia*).", "cat": "obl" }, { "term": "Usurae centesimae", "gloss": "процентна лихва", "body": "Съответства на месечна лихва от 1% върху дължимата сума, т.е. 12% годишно. Вж. също unciae usurae*.", "cat": "obl" }, { "term": "Venditio bonorum", "gloss": "публична продажба на имуществото", "body": "Виж bonorum venditio*.", "cat": "obl" }, { "term": "Venditor", "gloss": "продавач", "body": "При договор за покупко-продажба (emptio venditio*) това е страната, която прехвърля на купувача (emptor*) необезпокояваното владение на продадената вещ (merx*), с цел прехвърлянето и на правото на собственост върху нея, и която получава като насрещна престация правото на собственост върху цената (pretium*).", "cat": "obl" }, { "term": "Vindex", "gloss": "гарант, поръчител", "body": "В Закона на Дванадесетте таблици, това е лицето, което съдейства като гарант на друго лице било като осигурява явяването му в процес, било при принудително изпълнение върху личността, било за гарантиране на плащането на дължимата сума на кредитора по време на изпълнителното производство върху личността на длъжника.", "cat": "obl" }, { "term": "Vis maior", "gloss": "непреодолима сила", "body": "Външно, извънредно, непредвидимо събитие, на което повечето хора не могат да се противопоставят (земетресение, лавина, наводнение, гражданска война, разбойничество) и по-специално, на които длъжникът не може да се противопостави. От нея се различава случайно събитие (casus fortuitus).", "cat": "obl" }, { "term": "Consortium ercto non cito", "gloss": "общност на наследниците", "body": "Общност на наследниците (heres*), която създава своеобразно дружество (societas*) по наследственото право, в която наследниците са неразделни собственици /съсобственици/ на наследствената маса и упражняват върху нея правото на собственост на общо основание (принцип на неразделност).", "cat": "inherit" }, { "term": "De cuius successione agitur", "gloss": "този, който е основата на наследяването", "body": "Традиционен израз, използван за определяне на починалото лице (наследодател), чието наследство трябва да бъде уреждано.", "cat": "inherit" }, { "term": "Fideicommissum", "gloss": "фидеикомис", "body": "Щедрост по повод на смърт, оказана на определено частно лице и водеща до частно правоприемство. Изпълнението на волята на починалия може да бъде поверено на трето лице, което получава наследството и се задължава да предаде обекта на фидеикомиса на определеното от наследодателя лице. Първоначално използването на фидеикомиси зависи от волята на наследника, натоварен с него, и едва по времето на Август то става задължителен.", "cat": "inherit" }, { "term": "Hereditas", "gloss": "наследство", "body": "От класическия период наследството като цяло се счита за нетелесна вещ и включва от една страна съвкупността от телесни вещи и вземания на наследодателя, а от друга – неговите задължения.", "cat": "inherit" }, { "term": "Hereditas iacens", "gloss": "висящо наследство", "body": "Наследство, което е открито след смъртта на наследодателя, но което все още не е придобито от призованото за наследник трето, външно за фамилията лице.", "cat": "inherit" }, { "term": "Hereditas petitio", "gloss": "иск за наследство", "body": "Цивилен вещен иск (actiones in rem*), който ищецът по силата на своето качество на наследник (heres*) може да насочи срещу длъжник на наследодателя, който също претендира.", "cat": "inherit" }, { "term": "Heres", "gloss": "наследник", "body": "Универсален правоприемник на едно починало лице, който е назначен за такъв по силата на закона или по волята на наследодателя (de cuius*) – по завещание, за да придобие изцяло или отчасти /заедно с другите сънаследници/ имуществото на наследодателя.", "cat": "inherit" }, { "term": "Intestatus", "gloss": "интестат", "body": "Лице, което е починало без да остави завещание.", "cat": "inherit" }, { "term": "Legatarius", "gloss": "легатар", "body": "Бенифициент по легат (legatum*).", "cat": "inherit" }, { "term": "Legatum", "gloss": "легат", "body": "Разпореждане по повод на смърт, с което се създава частно правоприемство. Легатът може да е включен в завещание (testamentum*), а от времето на Империята – в кодицил (притурка), който се потвърждава в завещанието, и с него завещателят оказва щедрост на едно лице, наречено легатар (legatarius*) за сметка на наследника (heres*). Различават се следните типове легати:\n- legatum per damnationem (легат със задължаване, дамнационен легат): Легат, с който завещателят с тържествени слова налага на наследника задължение за изпълнение на специфична престация в полза на легатаря. Изпълнението на задължението от наследника е санкционирано с actio ex testamento.\n- legatum per praeceptionem (легат с прецепция, прецепционен легат): Легат, който може да се направи в полза на един от сънаследниците, който може да придобие за себе си определена вещ преди подялбата на наследството между всички сънаследници. Тази вещ му принадлежи в качеството му на легатар (т.е. по силата на частно правоприемство) и не се приспада от наследствения му дял.\n- legatum per vindicationem (легат с виндикация, виндикационен легат): Легат, с което завещателят предоставя направо на легатаря. правото на собственост върху една вещ, на поземлен сервитут или на право на плодоползване. Нарича се така заради вещния иск за виндикиране (reivindicatio*), които легатарят може да предяви за предоставяне на обекта на легата.", "cat": "inherit" }, { "term": "Mortis causa", "gloss": "по повод на смърт", "body": "Израз, използван във връзка с правните актове по повод на смърт – било като се има предвид смърт на трето лице, или които трябва да породят правно действие след смъртта на техния извършител.", "cat": "inherit" }, { "term": "Nemo pro parte testatus pro parte intestatus decedere potest", "gloss": "не се допуска оставане на наследство отчасти по завещание, отчасти по закон", "body": "Основен принцип на наследственото право, което изисква завещателят да разпредели в завещанието си (testamentum*) цялото си имущество. Единственото изключение е по повод на войнишкото завещание.", "cat": "inherit" }, { "term": "Nuncupatio", "gloss": "нункупация", "body": "Тържествена устна декларация, направена от отчуждителя пред свидетели по време на извършване на манципация (mancipatio*) или от кредитора по време на сключването на нексиум (nexum*), или от завещателя при съставяне на завещание с бронз и везни (per aes et libram*), с цел да се определи естеството на правните последици от извършвания правен акт.", "cat": "inherit" }, { "term": "Querela inofficiosi testamenti", "gloss": "жалба за опорочено завещание", "body": "Жалба, представена пред магистрата (magistratus*) от роднини на завещателя (de cuius*) срещу направено от него обезнаследяване или от друго лице, което е пропуснато в завещанието (testamentum*) и не може да наследи. Жалбата е основана на разбирането, че такова завещание е в противоречие с дължимото отношение на признателност на наследодателя към най-близките на наследодателя.", "cat": "inherit" }, { "term": "Successio ab intestato", "gloss": "наследяване без завещание, т.е. наследяване по закон", "body": "Наследяване на едно лице (de cuius*), което не е съставило (приживе) завещание (testamentum*).", "cat": "inherit" }, { "term": "Testamentum", "gloss": "завещание", "body": "Едностранен писмен соленелен акт, извършен в присъствието на определен брой свидетели, с което paterfamilias* урежда разпределянето на имуществото си след своята смърт (акт по повод на смърт).", "cat": "inherit" }, { "term": "Actio", "gloss": "иск – акция2", "body": "Процесуално средство, чрез което оправомощените да водят съдебен процес защитават искът се схваща преди всичко като право, отколкото в процесуален смисъл. Често само то за иск се асимилира с материалното право. Двете значения често се смесват в класическото римско право.", "cat": "proc" }, { "term": "Actio ad exhibendum", "gloss": "иск за представяне на вещ", "body": "Облигационен иск (actio in personam), който е доставен на този, който има интерес да се яви ревандикационен иск или някакъв ноксален иск (actio noxalis), за да има възможност да поиска ответникът да представи от нейния владение вещта, която е насочен срещу лицето, което претендира, полага, че владее вещта.", "cat": "proc" }, { "term": "Actio commodati", "gloss": "иск от договор за прослужване", "body": "Облигационен иск на заемодателя, с който е предоставен заем за послужване (commodatum) на заемателя. договор за заем за послужване (commodatum), за получаване на парична кондемнация срещу комодатаря, когато той не е върнал заетата вещ; както и за обезщетяване на причинените от комодатаря вреди (actio commodati directa). Той може да предостави на комодатаря срещу комоданта за заплащане на разноски, свързани с ползването или запазването на заетата вещ (actio commodati contraria).", "cat": "proc" }, { "term": "Actio communi dividundo", "gloss": "иск за делба на съсобственост", "body": "Иск, предоставен на всеки от съсобствениците, за прекратяване на съсобствеността и за делба на вещта между тях в съответствие с притежаваните идеални части.", "cat": "proc" }, { "term": "Actio conducti", "gloss": "иск на наемодателя /conductor/", "body": "Облигационен иск (actiones in personam) на наемодателя (locator) срещу наемателя (conductor) за получаване на парична кондемнация при неизпълнение или лошо изпълнение на задължение по договор за наем (locatio conductio) (аренден договор, договор за наем на работа или за наем на трудов резултат).", "cat": "proc" }, { "term": "Actio confessoria", "gloss": "конфесорен иск", "body": "Вещен иск (actiones in rem), сравним по своето действие с ревандикационния иск (reivindicatio), с който ищецът претендира ответникът да бъде осъден да признае наличието на сервитут (servitus) или на плодоползване (ususfructus) върху процесния имот. Вж. и vindicatio servitutis.", "cat": "proc" }, { "term": "Actio de dolo", "gloss": "иск за измама", "body": "Пенален иск, основан върху факти (actiones in factum), създаден през 66 г. пр.Хр. от претора Aquilius Gallus, който се предоставя, при липса на друг иск, на потърпевшия срещу лицето, извършило измамата, и се търси присъждането на обезщетение според размера на причинената вреда.", "cat": "proc" }, { "term": "Actio de modo agri", "gloss": "иск във връзка с размера на поземления имот", "body": "Облигационен иск (actiones in personam), предоставен на купувача на поземлен имот, чието право на собственост е прехвърлено чрез манципация (mancipatio), за връщане от продавача на съответната част от цената, тогава когато размерът на имота не съответства на това, което е уговорено при продажбата (срв. leges mancipii). Този иск предшества /по време/ иска за намаляване на цената при гаранция за скрити недостатъци на продадената вещ (срв. actio quanti minoris).", "cat": "proc" }, { "term": "Actio de peculio et de in rem verso", "gloss": "иск относно пекулия и обогатяването", "body": "Облигационен иск (actiones in personam), принадлежащ към общата категория на адиектните искове (actiones adiecticiae qualitatis). С него едно лице, договарящо с подвластен (alienis iuris), подвластен син (filius) или роб (servus) с пекулий (peculium), може да поиска от техния домовладец (paterfamilias, dominus) овъзмездяване до размера на актива на пекулия или на обогатяването, произтекло от това договаряне.", "cat": "proc" }, { "term": "Actio de tigno iuncto", "gloss": "иск за вградената греда", "body": "Предвиден в Закона на Дванадесетте таблици (Lex XII [duodecim] tabularum*) пенален иск, предоставен на собственика на откраднати материали /използвани от другиго/, при построяването на сграда върху чужда земя (срв. tignum iunctum*). Actio de tigno iuncto е считан от класическите юристи като средство за получаване на цялостно обезщетение, дължимо независимо от добросъвестността (bona fides*) или недобросъвестността на този, който е използвал материалите.", "cat": "proc" }, { "term": "Actio depositi", "gloss": "иск по договор за влог", "body": "Облигационен иск (actiones in personam), предоставен на влогодателя (депонент) срещу влогоприемателя (депозитар) да получи от него парична кондемнация при невръщане на вложената вещ по силата на един договор за влог (depositum*) или да получи обезщетение за причинените от депозитаря вреди (actio depositi directa). Той може да бъде предоставен и на влогоприемателя (депозитар) срещу влогодателя (депонент) за обезщетяване на направените разходи, свързани с депонираната вещ (actio depositi contraria).", "cat": "proc" }, { "term": "Actio empti", "gloss": "иск на купувача", "body": "Облигационен иск (actiones in personam*), предоставен на купувача (emptor*) срещу продавача (venditor*) за получаване на парична кондемнация при неизпълнение или лошо изпълнение на задълженията по договор за покупко-продажба.", "cat": "proc" }, { "term": "Actio ex stipulatu", "gloss": "иск, произтичащ от стипулация", "body": "Облигационен иск (actiones in personam*), предоставен на стипуланта (stipulator*) срещу промитента (promissor*) за получаване на парична кондемнация за неизпълнение или лошо изпълнение на задължение по стипулация (stipulatio*).", "cat": "proc" }, { "term": "Actio fiduciae", "gloss": "иск по договор за фидуция", "body": "Облигационен иск (actiones in personam*), предоставен на фидуцианта срещу фидуциаря за получаване на парична кондемнация при невръщането на вещта – обект на договора за фидуция (actio fiduciae directa); или предоставен на фидуциаря срещу фидуцианта за получаване на обезщетение за направените разходи по изпълнение на договора (actio fiduciae contraria).", "cat": "proc" }, { "term": "Actio furti", "gloss": "иск от кражба", "body": "Пенален иск, предоставен за защита на всяко лице, което има интерес кражбата да не е извършвана (cuius interest rem salvam esse) срещу крадеца и/или неговите съучастници за получаване на парична кондемнация, представляваща неколкократната стойност на открадната вещ в зависимост от вида кражба (furtum*).", "cat": "proc" }, { "term": "Actio institoria", "gloss": "инститорен иск", "body": "Иск, принадлежащ към общата категория на адиектните искове (actiones adiecticiae qualitatis*), и предоставен на едно лице, договаряло с подвластно лице (alienis iuris*), с подвластен син (filius*) или с роб (servus*), а в следкласическото право и с неподвластни лица (sui iuris*), които са назначени да извършват по занятие някаква търговия или за управители на магазини. С този иск, насочен срещу домовладелеца (paterfamilias*, dominus*) по всяко време може да се търси плащане на целия дълг в размера, в който е породен при осъществяване на дейността. не на разрешената от домовладелеца търговска дейност.", "cat": "proc" }, { "term": "Actio iudicati", "gloss": "иск за изпълнение на съдебно решение", "body": "Иск, предоставен по формуларната процедура (вж. actiones per formulas*) срещу ответника, който е осъден и който не е изпълнил доброволно съдебното решение. Второто решение по същия иск осъжда ответника да плати двойно (duplum) това, за което е осъден по първото решение, и има изпълнителен характер.", "cat": "proc" }, { "term": "Actio legis Aquiliae", "gloss": "иск по Аквилиевия закон", "body": "Иск по Аквилиевия закон (lex Aquilia de damno*), предоставен на потърпевшия от деликта (delictum*) в случаите на непозволено увреждане на чужда вещ, с който той може да получи обезщетение, равно на най-високата стойност (plurimi) на увредената или погинала вещ. Този иск се предявява в едногодишен срок от узнаването на деликта или непосредствено в тридесетдневен срок от извършването на деликта.", "cat": "proc" }, { "term": "Actio locati", "gloss": "иск на наемателя", "body": "Облигационен иск (actiones in personam*), предоставен на наемателя (locator*) срещу наемодателя (conductor*) за получаване на парична кондемнация при неизпълнение или лошо изпълнение на задължение по договор за наем на вещ, (locatio-conductio*) (договор за наем на работа или на трудов резултат).", "cat": "proc" }, { "term": "Actio negatoria", "gloss": "негаторен иск", "body": "Вещен иск (actiones in rem*), предоставен в два случая:\n(1) на собственика (dominus*) на една вещ срещу всяко лице, което претендира съществуването на ограничено вещно право върху нея (iura in re aliena*).\n(2) на титуляра на сервитут (servitus*), състоящ се в бездействие, срещу собственика на имота, който трябва да се съобразява със сервитута (servitus*) или да плати парично обезщетение.", "cat": "proc" }, { "term": "Actio negotiorum gestorum", "gloss": "иск за водене на чужда работа без поръчка", "body": "Облигационен иск (actiones in personam*), предоставен на собственика срещу гестора за получаване на парична кондемнация при лошо изпълнение на чужда работа без поръчка (negotiorum gestio*) или за предаване на вещите или ползите, получени в резултат на изпълнението на поръчка (mandatum*) (actio negotiorum gestorum directa). Той може да бъде предоставен и на гестора срещу собственика за заплащане на направените разходи във връзка с предприетата работа (actio negotiorum gestorum contraria).", "cat": "proc" }, { "term": "Actio noxalis", "gloss": "ноксален иск", "body": "Иск, предоставен на увреденото от деликт (delictum*) лице, когато увреждането е извършено срещу настоящия домовладелец (paterfamilias*, dominus*) на подвластен (alienis iuris*), подвластен син (filius*) или роб (servus*), когато тези лица са извършили увреждането. Домовладелецът носи отговорност за деликта било като заплати глобата, или като предостави /букв. Изостави/ подвластния или роба под властта на увреденото лице (вж. също noxae deditio*).", "cat": "proc" }, { "term": "Actio pigneraticia", "gloss": "иск по договор за залог", "body": "Облигационен иск (actiones in personam*), предоставен на залогодателя (по принцип длъжник по основното правоотношение) срещу залогоприемателя (кредитор по основното правоотношение) – пряк иск, за получаване на парична кондемнация при невръщане на заложената вещ след погасяване на вземането, което обезпечава или за възстановяване на вредите, причинени от заложената вещ (pignus*) (actio pigneraticia directa). Той може да бъде предоставен и на залогодателя срещу залогоприемателя за получаване на обезщетение за направените разноски, свързани със заложената вещ (actio pigneraticia contraria).", "cat": "proc" }, { "term": "Actio praescriptis verbis", "gloss": "иск, произтичащ от думите, вписани в началото на формулата на иска", "body": "Облигационен иск (actiones in personam*), предоставен на страната по ненаименован договор (conventiones sine nomine*), която е изпълнила добросъвестно своето задължение, срещу другата страна по договора, за парична кондемнация при неизпълнение или лошо изпълнение на задълженията й по същия ненаименован договор.", "cat": "proc" }, { "term": "Actio pro socio", "gloss": "иск на съдружника", "body": "Облигационен иск (actiones in personam*), предоставен на всеки от съдружниците (socius*) в едно дружество (societas*) срещу другия съдружник или другите съдружници, който води по принцип до прекратяване на дружеството (иск за обща ликвидация) и с който се цели да се получи парично обезщетение, като всички вземания и дългове във връзка с дружеството се разпределят между съдружниците. Кондемнацията на иска е за разликата между това, което съдружниците дължат на ищеца, и техни вземания срещу него.", "cat": "proc" }, { "term": "Actio Publiciana", "gloss": "Публициев иск", "body": "Вещен иск (actiones in rem*), въведен за първи път от претора Publicius (67 пр.Хр.), който се дава на приобретателя на една вещ, който е изгубил владение върху нея преди изтичане на давността (usucapio*). Искът е построен по модела на ревандикационен иск (reivindicatio*) и съдържа фикция за съществуване на владеене по време на давностния срок за узукапиране (anno possedisset).", "cat": "proc" }, { "term": "Actio quanti minoris", "gloss": "иск за намаляване на цената", "body": "Облигационен иск (actiones in personam*), въведен от курулни едили (aediles*), който се предоставя на купувача (emptor*) срещу продавача (venditor*) на една вещ, купена на пазара и която има недостатък, за да се получи намаляване на цената, пропорционално на по-ниската стойност на тази вещ в резултат на недостатъка.", "cat": "proc" }, { "term": "Actio quod iussu", "gloss": "иск във връзка с дадено нареждане", "body": "Облигационен иск (actiones in personam*), който е от категорията на адиектните искове (actiones adiecticiae qualitatis*). Той се предоставя на лицето, договарящо с чужд подвластен (alienis iuris*), подвластенсин (filius*) или роб (servus*), срещу домовладелеца (paterfamilias*, dominus*) за получаване на дължимата по договора сума. В случая задължението се поражда от правен акт, осъществен от подвластния син или роб, при специалното овластяване с дадено нареждане (iussum*) за това от страна на домовладелеца.", "cat": "proc" }, { "term": "Actio quod metus causa", "gloss": "иск във връзка с осъществена заплаха", "body": "Иск, основан на факти (actiones in factum*) и предоставен на едно лице, което е сключило договор поради упражняване върху него на заплаха (metus*). Искът се предявява срещу насрещната страна по договора и цели кондемнация (първоначално в четирикратен размер), а след това до размера на полученото от заплашеното лице в резултат на осъществената заплаха.", "cat": "proc" }, { "term": "Actio rationibus distrahendis", "gloss": "иск във връзка с уреждане на сметки", "body": "Пенален иск, предвиден в Закона на Дванадесетте таблици (Lex XII [duodecim] tabularum*), който се предоставя на пупила (pupillus*) срещу /непълнолетното лице/ настойника му (tutor*), когато последният е разпореждал имуществото под настойничество за уреждане на сметки, свързани с пупила. Искът е за двойна стойност на причинената вреда.", "cat": "proc" }, { "term": "Actio redhibitoria", "gloss": "редхибиторен иск", "body": "Облигационен иск (actiones in personam*), създаден от курулните едили (aediles curules*), и предоставен на купувача на купена вещ с недостатъци (emptor*) срещу нейния продавач (venditor*), с които се иска развалянето на договора и възстановяването на платената цена.", "cat": "proc" }, { "term": "Actio tutelae", "gloss": "иск относно настойничеството", "body": "Облигационен иск (actiones in personam), предоставен на пупила /непълнолетния/ (pupillus), след навършване на пълнолетие (срв.. pubertas) от него, срещу неговия настойник (tutor), който трябва да направи отчет за управлението на имущество и сметките и да му предаде това имущество (actio tutelae directa). Този иск се дава и на настойника срещу пупила за заплащане на направените в негов интерес разходи (actio tutelae contraria).", "cat": "proc" }, { "term": "Actio venditi", "gloss": "иск на продавача", "body": "Облигационен иск (actiones in personam), предоставен на продавача (venditor) срещу купувача (emptor) за парична кондемнация при неизпълнение или лошо изпълнение на задълженията по договора за покупко-продажба.", "cat": "proc" }, { "term": "Actiones adiecticiae qualitatis", "gloss": "адиектни искове /искове с доба въчно качество/", "body": "Наименование, дадено от глосаторите и съвременните романисти на преторските искове (срв. praetor), насочени срещу домовладелеца (paterfamilias) при правни сделки, сключени от негов подвластен (alieni iuris), подвластен син (filius) или роб (servus), с негово съгласие или по негово искане, както и когато е предоставил пекулий (peculium). Към тези искове спадат исковете относно пекулия и обогатяването (actio de peculio et de in rem verso), инститорния иск (actio institoria), екзерциторния иск иск (actio exercitoria) и искът във връзка с дадено нареждане на домовладелеца (actio quod iussu).", "cat": "proc" }, { "term": "Actiones bonae fidei", "gloss": "искове на добросъвестността", "body": "Вид искове, при които съдията (iudex) има широка дискреция да извърши преценка на спорните обстоятелства, тъй като във формулата (formula) му е предписано да отсъди според добросъвестността („ex fide bona“). Съдията дължи сметка и за предявените от ответника възражения (exceptio) и обстоятелства, с които се оспорва добросъвестността на ищеца, дори и във формулата да не са включени специалните възражения за това (възражения за измама, за заплаха, за доба въчен пакт).", "cat": "proc" }, { "term": "Actiones contrariae", "gloss": "обратни искове или искове в противоположен смисъл", "body": "Наименованието е въведено по времето на Юстиниан за исковете, произтичащи от несъвършен двустранен договор като например договор за поръчка (mandatum), за влог (depositum), за заем за послужване (commodatum) или за залог (pignus). С тях основният длъжник по договора може да получи обещатение за направените от него разходи или за претърпяните вреди при изпълнение на договорните му задължения.", "cat": "proc" }, { "term": "Actiones directae", "gloss": "преки искове", "body": "Наименованието е въведено по времето на Юстиниан за исковете, произтичащи от несъвършен двустранен договор като например договор за поръчка (mandatum), за влог (depositum), за заем за послужване (commodatum) или за залог (pignus). С тях основният кредитор може да иска парична кондемнация при неизпълнение или лошо изпълнение на договора от насрещната страна.", "cat": "proc" }, { "term": "Actiones in factum", "gloss": "фактически искове, искове основани на факти", "body": "Хонорни (преторски) искове, които преторът дава във всички случаи, когато няма позоваване на цивилното право, за защита само на значителни случаи според критериите за равнопоставеност и справедливост. Интенцията на формулата, която е премествана от демонстрацията, която представлява кратко изложение на фактите в хипотетична форма. Фактическите искове се противопоставят на исковете, основани върху права (actiones in ius).", "cat": "proc" }, { "term": "Actiones in ius", "gloss": "искове, основани върху права", "body": "Искове, в чиято формула се съдържа интенция с поставен за разрешаване от съдията абстрактен и формализиран въпрос, основан на цивилното право, което се прилага в конкретния случай. Тези искове се противопоставят на исковете, основани на факти (actiones in factum).", "cat": "proc" }, { "term": "Actiones in personam", "gloss": "облигационни искове", "body": "Искове за защита на относително (облигационно) право, с които ищецът иска от ответника изпълнението на облигационното отношение. Името на ответника е включено в интенцията.", "cat": "proc" }, { "term": "Actiones in rem", "gloss": "вещни искове", "body": "Искове за защита на абсолютно (вещно право) върху определена вещ, която е във владение на ответника. Името на ответника не е включено в интенцията, а само в кондемнацията.", "cat": "proc" }, { "term": "Actiones per formulas", "gloss": "искове с формула", "body": "Тези искове са свързани с една от трите исторически развили се форми на гражданското правораздаване, които във времето се формулираната процедура, която във времето се намира между легисакционната процедура и екстраординарната процедура. Тя е въведена от претора, който от III в. пр.Хр. включва в своя едикт формулите на исковете.", "cat": "proc" }, { "term": "Actiones reipersecutoriae", "gloss": "рейперсекуторни искове", "body": "Облигационни или вещни искове, с които се търси равностойността на причиненото увреждане от неизпълнението или лошото изпълнение на едно облигационно отношение, или пък връщането на една вещ, върху която ищецът има право на собственост или ограничено вещно право.", "cat": "proc" }, { "term": "Actiones stricti iuris", "gloss": "искове по стриктното право", "body": "Вид облигационни искове, наречени по този начин по времето на Юстиниан, в които дискреционните правомощия на съдията са ограничени стриктно от формулата за разлика от исковете на добросъвестността.", "cat": "proc" }, { "term": "Actiones utiles", "gloss": ",,полезни“ искове", "body": "Искове, дадени на полезно основание, които са създадени от претора. При тях се адаптира формулата (formula*) на един съществуващ иск към аналогична правна ситуация (напр. rei vindicatio utilis*), най-често чрез разширяване на активната легитимация по иска.", "cat": "proc" }, { "term": "Actions infamantes", "gloss": "инфамиращи искове", "body": "Искове, свързани с основани на доверие и честност (intuitu personae) правни отношения, като например договор за поръчка (actio mandati directa*) или за дружество (actio pro socio*), при които в кондемнацията е включено и прогласяване на ответника за безчестен (infamia*). Това води до изключително неблагоприятни правни и социални последици за ответника, включително ограничаване на неговата гражданска правоспособност.", "cat": "proc" }, { "term": "Adiudicatio", "gloss": "адюдикация /присъждане/", "body": "Адюдикацията е част от формулата на един иск (actio*), която дава право на съдията да присъди правото на собственост (dominium*) или ограниченото вещно право (iura in re aliena*) върху процесната вещ на една от страните (pars*) в процеса.", "cat": "proc" }, { "term": "Advocatus", "gloss": "адвокат, този който е „привикан“ от някого", "body": "Адвокат, чиято основна дейност се изразява в защита на интересите на неговия клиент (в частност асистент в съдебен процес).", "cat": "proc" }, { "term": "Album iudicum", "gloss": "съдебен албум, листа на съдиите", "body": "Листа на съдиите (iudex*), от която преторът (praetor*) по предложение на страните по делото определя съдия за решаването му.", "cat": "proc" }, { "term": "Album praetoris", "gloss": "преторски албум", "body": "Табло, таблица, върху която са написани разпоредбите на едикта (edictum*), съставен от претора (praetor*).", "cat": "proc" }, { "term": "Appellatio", "gloss": "обжалване", "body": "Способ за повторно разглеждане на делото, при което една от страните в процеса може да иска от по-горната инстанция изменение на произнесеното съдебно решение. Обжалването се развива едва при екстраординарната процедура (cognitio extra ordinem). Вж. също supplicatio.", "cat": "proc" }, { "term": "Arbiter", "gloss": "арбитър", "body": "Определено от претора (praetor) частно лице при формуларната процедура (actiones per formulas) за решаване на определени спорове (между съседи; за делба на наследство). Често арбитърът е избиран по свободното и приятелско споразумение между страните за произнасяне на решение (sententia) по техен спор. Тогава преторът не се намесва в процедурата.", "cat": "proc" }, { "term": "Aulus Agerius", "gloss": "от „actor“, лице, което действа, ищец", "body": "Фиктивно име, използвано в образците на формули (formula) на преторски едикт (edictum) за определяне на ищеца чрез омофония от термина „actor“ – този, който води дело или който действа. Във формулата ищецът се означава, като се използва съкращението AA.", "cat": "proc" }, { "term": "Centumviri", "gloss": "центумвири, „съд на стоте мъже“", "body": "Постоянен съд, създаден по време на Републиката и състоящ се от 105 членове във връзка с разделението на гражданите по триби (т.е. по трима на една триба) (tribus*), който има компетентност в различни материи, най-вече за процеси по въпроси за наследство (hereditas*) и собственост (dominium*).", "cat": "proc" }, { "term": "Cognitio extra ordinem", "gloss": "екстраординарен процес", "body": "Третата форма на римската гражданска процедура след легисакционната (legis actiones*) и формуларната (actiones per formulas*) процедури. Екстраординарната процедура от времето на Август насетне представлява извънредна форма на граждански процес, която се прилага от императора и от неговите служители, упражняващи юридиционна компетентност и разглеждащи правни спорове. Тази процедура става обща от III в. сл.Хр.", "cat": "proc" }, { "term": "Cognitor", "gloss": "представител пред правораздаването", "body": "Термин, определящ представител пред правораздавателните органи, който за разлика от прокуратора (procurator*), се овластява въз основа на един тържествен формален акт.", "cat": "proc" }, { "term": "Condemnatio", "gloss": "кондемнация, осъждане", "body": "Част от формулата (formula*) на един иск (actio*), която дава на съдията предписание или да осъди, или да оправдае ответника.", "cat": "proc" }, { "term": "Confessio in iure", "gloss": "признание пред претора", "body": "Признание или одобрение на ответника, направено пред претора (praetor*), с което се приема основателно искането на ищеца. Признанието предрешава уважаването на иска (actio*) на ищеца.", "cat": "proc" }, { "term": "Demonstratio", "gloss": "демонстрация, точно определено предписание", "body": "Клауза на формулата (formula*), на един иск (actio*), в която посочва правното основание на претендираното юридическо отношение. Извън този правно-технически смисъл може да означава и „определяне“. Вж. също сентенцията falsa demonstratio non nocet*.", "cat": "proc" }, { "term": "Denegare actionem ou non dare actionem", "gloss": "отказ за предоставяне на иск", "body": "Акт на претора (praetor*), с който във фазата in iure се отказва да се даде ищеца формула на иска (actio*). Това е случаят, когато на фазата на обща оценка на фактите (in iure) се приема, че искът, който се търси от ищеца, не е правно обоснован.", "cat": "proc" }, { "term": "Denuntiatio", "gloss": "денониация", "body": "В наказателното право това е акт, с който извършеното правонарушение се посочва на магистрата. В гражданското право това е акт, състоящ се в предявяване на спора на трето лице така, че то да се включи в процеса на страната на ответника (срв. litis denuntiatio*).", "cat": "proc" }, { "term": "Do ut des", "gloss": "давам, за да дадеш", "body": "Една от четирите форми на наименованите договори според класификацията на византийските юристи (conventiones sine nomine*). Състои се в предоставяне на правото на собственост върху една вещ, с цел да се получи като Ei incumbit probatio qui dicit: non qui negat (доказването тежи върху този, който иска нещо, а не върху този, който го отрича)\nОсновен процесуален принцип, според който в тежест на ищеца в гражданския процес е да докаже фактите, на които се основава претендираното от него право.", "cat": "proc" }, { "term": "Duplicatio", "gloss": "дуплика", "body": "Отговор на ответника на репликата (replicatio*) на ищеца, която се осъществява чрез възражение (exceptio*), направеното от ответника с цел да парализира иска (actio*) на ищеца. Дупликата се състои в включване на една фраза под условие за доказване във предоставената на спорещите страни формула.", "cat": "proc" }, { "term": "Evocatio", "gloss": "призоваване", "body": "При екстраординарната процедура (cognitio extra ordinem*) това е призоваването на ответника от съдебния магистрат, а в някои случаи и прехвърляне на делото на друга юрисдикция.", "cat": "proc" }, { "term": "Exceptio", "gloss": "replicatio) iusti dominii (възражение (реплика) за действителна собственост", "body": "Възражение или реплика, предоставени на собственика (dominus*), който е ответник по по Публициевия иск (actio Publiciana*), с което той се позовава на своята действителна собственост и се противопоставя на давностното владение (ad usucapionem*) на ищеца.", "cat": "proc" }, { "term": "Exceptio doli", "gloss": "mali) (възражение за измама", "body": "Процесуално средство за защита, което може да се използва от ответника в следните два случая:\n(1) Когато един правен акт е осъществен въз основа на измама (dolus malus*);\n(2) Когато след осъществяване на правния акт и най-нае поведение, несъвместимо с ищеца, той има поведение, несъвместимо с правилата на добросъвестността (bona fides*).", "cat": "proc" }, { "term": "Exceptio legis Laetoriae", "gloss": "възражение по Lex Laetoria", "body": "Предоставено от претора (praetor*) възражение за осигуряване на ефикасната закрила на ненавършилите 25 години лица, срещу вредоносните действия (срв. circumscriptio*) на други правни субекти, които се възползват от тяхната неопитност и ги склоняват да предприемат неизгодни за тях правни действия. Това възражение е предвидено в lex Laetoria de minoribus*.", "cat": "proc" }, { "term": "Exceptio metus", "gloss": "възражение за заплаха", "body": "Възражение срещу ищеца, който склонява със заплаха (metus*) ответника да сключи определена сделка.", "cat": "proc" }, { "term": "Exceptio non adimpleti contractus", "gloss": "възражение за неизпълнен договор", "body": "Израз, използван от XV век насетне, за означаване на възражението на ответника, който е страна по двустранен договор, ако другата страна изисква изпълнението на дължима престация, без самата тя да е осъществила своята престация. С това възражение ответникът може да не изпълнява веднага своето задължение (срв. exceptiones dilatoriae).", "cat": "proc" }, { "term": "Exceptio non numeratae pecuniae", "gloss": "възражение за неплатени/ненаброени пари", "body": "Възражение, което се дава на заемателя по договор за обикновен заем (заем за потребление - mutuum), когато той не е получил от заемодателя обещаната сума пари, но въпреки това заемодателят иска връщането ѝ с condictio certae creditae pecuniae.", "cat": "proc" }, { "term": "Exceptio pacti conventi", "gloss": "възражение за сключен пакт", "body": "Възражение, предоставено от претора на ответника, който е страна по един пакт (pactum), т.е. особено съглашение (conventio), което не поражда самостоятелен иск, а само възражение (nuda pactio obligationem non parit, sed parit exceptionem).", "cat": "proc" }, { "term": "Exceptio rei iudicatae vel in litem deductae", "gloss": "възражение за пресъдено нещо или за воден пред съда спор", "body": "Възражение, което се предявява от ответника, когато предмет на предявения срещу него иск на ищеца вече е бил обект на пресъждане по предходно дело между същите страни или е бил обект на литисконтестация (litiscontestatio).", "cat": "proc" }, { "term": "Exceptio rei venditae et traditae", "gloss": "възражение за продадена и предадена вещ", "body": "Възражение, предоставено на купувача срещу продавача, който е останал собственик, и който ревандикира продадената вече вещ.", "cat": "proc" }, { "term": "Exceptio senatusconsulti Macedoniani", "gloss": "възражение по Senatusconsultum Macedianum", "body": "Възражение, предоставено от претора на едно лице, което е станало неподвластно (sui iuris) за отхвърляне на предявения от кредитора (creditor) иск, с който се търси връщането на заем (mutuum), уговорен по време, когато заемателят е бил все още подвластен (alieni iuris).", "cat": "proc" }, { "term": "Exceptio senatusconsulti Velleiani", "gloss": "възражение по Senatusconsultum Velleianum", "body": "Възражение, предоставено на жената, да се противопостави на предявения от кредитора (creditor) иск срещу нея, в случаите, в които тя е поела чужд дълг (intercessio). Такова задължение на жени е нищожно по силата на Senatusconsultum Velleianum.", "cat": "proc" }, { "term": "Exceptio vitiosae possessionis", "gloss": "възражение за опорочено владение", "body": "Възражение на ответника, с което той може да се противопостави на заповедта на претора (praetor) да възстанови владението на една вещ, която е отнел от друго лице. Ответникът може да претендира, че това лице, което иска за себе си интердиктна защита (interdictum), е отнело от самия ответник владението (possessio) по неправомерен начин – насилствено (vi), тайно (clam) или прекарно (precarium), т.е. че самият ищец е порочен владелец спрямо ответника.", "cat": "proc" }, { "term": "Exceptiones dilatoriae", "gloss": "дилаторни, временни, отлагателни възражения", "body": "Възражения, които могат да се предявят само към определен момент в процеса, и имат за цел да отложат процесуалните действия.", "cat": "proc" }, { "term": "Exceptiones peremptoriae", "gloss": "прекратилни, перемпторни възражения", "body": "Възражения, които могат да се предявят по всяко време на процеса, и които имат за цел да отхвърлят, да препятстват изцяло уважаването на предявения иск. лен договор. Ако страхът е основателен, с релевиране на възражението договорът може да бъде унищожен. действия, извършени от назначения от него капитан на кораба (magister navis).", "cat": "proc" }, { "term": "Falsa demonstratio non nocet", "gloss": "погрешното оповестяване не вреди", "body": "Израз, свързан с римското наследствено право, който означава, че погрешното квалифициране (оповестяване) на един правен акт не води до неговата нищожност и дава възможност след време да се определи действителната воля на страните.", "cat": "proc" }, { "term": "Formula", "gloss": "формула", "body": "Обобщение на съществените елементи на спора в гражданския процес. Формулата съдържа номиниране на съдията и предписания относно разрешаването на спора от него. В нея се включват определяне на действията, които са целта на предприеме. В зависимост от вида на предявения иск от следните елементи: основание на предявения иск (demonstratio*), позоваване на предявения иск (intentio*), присъждането на вещта (adiudicatio*) или осъждането на ответника (condemnatio*).", "cat": "proc" }, { "term": "In integrum restitutio", "gloss": "пълно възстановяване на първоначалното състояние, пълна реституция", "body": "Извънредна мярка, предприемана главно от претора (praetor*) с цел да обезсили правните последици от една сделка или правно-валидно действие, което е действително по цивилното право. Преторът постановява реципрочно възстановяване на разменените от страните престации. Реституцията се прилага в случаите на измама (ob dolum), заплаха (ob metum), договаряне с цел увреждане (ob errorem) или сключване на договор с лице, ненавършило 25 години (ob aetatem).", "cat": "proc" }, { "term": "Indefensus", "gloss": "ответник, който не се защитава", "body": "Призовано на съд лице, което без да признава основателността на претенцията на ищеца, не се защитава и не съдейства на правораздавателния орган за разрешаването на спора.", "cat": "proc" }, { "term": "Index iuxta alligata et probata iudicare debet", "gloss": "съдията трябва да се произнесе по предявените и доказани факти", "body": "Принцип на гражданското правораздаване, с който се забранява на съдията да разглежда въпроси, които не са предявени в процеса. Той може да преценява само предявените и доказаните пред него факти; в противен случай излиза извън пределите на исковата претенция (ultra petita partium).", "cat": "proc" }, { "term": "Indicatum", "gloss": "осъждане", "body": "Съдебно решение (sententia*), произнесено от съдията (iudex*) и по-специално това, което е осъдителен характер (condamnatio*).", "cat": "proc" }, { "term": "Intentio", "gloss": "интенция", "body": "Съществена част на формулата (formula*) на един иск (actio*), в която е посочено правното основание и предмета на исковата претенция. Интенцията се включва във формулата след определянето на съдията или след демонстрацията (demonstratio*), ако тя е включена във формулата (срв. actiones in factum*).", "cat": "proc" }, { "term": "Interdictum", "gloss": "интердикт", "body": "Правно средство за защита, предоставяно от претора (praetor*) чрез обща самостоятелна едноинстанционна процедура, с което той отправя заповед към една от страните, било и към двете стани. Според техния обект се различават три вида интердикти:\n(1) ексхибиторни интердикти (interdicta exhibitoria) преторът издава заповед да се представи или предаде едно лице или една укрита вещ\n(2) реституционни интердикти (interdicta restitutoria, recuperandae possessionis causa): преторът издава заповед да се възстанови владението върху вещта на една от страните в процеса;\n(3) прохибиторни (запазващи) интердикти (interdicta prohibitoria, retinendae possessionis causa), които са най-старите от трите вида. Преторът издава заповед едно лице да се въздържа от извършване", "cat": "proc" }, { "term": "Interdictum clam", "gloss": "интердикт във връзка с тайно завладяване на една вещ", "body": "Реституционен интердикт (interdictum*), с който се заповядва на лицето, отнело тайно владението на една вещ от друго лице, да я върне на предишния и владелец.", "cat": "proc" }, { "term": "Interdictum de precario", "gloss": "интердикт относно precarium*", "body": "Реституционен интердикт (interdictum*), който нарежда на прекариста да върне на концедента вещта, която е получил от него на прекарно основание (precarium*).", "cat": "proc" }, { "term": "Interdictum unde vi", "gloss": "интердикт относно насилието", "body": "Реституционен интердикт (interdictum*), с който преторът нарежда на лицето, изгонило с насилие предходния владелец от недвижим имот, незабавно да му го върне.", "cat": "proc" }, { "term": "Interdictum unde vi armata", "gloss": "интердикт относно въоръженото насилие", "body": "Реституционни интердикт (interdictum*), с който се нарежда на лицето, упражнило въоръжено насилие за отнемане на една вещ, да възстанови владението на предходния владелец.", "cat": "proc" }, { "term": "Interdictum uti possidetis", "gloss": "интердикт uti possidetis", "body": "Прохибиторен интердикт (interdictum*), който забранява всякакви действия за промяна на владението на настоящия владелец на един недвижим имот. Вето е в основата на принципа на колегиалност при римските магистратури. То не може да се упражнява срещу решенията на диктатора (dictator*), поема чужд дълг, без да има правен интерес от това. Вж. също Senatusconsultum Velleianum*.", "cat": "proc" }, { "term": "Interdictum utrubi", "gloss": "интердикт utrubi", "body": "Прохибиторен интердикт (interdictum*), който забранява промяната на владението на владелеца, който е владял по-голяма част от времето в продължение на една година една движима вещ.", "cat": "proc" }, { "term": "Ipso iure", "gloss": "по силата на правото", "body": "Израз, според който правните последици настъпват по силата на правото за разлика от случаите, когато те настъпват само ако се направи съответното възражение (ope exceptionis*), включено в исковата формула.", "cat": "proc" }, { "term": "Iudex", "gloss": "съдия", "body": "Частно лице (index privatus), избрано от страните по определен спор. То се избира със съдействието на магистрата (magistratus*) от три листи с достойни да бъдат номинирани за съдии лица (index selectus). Съдията преценява фактите според предписанията в редакцията на формулата.", "cat": "proc" }, { "term": "Iudicatio", "gloss": "съдене", "body": "Третата и последна фаза на процеса, по време на която избраният от страните съдия (iudex*) разглежда доказателствата и постановява решение (sententia*).", "cat": "proc" }, { "term": "Iudicatus", "gloss": "„присъдено“ лице", "body": "Това е ответникът в осъдителен процес (indicatum*), който, ако не изпълни съдебното решение, може да бъде подложен на принудително изпълнение срещу личността му или срещу имуществото му. Синоним на condemnatus*.", "cat": "proc" }, { "term": "Iudicia bonae fidei", "gloss": "съдебни производства по добра воля", "body": "Съдебни производства, при които съдията има широка свобода при тълкуването на исковете и при преценката на отношенията между страните, като се ръководи от принципа на добросъвестността (bona fides*).", "cat": "proc" }, { "term": "Iudicia stricti iuris", "gloss": "съдебни производства по строго право", "body": "Съдебни производства, при които съдията е обвързан стриктно с текста на формулата, без да има възможност за свободна преценка на мотивите на страните.", "cat": "proc" }, { "term": "Iudicium", "gloss": "формула или инстанция", "body": "Използван във формуларната процедура термин (formula*) като синоним на иск (actio*) (напр. в израза iudicium bonae fidei). В по-тесен правно-технически смисъл се използва за означаване на съдебното производство по разглеждането на даден спор пред съдията. Изменение на основанието или вида на владеенето (possessio*), което произтича напр. от предаване на владението на къса ръка (brevi manu traditio*) или от владелчески конститут (constitutum possessorium*).", "cat": "proc" }, { "term": "Iurisdictio", "gloss": "юрисдикция, правораздаване", "body": "Израз, произтичащ от „jus-dicere“ (казвам правото) и означаващ властта на магистрата (magistratus*) да даде разрешение на един спор. Тази власт се упражнява от всеки магистрат с висша военна и гражданска власт (imperium*).", "cat": "proc" }, { "term": "Lance licioque quaestio", "gloss": "претърсване с блюдо в ръце и препаска на кръста", "body": "Формална процедура за претърсване, установена от Закона на Дванадесетте таблици (Lex XII duodecim tabularum*), с цел да се открие откраднатата вещ. Тя се осъществява от потърпевшия от кражбата в жилището на обвиненото лице. Спазването на тази ритуална и сакрализирана форма от потърпевшия изисквала той да влезе в дома на обвиняемия само с малка препаска на кръста (licium) и с блюдо (lanx) в ръце.", "cat": "proc" }, { "term": "Laudatio auctoris", "gloss": "призоваване от ищеца", "body": "Най-често това се извършва от застрашеното от евикция (evictio*) лице, което обявява спора (litis denuntiatio*) на продавача (venditor*), който му е предал имотната, за да се включи и той като подпомагаща страна в процеса.", "cat": "proc" }, { "term": "Legis actiones", "gloss": "легисакции", "body": "Легисакционната процедура е най-древната в римското право. Тя носи своето име от обстоятелството, че е основана изцяло на Закона на Дванадесетте таблици (Lex XII [duodecim] tabularum*) или на следващи по време закони (lex*). Отличава се със строг формализъм и е достъпна само за римските граждани (срв. ius Quiritium*). вност върху една вещ, на ут или на право на арича се така заради дикиране (reivindicatio*), може да предяви за екта на легата. авени“ закони)\nично от военоначалник истрат (magistratus*) по или от Империята, по мпетентност, с които се ус на победен град или ogatae*. tionis (клаузи за вени от страните по -продажба (emptio комисорния пакт (lex а с уговорка за опит- *), пактът за обратно troemendo) и уговор- говора до определен кони)\nна една конституция н III, трябва да бъде\nна императорския ябва да се придаде ението му за всички вързани с на манципацията очват в нея по иска- Lex Aebutia\nЗакон, чиято дата на приемане е дискусионна (между 149 и 125 г. пр.Хр.), който установява формуларната процедура (actiones per formulas*) и решително съдейства за нейното развитие и прилагане.", "cat": "proc" }, { "term": "Libellus", "gloss": "букв. малка книжка", "body": "Термин, използван за означаване на всякакъв вид жалби, искания или писма, адресирани до императора или до висше длъжностно лице. Част от императорската администрация е определена да разглежда жалбите и исканията a libellis.", "cat": "proc" }, { "term": "Lis", "gloss": "спор, обект на спор", "body": "Оспорване, което води до съдебен процес. В по-архаичния смисъл терминът означава и вещ (res*), за което е предявен ревандикационен иск (вж. reivindicatio*), откъдето идва и израза litis aestimatio*.", "cat": "proc" }, { "term": "Litis aestimatio", "gloss": "оценка на обекта на спора", "body": "Оценка в пари, направена от съдията (iudex*) или арбитъра (arbiter*) на обекта на спора, ако спорът не е за определена сума пари, а за някаква вещ.", "cat": "proc" }, { "term": "Litis contestatio", "gloss": "литисконтестация", "body": "Litis contestatio е съществен акт в римския граждански процес. Тя бележи края на фазата пред претора (in iure). В легисакционната процедура (legis actiones*), при нея се допуска включването като свидетели на лицата, които подпомагат страните по делото. Във формуларната процедура (actiones per formulas*), тя се състои в съгласието на страните по редактираната от претора (praetor*) формула (formula*).", "cat": "proc" }, { "term": "Litis denuntiatio", "gloss": "денунциация на спора", "body": "(1) Процедура, с която ответникът информира лицето, което държи спорната вещ, за претенцията на ищеца с цел това лице да се включи в процес като подпомагаща страна (срв. също denuntiatio*). Така, ако купувачът на една вещ е заплашен от ревандикационен иск (reivindicatio*), предявен от трето лице, той трябва да денонсира спора на продавача (срв. evictio*).\n(2) В екстраординарната процедура (cognitio extra ordinem*), това са встъпителните процесуални действия, с които претенцията се предявява на ответника от императорския служител.", "cat": "proc" }, { "term": "Manus iniectio", "gloss": "буквално: „полагане на ръка“", "body": "Тържествена и формализирана процедура, въведена от Закона на Дванадесетте таблици (Lex XII [duodecim] tabularum*), която се осъществява чрез една от петте типа легисакции (legis actiones*). С нея кредиторът-ищец (creditor*) полага символично ръка върху своя неизправен длъжник (debitor*). Магистратът позволява на ищеца да отведе ответника в частния си затвор, ако той не плати незабавно поисканата устно от кредита сума или ако никой поръчител (vindex*) не гарантира плащането на тази сума.", "cat": "proc" }, { "term": "Nuda pactio actionem non parit, sed parit exceptionem", "gloss": "от гол пакт не се поражда иск, а само възражение, или: голият пакт се санкционира не с иск, а с възражение", "body": "Правило, което обобщава режима на пактовете. По принцип при пакта (pactum*) не се дава самостоятелен иск (actio*), но е възможно той да се защити чрез възражение (exceptio*), противопоставено на ищеца в хода на процеса.", "cat": "proc" }, { "term": "Numerus Negidius", "gloss": "Нумерий Негидий – това е ответникът, който отрича от глагола [negare] задължението си да плати от глагола [numerare]", "body": "Фиктивно наименование на ответника, изпълнено в моделите на формули (formula*) по преторския едикт (edictum*).", "cat": "proc" }, { "term": "Onus probandi", "gloss": "тежест на доказване", "body": "Принцип, според който (ei incumbit probatio qui negat) – тежестта на доказване лежи върху този, който отрича, а не върху този, който отрича (иска?).\nПринцип, който е фундаментално заложен в римския процес, за да не бъде променен гражданският процес в полза на ищците, които биха могли да предявят претенции спрямо всеки, без да бъде този, който основава иска си на доказуеми факти.", "cat": "proc" }, { "term": "Onus probandi incumbit ei qui dicit, non ei qui negat", "gloss": "тежестта на доказване се носи от този, който претендира, а не от този, който отрича", "body": "Принцип на граждански процес, който е създаден в римското право, но е валиден и в съвременния граждански процес. Според него последиците от липсата или недостатъчността на претендираните факти са в тежест на този, който основава своето право на тях.", "cat": "proc" }, { "term": "Ope exceptionis", "gloss": "чрез възражение", "body": "Израз за означаване на обстоятелства или права, които могат да се предявяват в процеса само чрез възражение (exceptio*), включено във формулата (formula*) на иска (actio*), и които не произтичат по силата на правото (ipso iure*).", "cat": "proc" }, { "term": "Ordo iudiciorum privatorum", "gloss": "правила на частноправната процедура", "body": "Съвкупност от норми в гражданския процес, които определят реда и условията, по които се извършват различните процесуални действия, вкл. времето и мястото за тяхното извършване. Легисакционният (legis actiones) и формуларният процес (actiones per formulas) представляват частноправния ред за решаване на спорове за разлика от екстраординарния процес (cognitio extra ordinem), който е друг вид процедура.", "cat": "proc" }, { "term": "Pactio", "gloss": "пакт", "body": "Вж. pactum*.", "cat": "proc" }, { "term": "Periculum", "gloss": "риск", "body": "Намаляване на имущество (patrimonium*) на една страна поради унищожаването на вещи (res*) или нейното увреждане, за което нито собственик (dominus*), нито някоя от страните по договора (contractus*) може да носи отговорност.", "cat": "proc" }, { "term": "Petitio", "gloss": "иск, молба, искане", "body": "Това е самият иск (actio*), който се предявява пред правозащитния орган от този, който се счита за титуляр на едно право, например с цел той да се въведе във владение (missio in possessionem) при hereditatis petitio*. Говори се за реципрочни искове (mutuae petitiones), когато се предявяват два независими иска – по един от всяка от двете насрещни страни в процес, които се разглеждат от един и същ съдия. В екстраординарната процедура extra ordinem*, така се нарича и молбата, адресирана до императора или до императорския чиновник.", "cat": "proc" }, { "term": "Petitum", "gloss": "петитум, искане", "body": "Съдържание на иска (срв. ако се излезе извън искането: Ultra petita partium).", "cat": "proc" }, { "term": "Pluris petitio", "gloss": "излизане извън рамките на искането по иска", "body": "Ситуация, в която се намира ищецът, когато е направил погрешно искане — било като претендира повече от това, на което има право (pluris petitio re), било като претендира преди падежа на вземането (pluris petitio tempore), било като неправилно е определил мястото на предявяване на иска (pluris petitio loco). В класическото римско право процесуалната санкция е в загубата на делото. По време на Империята тази санкция е заменена със специфична глоба", "cat": "proc" }, { "term": "Postulatio", "gloss": "молба, искане", "body": "Адресирана до магистрата (magistratus*) молба, например за назначаване на съдия (postulatio iudicis) или арбитър (postulatio arbitrii) или настойник (postulatio tutoris), или за отстраняване на недобросъвестен настойник (suspecti tutoris). С този термин се означава формален процесуален акт, с който ищецът запознава претора (praetor*) със своето искане, съответно и с формулата на търсения от него иск (actio*).", "cat": "proc" }, { "term": "Praefectus praetorio", "gloss": "преториански префект", "body": "Висш императорски служители, главнокомандващ на преторианската гвардия (която охранява императора) и начело на гражданската (цивилната) имперторска администрация. Големите юристи Папиниан, Паул и Улпиан са заемали този пост.", "cat": "proc" }, { "term": "Praescriptio", "gloss": "прескрипция", "body": "(1) Процесуална клауза в началото на формулата (formula*), с които ищецът може да постигне частичен резултат от предявяване на иска, като избегне погасителния ефект на литисконтестацията (litis contestatio*). Чрез нея не се препятства предявяване на иска в целия му размер по-късно, като не се прилага принципът ne bis in idem.\n(2) В следкласическото римско право това е средство за защита на владелеца (срв. possessio\nпродължително владение срещу невладеещ собственик. Често се използва като възражение на ответника. Praescriptio longi temporis\nпродължително владение. От края на II в. сл. Хр. действа по отношение на (reivindicatio) и защитава вещно право. С течение на това поте (време) добросъвестният владелец може да придобие с придобивна давност провинциални земи. По-късно possessio longi temporis става неоспоримо средство за владение (срв. usucapio).\npraescriptio pro absente,\nfides*). В правото на Теодосий II става общоизходно средство.", "cat": "proc" }, { "term": "Praescriptio longi temporis", "gloss": "прескрипция за продължително владение", "body": "От края на II век сл.Хр. продължителното бездействие погасява вещния иск на собственика (reivindicatio) или на титуляра на ограничено вещно право (vindicatio servitutis), непряко това потвърждава правото на действителния владелец върху вещта. По-късно тя е свързана с придобиване на право на собственост върху провинциален имот, чиито владелец (срв. possessio) може да докаже придобиване на неопорочено владение на годно правно основание (срв. causa), продължителност на това владение 10 г. между присъстващи (inter praesentes) или 20 г. между отсъстващи (inter absentes) и наличие на добросъвестност (bona fides). Срокът е увеличен на 30 г. по време на Теодосий II, а Юстиниан възстановява предходните срокове.", "cat": "proc" }, { "term": "Praescriptio longissimi temporis", "gloss": "прескрипция за най-продължително владение", "body": "По време на Юстиниан тя е свързана с придобиване на право на собственост върху провинциални земи, когато владелецът (срв. possessio), който няма правно основание за придобиване (срв. causa), е добросъвестен (bona fides) и владее без порок повече от 30 г., а при определени условия повече от 40 г.", "cat": "proc" }, { "term": "Praesumptio", "gloss": "презумпция", "body": "(преположение) – извод за владение на неизвестен факт. По-късно се появяват презумпциите, които могат да бъдат оборими (praesumptio iuris tantum) и необорими (praesumptio iuris et de iure). possessio срещу ищец, който след продължително бездействие отправя срещу него вещен иск (actiones in rem). Често се употребява и като синоним на възражение (exceptio), използвано от ответника срещу ищеца.", "cat": "proc" }, { "term": "Praesumptio iuris", "gloss": "правна презумпция", "body": "Правна норма, която позволява от наличието на достатъчно определен факт да се направи извод за друг факт, който към този момент не е налице. Възможно е обаче да се доказва и противното (оборима презумпция).", "cat": "proc" }, { "term": "Praesumptio iuris et de iure", "gloss": "правна фикция", "body": "Касае се за необорима правна презумпция (praesumptio iuris*), т.е. не е възможно доказване на противното.", "cat": "proc" }, { "term": "Praetor", "gloss": "претор", "body": "Магистрат, натоварен предимно с правораздавателни функции. Той се избира за една година и при встъпването си в длъжност прокламира в своя едикт (edictum*) основните принципи, които ще спазва по време на своя мандат. От 242 г. пр.Хр. има два претора, които се различават по своята компетентност:\n(1) praetor urbanus – магистрат, натоварен предимно с правораздаването между римските граждани.\n(2) praetor peregrinus – той е натоварен със спорове между cives Romanus и чужденци и само между чужденци.", "cat": "proc" }, { "term": "Probatio", "gloss": "пробация, начин на доказване", "body": "Предявяване на съществуването на факт или на правен акт през втората фаза на процеса по време на прилагане на формуларната процедура (actiones per formulas), т.е. през заклетия съдия (apud iudicem, iudex).", "cat": "proc" }, { "term": "Probatio diabolica", "gloss": "дяволско доказване", "body": "Израз, създаден от средновековните юристи, за определяне на лежащата върху ищеца по ревандикационния иск тежест да докаже валидността на придобивното основание за правото на собственост върху ревандикираната вещ. При това доказване не може да се получи верига от доказателства до достигането на основание за първично придобиване.", "cat": "proc" }, { "term": "Provocatio ad populum", "gloss": "обжалване пред римския народ", "body": "Право на римския гражданин (civis Romanus), осъден от магистрат (magistratus), с налагане на публично наказание (смъртно наказание, мъчение, значителни глоби), да се обърне с искане за преразглеждане на делото или за помилване към събрания в народното събрание (comitia) римски народ.", "cat": "proc" }, { "term": "Querela", "gloss": "жалба, обжалване", "body": "Процедура, която се развива по правила на екстраординарния процес (cognitio extra ordinem*) и която започва с адресирана до магистрата на ответната страна жалба.", "cat": "proc" }, { "term": "Replicatio", "gloss": "реплика", "body": "Във формуларния процес (actiones per formulas) това е средство за защита на ищеца, който се противопоставя на възражението (exceptio) на ответника. Вж. и replicatio iusti dominii.", "cat": "proc" }, { "term": "Restitutio in integrum", "gloss": "пълно възстановяване на съществуващото положение", "body": "Виж in integrum restitutio*.", "cat": "proc" }, { "term": "Reus", "gloss": "субективно задлъжено лице", "body": "Термин, с който се означава най-често ответникът, но понякога и ищецът или обвиняемият. От тук идва изразът in dubio pro reo (в случай на съмнение трябва да се отсъди или тълкува в полза на обвиненото лице).", "cat": "proc" }, { "term": "Sacramentum", "gloss": "сакраментум, клетва", "body": "Формален акт, свързан с едно от петте типа легисакции, – legis actio per sacramentum. Сакраментумът първоначално е религиозна клетва на всяка от страните, които тържествено потвърждават своето право. Вж. също iusiurandum in litem.", "cat": "proc" }, { "term": "Sententia", "gloss": "мнение, становище, съдебно решение", "body": "Терминът има две значения:\n(1) произнесено от съдията (iudex*) решение на определен спор\n(2) решение или становище (responsa*) на юристи по правен въпрос", "cat": "proc" }, { "term": "Supersessio", "gloss": "", "body": "В контекста на изпълнителния процес. potestas на друго лице за разлика от подвластното alieni iuris. Вж. също paterfamilias.", "cat": "proc" }, { "term": "Supplicatio", "gloss": "супликация, жалба", "body": "В служебния когнитивен процес (cognitio extra ordinem) жалба, която е адресирана направо до императора от едно частно лице, ако едно съдебно решение е отменено от съдията или е необжалваемо. Тогава молителят иска самият император да постанови ново решение или да определи съдия, който да реши отново делото. Вж. също appellatio.", "cat": "proc" }, { "term": "Taxatio", "gloss": "ограничение до определена сума", "body": "Във формуларната процедура (actiones per formulas*), това е включена във формулата клауза, с която кондемнацията (condemnatio*) се ограничава до определена сума.", "cat": "proc" }, { "term": "Transactio", "gloss": "спогодба", "body": "Извънсъдебно споразумение, при което една от страните отстъпва от своето претендирано право, за да се избегне съдебен процес срещу ответника при отстъпка или обещана престация от негова страна.", "cat": "proc" }, { "term": "Vadimonium", "gloss": "задължаване под форма на поръчителство", "body": "Задължаване чрез стипулация (stipulatio*) в полза на ответника в процеса преди явяването му пред съдията. Актът е извънсъдебен, ако има искане ответникът да се яви незабавно пред магистрата (in ius vocatio*).", "cat": "proc" }, { "term": "Verba certa", "gloss": "с точно определени думи", "body": "Соленелна устна формула, която трябва да се произнесе, за да бъде валиден правния акт в архаичния период.", "cat": "proc" }, { "term": "Vim vi fieri veto", "gloss": "забранявам употребата на сила", "body": "Израз на претора praetor*) за подчертаване на забраната за саморазправа във връзка със задължение да се търси интердиктна защита (interdictum*) за отнето владение.", "cat": "proc" }, { "term": "Vindicare", "gloss": "искам, виндикирам", "body": "Извършване на властническо действие, по-специално упражняване на правото да се предяви иск пред съда, предимно при предявяването на ревандикационен иск.", "cat": "proc" }, { "term": "Crimen", "gloss": "престъпление", "body": "Публичен деликт (престъпление), което се наказва по специална процедура пред наказателните съдилища (quaestiones perpetuae).", "cat": "crim" }, { "term": "Desertio", "gloss": "дезертиране", "body": "Действие на войник, който напуска без право римската армия, и който бива подлаган на сериозни санкции в армията, включително осъждане на смърт.", "cat": "crim" }, { "term": "Exilium", "gloss": "заточение", "body": "Ситуация, при която римски гражданин (civis Romanus) е принуден да напусне родината си, което води до промяна в гражданския му статус – status civitatis (status) и ограничава дееспособността му (capitis deminutio). Заточението може да бъде и в резултат на санкция за извършени публичноправни нарушения.", "cat": "crim" }, { "term": "Poena", "gloss": "наказание", "body": "Термин, с който се означава както санкция за престъпление (crimen), така и за деликт (delictum*).", "cat": "crim" }, { "term": "Quaestio", "gloss": "въпрос, разследване", "body": "Терминът има различни значения:\n(1) разследване, издирване и по-специално разглеждане на наказателно дело. В по-широк смисъл по време на Републиката това са постоянни наказателни съдилища (quaestiones perpetuae), пред които се разглеждат дела за престъпления (crimen*).\n(2) въпрос, запитване към юрист, конкретен случай, на който се търси правното разрешение. В по-широк смисъл quaestiones са сборници с правни разрешения на римските юристи (iurisconsulti*) на поставени пред тях въпроси било от учениците им, било по повод на разглеждани от тях случаи.", "cat": "crim" }, { "term": "Talio", "gloss": "талион", "body": "Акт на частно отмъщение, произтичащ от Закона на Дванадесетте таблици (Lex XII [duodecim] tabularum*), при които лицето, потърпевши от деликт (delictum*) налага на виновника идентично телесно увреждане на това, което самото то е понесло („око за око, зъб за зъб“.).", "cat": "crim" }, { "term": "Vim vi repelle", "gloss": "отблъсквай силата със сила", "body": "Израз на претора (praetor) за допускане на самопомощта при защита на владение на отбрана.", "cat": "crim" }, { "term": "Vim vi repellere licet", "gloss": "позволено е да се отговори на насилието с насилие", "body": "Израз на претора, с който се позволява самопомощта за незабавно възстановяване на владение на отнетата вещ (законна отбрана).", "cat": "crim" }, { "term": "Aediles", "gloss": "едили", "body": "Магистрати, които осъществяват едилитурата (aedilitas*) и чиито функции се разпределят между:\n- aediles curules (курулни едили): магистрати на римския народ, натоварени с организиране на игри, и с полицейски функции за стопанисване и управление на обществените пътища и пазари;\n- les aediles plebis (плебейски едилии): магистрати, избрани от плебса, които да помагат на плебейските трибуни (tribunus plebis*) при защита на интересите на плебса (plebs*). Те имат и финансови функции.", "cat": "source" }, { "term": "Aedilitas", "gloss": "едилитура", "body": "Редовна магистратура (magistratus*), чийто основни членове са едили (aediles*) и която представлява основен, но не и необходим етап от cursus honorum*. Тя се състои от две „под- магистратури», тази на курулните едили и на плебейските едили.", "cat": "source" }, { "term": "Aequitas", "gloss": "равнопоставеност, равенство", "body": "Централно понятие в основата на римскотоправната система. Според него правната норма се тълкува не само според стриктния смисъл на текста, но и като се държи сметка за целта и полезността ѝ.", "cat": "source" }, { "term": "Antecessor", "gloss": "учител, професор", "body": "Преподавател по право, предимно в правните школи в Бейрут и Константинопол /по време на Домината/. Най-известни са Доротей и Теофил. Вж. също Institutiones Iustiniani*.", "cat": "source" }, { "term": "Argentarius", "gloss": "банкер", "body": "Лице, което извършва различни операции със стоки и пари, обмяна на валута, приема влогове или дава кредити.", "cat": "source" }, { "term": "Authenticum", "gloss": "Автентика", "body": "Наименование, дадено на глосаторите на един от латинските екземпляри на новелите на Юстиниан (Novellae Iustiniani), датиран към 556 г., с който към конституциите, включени в Кодекса на Юстиниан (Codex Iustinianus) се добавят и императорските конституции, с които те се изменят.", "cat": "source" }, { "term": "Basilicae", "gloss": "Василики", "body": "Компилация, публикувана от император Лъв през 900 г. сл.Хр., която включва юстинианово право – с текст на гръцки език: извадки от Институциите (Institutiones Iustiniani*), от Кодекса (Codex Iustinianus*), от Дигестите (Digesta*) и от Новелите (Novellae Iustiniani*). Вж. също Scholiae*.", "cat": "source" }, { "term": "Beneficium excussionis", "gloss": "право на противопоставяне", "body": "Съвременен израз за определяне на следните практики:\n- beneficium excussionis personalis: право, предоставено по времето на Юстиниан на поръчителя, с което се цели да се принуди кредиторът да поиска („да дискутира“) дълга първо от основния длъжник, а след това от него, като съответно може и само частично да удовлетвори кредитора, ако основният длъжник не плати изцяло;\n- beneficium excussionis realis: привилегия, предоставена по времето на Северите и Каракала, с цел да се принуди кредитора, който има едновременно обща и специална ипотека върху определени имущества, да насочи приоритетно изпълнение върху имуществото със специалната ипотека, ако то е достатъчно да удовлетвори изцяло неговото вземане.", "cat": "source" }, { "term": "Censores", "gloss": "цензори", "body": "Магистратура, създадена през 443 г. пр.Хр. Двамата цензори са избирани за пет години от центуриантните комисии (comitia centuriata*) и осъществяват функции в продължение на осемнадесет месеца. Те трябва да направят оценка на имуществото на всички жители на държавата, да ги впишат в регистрите по триби и да ги разпределят по класи и по центурии. Цензорите създават също списък на сенаторите и на конниците и листа за приходите и разходите в държавата.", "cat": "source" }, { "term": "Codex", "gloss": "кодекс", "body": "Нов начин на представяне на текстовете, който се появява в римския свят през III в. сл.Хр. Кодексът е съставен от множество листове от папирус или пък от дървени таблички, които са събрани заедно по начина, по който се съставят съвременните книги.", "cat": "source" }, { "term": "Codex accepti et expensi", "gloss": "книга за приходите и разходите, сметководна книга", "body": "Това е касовата книга, в която домовладелецът (paterfamilias) вписва своите дългове и кредити. Кодексът се използва също така за създаване на формални задължения чрез вписване (срв. obligationes litteris contractae).", "cat": "source" }, { "term": "Codex Gregorianus", "gloss": "Грегорианов кодекс", "body": "Кодекс с частен характер, който е създаден на Изток между 291–292 г. сл.Хр., най-вероятно от някой си Gregorianus /или Gregorius/. Той представлява компилация на императорските конституции, издадени между времето на император Хадриан и това на император Диоклециан.", "cat": "source" }, { "term": "Codex Hermogenianus", "gloss": "Хермогенианов кодекс", "body": "Частен кодекс, представляващ компилация на различни императорски конституции, отчасти възпроизведени и в Грегориановия кодекс (Codex Gregorianus), а също и някои конституции, издадени от император Диоклециан между 294 и 295 г. сл.Хр. Този кодекс вероятно е съставен в епохата на Диоклециан от някой си Hermogenianus.", "cat": "source" }, { "term": "Codex Iustinianus", "gloss": "Юстинианов кодекс", "body": "Официален кодекс, който представлява една широка компилация на императорски конституции, подредени по теми, след това подредени и хронологично, като най-старите се отнасят до времето на император Хадриан (117–138 г. сл.Хр.), а най-новите са от епохата на самия император Юстиниан (527–565 г. сл.Хр.). Първата редакция на кодекса е одобрена от Юстиниан на 7 юли и влиза в сила на 16 април 529 г. (срв. Corpus iuris civilis). Тази версия на кодекса не е достигнала до наши дни.", "cat": "source" }, { "term": "Codex repetitae praelectionis", "gloss": "кодекс в повторна редакция", "body": "Второто издание на Юстиниановия кодекс (Codex Iustinianus), което включва към вече действащото първо издание императорските конституции, издадени от самия Юстиниан между 529 и 534 г. Кодексът е одобрен на 16 ноември и влиза в сила на 29 декември 534 г. (срв. Corpus iuris civilis). Това издание всъщност е наречено Codex (Iustinianus) и е единственото, което е достигнало до наши дни.", "cat": "source" }, { "term": "Codex Theodosianus", "gloss": "Теодосиев кодекс", "body": "Официален кодекс, представляващ една широка компилация на императорски конституции, издадени между 312 и 437 г. сл.Хр. Кодификацията е предприета от Теодосий II, император на Източната част на Римската империя, и одобрена на 15 февруари 438 г., за да влезе в сила за цялата империя (т.е. и за двете части) на 1 януари 439 г. Текстът му е запазен до наши дни.", "cat": "source" }, { "term": "Comitia", "gloss": "комиции, народни събрания", "body": "Народни събрания, представляващи съвкупността на всички римски граждани. По време на Римската република са познати три различни вида на народни събрания:\n- comitia centuriata (центуриатни комиции): това са народни събрания, в които основната единица за гласуване е центурията (centuria*); те имат за компетентност да гласуват законите по предложение на магистрат, да избират консулите (consules*), преторите (praetor*) и цензорите (censores*). Тези народни събрания имат също значителни компетенции по отношение на наказателното правораздаване;\n- comitia curiata (куриатни комиции): тези народни събрания са най-древните и са съставени изключително от патриции (patricii*), групирани в тридесет курии, като основна единица за гласуване е курията (curia*); те имат компетенция по времето на царския период да избират рекса, като изборът му след това се потвърждава и от сената (senatus*), а по времето на Републиката да гласуват закона, с който се предоставя най-висшата военна и гражданска власт (lex curiata de imperio*), да предоставят тази власт (imperium*) на един магистрат, както и да одобряват практикуваното по това време осиновяване на неподвластно лице (adrogatio*), и съставянето на публично завещание;\n- comitia tributa (трибутни комиции): това са народни събрания, в които гражданите са разделени по триби (tribus*); те имат компетенция да гласуват законите по предложение на магистрати, да избират квесторите (quaestores*), курулните едили (aediles curules*) и други по-низши магистрати; те имат също така компетентност в областта на наказателното правораздаване. През 287 г. пр.Хр. тези комиции се сливат с плебейското народно събрание (concilia plebis*).", "cat": "source" }, { "term": "Comitium", "gloss": "комициум", "body": "Място, което се намира извън стените на града Рим и където задължително се свикват куриатните комиции (comitia curiata*) и трибутните комиции (comitia tributa*).", "cat": "source" }, { "term": "Concilia plebis", "gloss": "плебейско народно събрание", "body": "Народно събрание, съставено изключително от плебеи (срв. plebs*), групирано по триби (tribus*), свиквано и председателствано от плебейските трибуни (tribunus plebis*); това народно събрание има за компетентност да избира трибуните и плебейските едили. То взема решения (срв. plebiscitum*), които се изпълняват първоначално само по отношение на плебеите. Плебисцитите стават задължителни и по отношение на целия римски народ, включително и патрициите, от влизането в сила на закона на Хортензий (lex Hortensia de plebiscitis*), гласуван към 287 г. пр.Хр.", "cat": "source" }, { "term": "Consiliarii principis", "gloss": "императорски съветници", "body": "Императорските съветници, избирани измежду юристите от конническото съсловие (ordo equester*), които от началото на II в. сл.Хр. са натоварени с разглеждането на делата, които са подсъдни на императорския съд (срв. cognitio extra ordinem*).", "cat": "source" }, { "term": "Consilium principis", "gloss": "съвет на принцепса или на Императора", "body": "Императорски съвет, чийто състав е определен от императора, за до консултира по важни въпроси относно управлението на империята, а също и по правни въпроси.", "cat": "source" }, { "term": "Constitutio Antoniniana", "gloss": "Конституция на император Каракала", "body": "Едикт на император Каракала (211-217 г. сл.Хр.), издаден през 212 г., с която се предоставя римско гражданство на всички поданици в Римската империя с изключение на дедитициите (dediticii*).", "cat": "source" }, { "term": "Constitutiones principis", "gloss": "императорски конституции", "body": "Актове, издадени от императора, които придобиват силата на закон от края на II в. сл.Хр. Според тяхното съдържание се различават:\n- decreta (декрети): съдебни решения на императора (и по-скоро създадени от неговия съвет [consilium principis*]), по повод на процеси, заведени пред него като първа инстанция или като апелативна инстанция (appellatio*);\n- edicta (едикти): предписания с общ характер, взети по инициатива на самия император и прилагани за цялата империя, или по отношение на определена категория лица, или за определена територия;\n- mandata (мандати): инструкции с административен характер, които са адресирани от императора до неговите служители и по-специално до управителите на провинции за осигуряване на тяхното добро управление, за санкциониране на злоупотреби или за създаване на привилегии на войници;\n- rescripta (рескрипти): писмени отговори, давани от императора или от неговия съвет (consilium principis*) на поставени въпроси от частни лица, от държавни служители или от магистрати, най-често по повод на някакъв спор. Императорът отговаря на частното лице на базата на негова молба (subscriptio), а на магистратите или служителите той изпраща едно писмо, наречено (epistula).", "cat": "source" }, { "term": "Consuetudo", "gloss": "обичай", "body": "Източник на римското частно право. Признаването на валидността и задължителната сила на определен обичай е основано върху съществуване на две предпоставки за продължителност на прилагането: времетраене на определено ползване или на специфично поведение (longa consuetudo) и придаване на задължителна сила от страна на мнозинството на тази практика (opinio necessitatis).", "cat": "source" }, { "term": "Consules", "gloss": "консули", "body": "Название на двама магистрати по времето на Републиката (magistratus*), избрани за една година, които упражняват най-висшите функции в Римската държава, разполагайки с пълнотата на административната съдебна и военна власт, но със създаването на новите магистрати компетентността им постепенно е ограничена. Последно най-висше стъпало в йерархическата стълбица на магистратите (cursus honorum).", "cat": "source" }, { "term": "Corpus iuris civilis", "gloss": "Гражданска кодификация", "body": "Име, дадено от XVI в. насетне, на всички части на законодателството на император Юстиниан. Тя включва:\n- Codex Iustinianus или codex legum (529 сл.Хр.): сборник от императорски конституции, от които най-старите са от времето на Хадриан, а най-новите са от времето на Юстиниан. Самият кодекс не е достигнал до нас;\n- Codex Iustinianus repetitae praelectionis (534 г. сл.Хр.): второто издание на Codex Iustinianus;\n- Digesta Iustiniani или Pandectae (533 г. сл.Хр.): широка компилация от фрагменти на класическите юристи, която понякога се нарича и codex iuris;\n- Institutiones Iustiniani (533 г. сл.Хр.): учебник с основни понятия и институти, който е предназначен за въведение в изучаването на правото. Те са силно повлияни от Институциите на Гай (Institutiones Gai);\n- Novelles ou Novellae Iustiniani (565 сл.Хр.): императорските конституции, издадени от самия император Юстиниан след одобряването на кодекса до неговата смърт (от 535 г. до 565 г. сл.Хр.).", "cat": "source" }, { "term": "Curia", "gloss": "курия", "body": "Административна избирателна и религиозна единица. В архаичната епоха римското население е било разпределено на три триби (срв. tribus* и comitia tributa*), а самите те са били разделени на десет курии във всяка от тях.", "cat": "source" }, { "term": "Cursus honorum", "gloss": "почетна кариера", "body": "Ред, по който магистратите заемат съответната длъжност. По времето на Републиката редът във възходящ план е бил следният: квестура (quaestores*), курулна едилитура (aediles curules*), претура (praetor*) и консулат (consules*).", "cat": "source" }, { "term": "Da mihi facta, dabo tibi ius", "gloss": "предостави ми фактите, а аз ще ти посоча правото", "body": "Тази сентенция е с канонически произход и означава, че съдията трябва служебно да установи ново абстрактното правило, да се приложи по отношение на право, което трябва да се приложи в процеса на доказване на фактите. След това той трябва да определи правните последици, които са във връзка с релевантната претенция на ищеца. Страните от своя страна носят тежестта на доказване за твърдените от тях факти по делото.", "cat": "source" }, { "term": "Decemviri", "gloss": "децемвири", "body": "Колегия от десет магистрати или десетчленната комисия, която съставя Закона на Дванадесетте таблици (Lex XII [duodecim] tabularum*).", "cat": "source" }, { "term": "Digesta", "gloss": "Дигести", "body": "Термин, използван в две различни значения:\n- Пълен коментар върху системата на цивилното право (ius civile*) и на преторското право (ius honorarium*).\n- Сборник, одобрен от Юстиниан на 16 декември 533 г. и влязъл в сила на 30 декември същата година. Той е съставен от времето, докато се определи изходът от съдебния спор.", "cat": "source" }, { "term": "Dominatus", "gloss": "Доминат", "body": "Период от политическата римска история, който се простира от 284 г. сл.Хр. (управлението на императорите Диоклециан и Максимиан) до 565 г. сл.Хр. – смъртта на император Юстиниан.", "cat": "source" }, { "term": "Dura lex, sed lex", "gloss": "законът е строг, но е закон", "body": "Сентенция, означаваща, че дори когато разрешението, произтичащо от закона, изглежда неравноправно или несправедливо, трябва да се съблюдава закона, защото той е закон.", "cat": "source" }, { "term": "Edictum", "gloss": "едикт", "body": "Публично устно или писмено волеизявление (от edicere = казвам на висок глас) на магистрат (magistratus*). Най-значителен за развитието на частното право е преторският едикт (praetor*), с който се урежда правораздаването в частното право. Той представлява своеобразна харта за правораздаването, в която преторът включва списък на формулите (formula*), които могат да се искат от него по време на неговия мандат и условията, при които той може да предостави или да откаже предоставянето на такава формула.", "cat": "source" }, { "term": "Edictum annuum", "gloss": "годишен едикт, /ежегоден едикт/", "body": "Формулировка на преторския едикт (edictum*), която е валидна само за годината на мандата на претора и се публикува в момента на встъпването му в длъжност. Този едикт се нарича също lex annua. Магистратът, който встъпва в длъжност за следващия мандат, по принцип възприема и включва в своя едикт значителна част от едикта на своя предшественик.", "cat": "source" }, { "term": "Edictum perpetuum", "gloss": "вечен едикт", "body": "Това е преторският едикт (edictum*), в неговата окончателна и неизменна форма в редакцията на юриста Юлиан по поръчка на император Хадриан (131 г. сл.Хр.).", "cat": "source" }, { "term": "Edictum repentinum", "gloss": "извънреден едикт", "body": "Той се издава от магистрата по време на неговия мандат за уреждане на въпроси, които не са включени в едикта, публикуван при встъпването му в длъжност (edictum annuum*).", "cat": "source" }, { "term": "Edictum Theodorici", "gloss": "Едикт на Теодорикс", "body": "Едикт от 512 г. сл.Хр., издаден от краля на остготите Теодорик (474-526 г. сл.Хр.) и съдържащ норми, които се прилагат както за завареното римско население, така и за остготите.", "cat": "source" }, { "term": "Epistula", "gloss": "писмо, вид императорска конституция", "body": "В най-общ смисъл терминът означава писмо, но също и рескрипт на императора, адресиран до магистрат или държавен служител (вж. constitutiones principis*).", "cat": "source" }, { "term": "Epitome", "gloss": "извадка, съкратен вариант", "body": "Литературен стил през IV-V век сл.Хр. за редактиране на съкратена версия на едно известно произведение. Например може да се цитира Epitome Gai, който представлява съкратена версия на институциите на Гай (вж. Institutiones Gai*).", "cat": "source" }, { "term": "Glossa", "gloss": "глоса", "body": "Термин с гръцки произход, с който се означава включването на думи и изрази след текста или в полето на ръкописа с цел да се тълкува вия.", "cat": "source" }, { "term": "Honores", "gloss": "почит, почести", "body": "Израз, с който се означават задълженията на магистрата (срв. magistratus*), изпълнявани от името на римския народ, които не са възмездени, и които той осъществява според предвидения предварително определен ред (срв. cursus honorum*). Веднъж избран, магистратът изпълнява своите функции само в продължение на една година.", "cat": "source" }, { "term": "Imperator", "gloss": "император", "body": "По време на Републиката тази титла се дава на военачалника-победител във водена от римляните война, който е удостоен с триумф. По време на Империята същата титла се използва от титуляра на върховната военна и цивилна власт в държавата. Терминът е еднозначен с princeps по времето на Принципата (Principatus) и с dominus по времето на Домината.", "cat": "source" }, { "term": "Imperium", "gloss": "висша военна власт", "body": "Висша военна власт, която се упражнява от висшите магистрати (консули и претори), избирани от римския народ, а от епохата на Октавиан Август – от самия император (imperator, princeps).", "cat": "source" }, { "term": "In ius", "gloss": "основано на право", "body": "Израз за определяне на особен вид искове, в които претенцията е основана на права, уредени от цивилното право. Вж. actiones in ius*.", "cat": "source" }, { "term": "In ius vocatio", "gloss": "призоваване пред съдебния магистрат", "body": "Тържествена процедура на призоваване на съд, при която ищецът, срещайки ответника на публично място, го отвежда пред магистрата (срв. magistratus* и praetor*) и произнася определени изрази, с които заявява своята претенция към него.", "cat": "source" }, { "term": "Institutiones Gai", "gloss": "Институциите на Гай", "body": "Елементарен теоретичен учебник в 4 книги, съставен от юриста Гай през 160 г. сл.Хр. Наред с него той е написал и едно практическо ръководство, наречено res cottidianae (Юриспруденция на ежедневието). Институциите съществуват и в съкратен вариант в епохата на Домината. (срв. Epitome Gai*).", "cat": "source" }, { "term": "Institutiones Iustiniani", "gloss": "Институциите на Юстиниан", "body": "Елементарен учебник в 4 книги, предназначен за студентите по право, създаден по заповед на император Юстиниан през 533 г. от професорите Доротей и Теофил (antecessores), който е в голямата си част изграден върху Институциите на Гай (Institutiones Gai*). Институциите са част от Юстиниановата кодификация (Corpus iuris civilis*). на определени действия. („...vim fieri veto“), и по-специално да изменя владението на една вещ в своя полза.", "cat": "source" }, { "term": "Interpolatio", "gloss": "интерполация", "body": "Изменение на оригиналния текст от съчиненията на класически юрист, предприето от комисията, натоварена със съставянето на Дигестите и Юстиниановия кодекс (срв. Corpus iuris civilis*), с цел адаптирането му към действащото по времето на император Юстиниан право. Интерполацията се състои или в изменение на използваните термини, в допълване на изреченията или в отстраняване на класическите противоречия, които имат еднозначно разрешение в следващия период.", "cat": "source" }, { "term": "Interpretatio", "gloss": "тълкуване", "body": "Интелектуална дейност, която има за цел да определи смисъла и значението на едно или повече волеизявления или на една правна норма.", "cat": "source" }, { "term": "Interrex", "gloss": "интеррекс", "body": "В царския период това е сенаторът, който упражнява временно властта след смъртта на рекса (rex*) до избирането на неговия приемник. По времето на Републиката това е емик. По времето на Републиката сенатор, който избран от Сената (senatus*) или при незаета кон-сулска длъжност (consules*) или при пречка, след мата консули определя свой приемник и процедурата се повтаря на всеки 5 дни до избирането на новите консули.", "cat": "source" }, { "term": "Iura novit curia", "gloss": "съдът познава правото", "body": "Израз, според който съдът служебно трябва да познава и прилага правото.", "cat": "source" }, { "term": "Iurisconsulti", "gloss": "юристи", "body": "Римските юристи, които въз основа на своите правни познания дават правни консултации на страните по делото (responsa*), съветват страните при сключване на правна сделка или изразяват становища по искане на магистрат при изпълнение на неговите функции.", "cat": "source" }, { "term": "Iurisprudentia", "gloss": "юриспруденция", "body": "Според юриста Улпиан тя се определя като „познаване на човешките и божествените дела (закони) и се състои в изследването на конкретни случаи от юристите iurisconsulti*), които се преценяват и разрешават от правна гледна точка.", "cat": "source" }, { "term": "Ius", "gloss": "право", "body": "Според определението на Целз, правото е изкуство за доброто и справедливото (D. 1,1,1 pr: Ius est ars boni et aequi“).", "cat": "source" }, { "term": "Ius abutendi", "gloss": "право на разпореждане, вкл. и унищожаване, букв. „право на злоупотреба“", "body": "Признато на собственика (dominus*) на една вещ правомощие да се разпорежда с нея свободно било с атериални действия, било като я отчуждава или унищожава.", "cat": "source" }, { "term": "Ius adcrescendi", "gloss": "право на увеличаване на дела", "body": "В случаите на отказ или изоставане (derelictio*) на своята част от един или няколко съсобственици тези, които запазват съсобствеността, получават пропорционално увеличение на своите дялове според първоначалното им разпределение. Същият принцип се прилага и за сънаследниците, ако един или няколко от тях направят отказ от наследство.", "cat": "source" }, { "term": "Ius civile", "gloss": "цивилно и право на римските граждани", "body": "Цивилно право е правото, установявано от всеки народ според колективната воля. В Рим цивилното право се прилага само за римските граждани (ius Quiritium*).", "cat": "source" }, { "term": "Ius civitatis", "gloss": "право на града или на гражданската община", "body": "Съвкупност от права, които се притежават само от гражданите на определен град или гражданска община", "cat": "source" }, { "term": "Ius distrahendi", "gloss": "право на разпродаване", "body": "Право на кредитора да продаде или да отчужди по друг начин вещта, предоставена в залог (pignus*) или ипотека (hypotheca*) при липса на падеж на погасяване на дълга, който е обезпечен с тях.", "cat": "source" }, { "term": "Ius edicendi", "gloss": "право на издаване на едикт", "body": "Право на висшите магистрати (срв. magistratus*), избирани от римския народ, да обявяват публично разпоредби с административен или правораздавателен характер, които ще прилагат в изпълнение на тяхната длъжност и по време на упражняване на техните функции.", "cat": "source" }, { "term": "Ius eligendi", "gloss": "право на избор", "body": "(1) право, предоставено от император Теодосий II на преживелия съпруг, който може да избере едно от родените от брака деца като бенефициент на останалото от починалата съпруга застрално имущество (dos*).\n(2) Право на длъжника (debitor*) да избере коя престация да изпълни при алтернативните задължения (obligatio alternativa*).", "cat": "source" }, { "term": "Ius est ars boni et aequi", "gloss": "Правото е изкуство за доброто и справедливото", "body": "Определение за правото (ius*), дадено от юриста Целз, цитиран от Улпиан D.1,1,1pr.", "cat": "source" }, { "term": "Ius ex scripto", "gloss": "писано право", "body": "Voir ius scriptum", "cat": "source" }, { "term": "Ius excludendi omnes alios", "gloss": "право, което изключва всички други", "body": "Израз с некласически произход, с който се означава една от най-характерните черти на правото на собственост (dominium*) – неговият абсолютен характер (erga omnes*).", "cat": "source" }, { "term": "Ius exilii", "gloss": "право на заточение", "body": "Право на римския гражданин (civis Romanus*), който е осъден от центуриатните комиции (comitia centuriata*) за престъпление, наказуемо със смърт, да избере доброволно заточение (exilium*) извън границите на римската държава, за да избегне смъртното наказание.", "cat": "source" }, { "term": "Ius exponendi", "gloss": "право на изоставяне", "body": "Признато на домовладелеца (paterfamilias*) право да изостави новородено дете, което би следвало да се включи във фамилията с факта на раждането му.", "cat": "source" }, { "term": "Ius fruendi", "gloss": "право на плодоприбиране", "body": "Едно от правомощията на титуляря на вещни права и по-специално на титулярите на правото на собственост (dominium ex iure Quiritium*) и на правото на ползване (ususfructus*), което се състои в правото да се събират естествените или граждански плодове от една плодоносна вещ (вж. fructus*).", "cat": "source" }, { "term": "Ius gentium", "gloss": "право на народите", "body": "Правна система, възникнала през III в. пр. Хр. като отговор на нуждите на засиления търговски обмен между римските граждани и чужденците (peregrini*). Характеризира се с по-голяма гъвкавост, неформалност и акцент върху „добрата воля“ (bona fides*).", "cat": "source" }, { "term": "Ius honorarium", "gloss": "хонорарно /преторско/ право", "body": "Съвкупност от разпоредби, установени от претора (praetor*) в неговия едикт (edictum*) с оглед да се подпомогне прилагането, да се допълни или да се коригира цивилното право (ius civile*) с цел то да се пригоди към изискванията, породени от развитието на икономическия и социален живот. Нарича се хонорарно поради почетната длъжност на претора; вж. също ius praetorium*.", "cat": "source" }, { "term": "Ius in re", "gloss": "m) (вещно право", "body": "Израз, използван от средновековните юристи за определяне на вещното право. То се противопоставя на jus in personen, което означава облигационно право.", "cat": "source" }, { "term": "Ius liberorum", "gloss": "право, свързано с децата", "body": "Привилегия, въведена най-напред от император Октавиан Август (Lex Iulia Papia Poppaea) по отношение на родителите, които вече имат три деца (дори и да са починали) (ius trium liberorum*). Жените по този начин се освобождават от настойничество (tutela*). От IV в. сл. Хр. дори могат да бъдат назначавани за настойници на своите непълнолетни деца и самите те могат да съставят завещание, могат самостоятелно да избягнат публично задължение или възлагане на задължения на законно настойничество (вж. excusatio tutoris*).", "cat": "source" }, { "term": "Ius naturale", "gloss": "естествено право", "body": "Понякога то не се различава от правото на народите (ius gentium*). Ius naturale се състои в съвкупността от правила, които действат в природата и които се прилагат по отношение на всички живи същества. Така например робството, което произлиза от ius gentium, не е познато на ius naturale.", "cat": "source" }, { "term": "Ius possidendi", "gloss": "право да се владее", "body": "(1) Право да се владее (possessio*), което по принцип принадлежи на собственика на вещта (dominus*); приема се за еквивалентно на правото на ползване.\n(2) Право да се владее предоставената като обезпечение на вземане вещ, което принадлежи на кредитора – залогоприемателя от деня на сключване на договора за залог (pignus*).", "cat": "source" }, { "term": "Ius postliminii", "gloss": "възстановяване на правата на военнопленника при завръщането му в Рим", "body": "Вж. postliminium*.", "cat": "source" }, { "term": "Ius praetorium", "gloss": "преторско право", "body": "Съвкупност от правни норми, въведени постепенно чрез преторските едикти (срв. edictum* и praetor*) с цел да се подпомогне, допълни и коригира цивилното право (вж. ius honorarium*).", "cat": "source" }, { "term": "Ius privatum", "gloss": "частно право", "body": "Сферата на правото, която регулира интересите на отделните лица, техните взаимоотношения, собствеността, договорите и наследството.", "cat": "source" }, { "term": "Ius prohibendi", "gloss": "право на противопоставяне", "body": "Предоставено на собственика право да се противопостави, дори и с физическа сила, на всяко засягане на вещта в нейната цялост, което се осъществява без неговото съгласие. и отговорите и становищата по правни въпроси на римските юристи (responsa*).", "cat": "source" }, { "term": "Ius publicum", "gloss": "публично право", "body": "Сферата на правото, която урежда устройството на римската държава, статута на магистратите, религиозната организация и отношенията, които засягат интересите на цялата общност. Според Улпиан това право не може да бъде променяно от частни споразумения.", "cat": "source" }, { "term": "Ius Quiritium", "gloss": "квиритско право, право на Quirites", "body": "Архаичен израз, синоним на цивилно право (ius civile*), който произтича от факта, че първоначално правото е приложимо само за римските граждани (civis Romanus*) – квиритите (Quirites*), с което име те официално са се наричали при участието им в народните събрания.", "cat": "source" }, { "term": "Ius respondendi", "gloss": "ex auctoritate principis", "body": "(право да се дават отговори на правни въпроси по силата на овластяване от принцепса)\nПривилегия, предоставена от времето на император Октавиан Август на някои юристи (iurisconsulti*) да дават отговори и да изразяват становища по правни въпроси (responsa*). Тя произтича от специалното овластяване на императора.", "cat": "source" }, { "term": "Ius retentionis", "gloss": "право на задържане", "body": "Право на длъжника (debitor*) в случаите на претендиране на една вещ от ищеца, да я задържи до заплащането на направените от него разноски (impensae*). Това право се упражнява във формуларната процедура (срв. formula*) чрез включване на възражение за измама (exceptio doli*) във формулата.", "cat": "source" }, { "term": "Ius scriptum", "gloss": "писано право", "body": "Право, изразено в писмена форма (ex scripto), за разлика от неписаното право (ius non scriptum), включващо обичая (consuetudo*). (срв. damnum iniuria datum*) или друг деликт (delictum*), да изостави роба или подвластния (и да ги предаде под властта) на потърпевшия, вместо да заплати глобата и обезщетението за вреди (срв. също похае deditio*).", "cat": "source" }, { "term": "Ius singulare", "gloss": "специално право", "body": "Израз за означаване на специално предоставено право на определена група лица или по отношение на определени имущества или правоотношения. В повечето случаи се отнася до изключения от общи принципи и от общото право (ius commune).", "cat": "source" }, { "term": "Ius suffragi", "gloss": "право да се гласува", "body": "Право да се гласува в народното събрание (comitia*).", "cat": "source" }, { "term": "Ius tollendi", "gloss": "право да вземе нещо със себе си", "body": "Право, предоставено в следкласическия период на добросъвестния (bona fides*) или недобросъвестния (dolus malus*) владелец (срв. possessio*), който е ответник по ревандикационния иск (reivindicatio*), да вземе със себе си една вещ, която принадлежи на него или на трето лице, т.е. която може да бъде отделена от главната вещ, без да я увреди.", "cat": "source" }, { "term": "Ius trium vel quattuor liberorum", "gloss": "право, свързано с наличието на 3 или 4 деца", "body": "Привилегия, предоставена от императора Октавиан Август на жените, които имат вече три (за свободoродените) или четири деца (за освобожденките). Срв. ius liberorum*.", "cat": "source" }, { "term": "Ius utendi", "gloss": "право на ползване", "body": "Едно от правомощията на титуляра на вещно право, което му позволява свободно да ползва вещта.", "cat": "source" }, { "term": "Ius vetus", "gloss": "древното, старото право", "body": "За юристите от класическата епоха това е правото, което е създадено в архаичния и предкласическия период.", "cat": "source" }, { "term": "Ius vitae ac necis", "gloss": "право на живот и смърт", "body": "Правото на живот и смърт в архаичното римско право се е притежавало от домовладелеца (paterfamilias*) за лицата, които са под неговата власт (patria potestas*).", "cat": "source" }, { "term": "Kalendae", "gloss": "календи", "body": "Първият ден на месеца при римляните, което съответства в търговските отношения на определената дата, в която изтича уговорен едномесечен срок за погасяване на дългове.", "cat": "source" }, { "term": "Kalendarium", "gloss": "календар", "body": "(1) Книга, в която лихварите вписват заетите от тях суми и падежите с оглед определяне на месечните лихви;\n(2) Регистър за ражданията под формата на codex* или свитък папирус, в който се вписват декларираните раждания на деца в Рим.", "cat": "source" }, { "term": "Leges datae", "gloss": "„предоставени“ закони", "body": "Закони, издадени еднолично от военачалник победител, от висш магистрат (magistratus*) по време на Републиката или от Империята, по силата на делегирана компетентност, с които се определя правният статус на победен град или народ. Вж. също leges rogatae*.", "cat": "source" }, { "term": "Leges generales", "gloss": "общи закони", "body": "Термин, който, по силата на една конституция на император Валентиниан III, трябва да бъде включен изрично, когато на императорския рескрипт (rescriptum*) трябва да се придаде обща сила с оглед приложението му за всички поданици на Империята.", "cat": "source" }, { "term": "Leges mancipii", "gloss": "клаузи, свързани с манципацията", "body": "Допълнителни клаузи на манципацията (mancipatio*), които се включват в нея по искане на отчуждителя или на преобретателя и които имат за цел да пригодят процедурата за исканите от страните цели.", "cat": "source" }, { "term": "Leges regiae", "gloss": "„царски“ закони", "body": "Закони, приписвани на рекса (rex*), който е управлявал Рим преди установяването на Републиката.", "cat": "source" }, { "term": "Leges rogatae", "gloss": "гласувани от народното събрание закони", "body": "Закони, които се приемат от народното събрание (comitia*) и носят наименованието си според името на магистрата (magistratus*), който ги предлага. Вж. и leges datae*.", "cat": "source" }, { "term": "Leges Romanae barbarorum", "gloss": "варварски римски закони", "body": "По силата на лично действие на законите, това са приетите от варварските народи (barbari*) закони, които се прилагат само за завареното романизирано население (civis Romanus*). Тези закони имат римскоправна основа – това са по-специално Edictum Theodorici, наречен Lex romana Burgundionum*, и Lex romana Visigothorum*, наричин също Бревиарий на Аларих (Breviarium Alarici).", "cat": "source" }, { "term": "Lex", "gloss": "закон", "body": "Според определението на известния юрист Гай, законът е „това, което народът повелява и установява“. В стриктен смисъл законът е схващан като волеизявление с нормативно съдържание, което е прието от народа в народното събрание. Със сила на закон се считат и актовете, приети от плебейското народно събрание (concilia plebis*) под формата на плебисцити (plebiscitum*). В по-широк смисъл законът се схваща като съвкупност от общи и абстрактни правни норми. В този смисъл като закон може да се разглеждат и постановленията на Сената, наречени сенатусконсулти (senatusconsultum*) и императорските конституции (constitutiones Principis*). От формална гледна точка се различават leges datae* и leges rogatae*. Lex Aelia Sentia\nЗакон, гласуван по времето на император Октавиан Август (4 г. сл.Хр.), с който се урежда освобождаването (manumissio*) на роби (servus*), като се определя минимална възраст на господаря (20 г.) и на роба (30 г.), за да бъде валидно това освобождаване. Със закона се забранява освобождаването с цел увреждане на интересите на кредитора (creditor*) или патрона (patronus*). Lex Apuleia de sponsu\nЗакон от края на III век пр.Хр. (вероятно между 240 и 130 г. пр.Хр.), приложим по въпросите на поръчителството (fidepromissio* и sponsio*), който дава възможност на един от поръчителите, заплатил изцяло гарантирания с поръчителство дълг, да иска съответните суми от другите поръчители.", "cat": "source" }, { "term": "Lex Aquilia de damno", "gloss": "Аквилиев закон относно причиняването на вреда", "body": "Закон, приет вероятно през 286 г. пр.Хр. под формата на плебисцит (plebiscitum*), който санкционира увреждането на чужда вещ (obligationes ex delicto*). Този закон е в основата на съвременната отговорност за непозволено увреждане. Lex Atinia de usucapione\nЗакон, който въвежда забраната за придобиване по давност (usucapio*) на крадени вещи (res furtiva*). Датира се към края на III и началото на II век пр.Хр. Lex Calpurnia de condictione\nЗакон, чиято дата на издаване е неизвестна (след 204 г. пр.Хр.) и който разширява приложното поле на condictio (legis actio per condictionem; срв. legis actiones*), преди това ограничавано само до задължението за парична сума (Lex Silia). С този закон легисакцията се прилага и за всички задължения с обект индивидуално определени вещи. Lex Canuleia de conubio\nЗакон или плебисцит (plebiscitum*), гласуван по предложение на трибуна Canuleius през 445 г. пр.Хр., с който плебеите придобиват право да сключват законен римски брак по цивилното право (срв. ius conubii*). С него като последица са разрешени и браковете между плебеи (срв. plebs*) и патриции (patricii*). Lex Cicereia de sponsu\nЗакон с неопределена дата на издаване (към 173 г. пр.Хр.) и приложим в материята на поръчителството и гаранциите за изпълнение на облигационното отношение (срв. fidepromissio* и sponsio*). С него кредиторът (creditor*) се задължава в момента на установяване на поръчителството да обяви на висок глас размера на дълга и броя на поръчителите. В противен случай поръчителите не се считат за обвързани. Lex Cincia de donis et muneribus\nПлебисцит (plebiscitum*) от 204 г. пр.Хр., гласуван по предложение на плебейски трибун (tribunus plebis*) за ограничаване на свободата (donatio*). Законът забранява на адвокатите да получават подаръции и пари за техните пледирания в съда и забранява дарения над определен размер, извършвани от определени в закона категории лица.", "cat": "source" }, { "term": "Lex curiata de imperio", "gloss": "куриатен закон относно висшата военна власт", "body": "Законът, гласуван от куриатните комиции (comitia curiata*), с което се предоставя висша военна власт (imperium*) на един магистрат (magistratus*).", "cat": "source" }, { "term": "Lex de imperio", "gloss": "закон относно висшата военна власт", "body": "Закон, гласуван от народното събрание (comitia*), който предоставя на императора право да предприема мерки в обществен интерес и по-специално да утвърждава законодателни актове (вж. constitutiones principis*).", "cat": "source" }, { "term": "Lex Romana Burgundionum", "gloss": "Бургундски римски закон", "body": "Закон, издаден към 516 г. сл.Хр. от Гондебалд, крал на бургундите, за римските поданици на неговото кралство. Той се състои от фрагменти от императорски конституции (constitutiones principis*) и съчинения на римските юристи и може да бъде сравняван с lex Romana Visigothorum*.", "cat": "source" }, { "term": "Lex Romana Visigothorum", "gloss": "Вестготски римски закон", "body": "Наричан още Бревнарий на Аларих, този закон е създаден през 506 г. сл.Хр. по нареждане на вестготския крал Аларих II за римските поданици в Испания и Аквитания. Съдържа резюме на Институциите на Гай (Institutiones Gai*), фрагменти от Сентенциите на Паул (Sententiae Pauli*), и от Хергениановия (Codex Hermogenianus*), Грегориановия (Codex Gregorianus*) и Теодосиевия (Codex Theodosianus*) кодекси и някои конституции, издадени след император Теодосий – т.нар. посттеодосиеви новели.", "cat": "source" }, { "term": "Lex XII", "gloss": "duodecim) tabularum (Закон за XII-те таблици", "body": "Закон, който се счита за основа на Римското право (ius civile*). Той е сбор от обичайноправни норми, създаден между 451-450 г. пр.Хр. от колегия от 10 магистрати (decemviri*) и изписан на 12 табла (таблици). С него се придава писмена форма на древните обичаи в различни области на частното и наказателното право, но съдържа също и норми от сакралното право. Lex Falcidia\nС този закон, датиран към 24 г. пр.Хр., се защитават наследниците (heres*), защото той разрешава завещателят (срв. testamentum*) да се разпорежда под формата на легати (legatum*) само до три-четвърти от наследственото имущество. Lex Furia de sponsu\nЗакон с неопределена дата на приемане (между 230 и 130 г. пр.Хр.) относно поръчителството (срв. fidepromissio* и sponsio*), който предвижда обезпечението да се подели между живите съпоръчители към деня на падежа, а също и неговото погасяване в двугодишен срок след падежа. Lex Hortensia de plebiscitis\nЗакон, гласуван през 287 г. пр.Хр. след третата сецесия на плебеите (plebs*) на хълма Janiculus, с който плебисцитите (plebiscitum*) се приравняват на гласуваните от центуриантните комиции (comitia centuriata*) закони и им се придава задължителна сила за целия римски народ. Lex Irnitana\nНаименование на множеството бронзови таблички, върху които е възпроизведено съдържанието на Lex municipii Flavii Irnitanii, провинциален закон, уреждащ процесуални въпроси в муниципиите на Ирния (дн. Испания) от времето на Флавиите (69–96 сл.Хр. Те са открити в близост до Севиля (El Saucejo) през 1981 г. Lex Iulia de adulteriis\nЗакон, гласуван по времето на император Октавиан Август през 18 г. пр.Хр., с който се санкционират блудството (stuprum) и прелюбодеянието (adulterium), които по отношение на жената водят до изгонване от фамилията или дори до заточение на усамотено място без намаляване на правоспособността (capitis deminutio*). Законът забранява отчуждаването на италийските зестрални имоти (вж. dos*) без съгласието на съпругата (uxor*). Lex Iulia de maritandis ordinibus\nЗакон, гласуван по време на император Октавиан Август през 18 г. пр.Хр. срещу ергенството, който е първият от т.нар. ограничителни закони. С него се въвеждат неблагоприятни последици, най-вече в областта на наследяването. Законът улеснява браковете (matrimonium*) на подвластни дъщери (pater familias*) да предостави зестра на дъщеря си (срв. dos*). Разпорежданията му се допълват от lex Papia Poppaea nuptialis*, вероятно и от втория lex Iulia от 4 г. сл.Хр. Lex Iulia iudiciorum privatorum\nЗакон, гласуван по времето на император Октавиан Август през 17 г. пр.Хр. Той урежда граждански процес, като отменя окончателно легисакционната процедура (legis actiones*) и утвърждава формуларната процедура като обща за всички гражданскоправни спорове (actiones per formulas*). Lex Laetoria de minoribus\nЗакон, гласуван към 200 г. пр.Хр. с цел да се защитят лицата между 12 г. (за момичетата), респ. 14 г. (за момчетата и ненавършилите 25 г. лица (minor XXV [viginti quinque] annorum*) срещу вредоносните действия на други лица, които се възползват от тяхната неопитност и ги въвличат в неизгодни юридически операции (circumscriptio*). Законът дава възражение (срв. exceptio legis Laetoriae*) в полза на ненавършилото 25 години лице срещу кредитора ищец.", "cat": "source" }, { "term": "Libri", "gloss": "книги, томове", "body": "Множествено число от liber*.", "cat": "source" }, { "term": "Lictores", "gloss": "ликтори", "body": "Подчинени на републиканския магистрат (magistratus*) лица, които вървят пред него по време на церемонии и изпълняват неговите нареждания. Те свикват римското народно събрание (comitia*).", "cat": "source" }, { "term": "Littera florentina", "gloss": "Флорентина, флорентинска версия на Дигестите", "body": "Израз, за означаване на най-старата достигнала до нас версия на Дигестите (digesta*). Написана е в края на VI и началото на VII в. сл.Хр. Открита е в Пиза през 1050 г., пренесена като военна плячка във Флоренция (Polizius) 1406 г. От края на XV в., хуманистите (Polizius) предпочитат тази версия пред Вулгатата (vulgata*), използвана от глосаторите.", "cat": "source" }, { "term": "Lustrum", "gloss": "лустрация", "body": "(1) Действие по заличаване от списъците на римските граждани на определени лица, което се извършва от цензорите (censores*) на всеки пет години с цел „прочистване“ на римския народ.\n(2) Период от пет години, за който обикновено се сключват договори за аренда (наем) на недвижими имоти (срв. locatio-conductio rei*).", "cat": "source" }, { "term": "Magister officiorum", "gloss": "ръководител на служба", "body": "Висш ръководен служител по време на късната Империя. Той ръководи императорската канцелария и отговаря за императорската кореспонденция.", "cat": "source" }, { "term": "Magistratus", "gloss": "магистратура, титуляр на публична длъжност", "body": "(1) Публична длъжност, упражнявана от името на римския народ, на град (civitas*) или на муниципия (municipium*), която предоставя на своя титуляр административна и правораздавателна власт;\n(2) Самият магистрат, който е титуляр на магистратурата. Висшите магистрати – консули (consules*) и претори (praetor*), притежават военна власт (imperium*), която нямат низшите магистрати.", "cat": "source" }, { "term": "Mores", "gloss": "нрави, поведение", "body": "В множествено число mos и в самостоятелна употреба този термин означава обичай. Boni mores (добри нрави) се състоят в съвкупност от правила за поведение на всички римляни, които могат да се считат за добри граждани (bonus vir*) и чието нарушение може да доведе до цензорска санкция по силата на функциите на цензора (censores*), да управлява контрол върху частния и публичен живот на всички римляни (Вж. nota censoria*).\nВ съпружеските отношения се различават:\n— mores graviores (лошо поведение): тежко провинение (прелюбодеяние – adulterium) на мъжа или жената по време на съпружеското съжителство;\n— mores leviores (укоримо поведение): по-леко провинение по време на брака, което води при развод (divortium*) до по-малка парична санкция, отколкото тази при прелюбодеянието.", "cat": "source" }, { "term": "Mores maiorum", "gloss": "обичаите на предците", "body": "Съвкупност от обичаи, използвани в архаичния период за уреждане на отношенията между частните лица. Терминът се използва и като синоним на consuetudo* като източник на правото.", "cat": "source" }, { "term": "Nota censoria", "gloss": "цензорска нота", "body": "Санкция, налагана по времето на Републиката и в началото на Империята от цензорите (срв. censores*) по отношение на мъж или жена, които са извършили действия, несъвместими с поведението на добросъвестни римски граждани (срв. boni mores* и mores*). Вж. също и infamia*.", "cat": "source" }, { "term": "Novellae Iustiniani", "gloss": "Новелите на Юстиниан", "body": "Конституции (constitutiones principis*), издадени от император Юстиниан в периода между 535 и 566 г. сл.Хр. (срв. Corpus Iuris Civilis*). Те не се издават като притурка към кодекса (срв. Codex repetitae praelectionis*), макар че императорът първоначално е имал такова намерение. Отчасти са запазени в Authenticum*, както и в сборник на император Тиберий II (578–582 г.) и в Epitome Juliani.", "cat": "source" }, { "term": "Nudum ius Quiritium", "gloss": "голото квиритско право", "body": "Израз, чрез който юристът Гай определя статуса на квиритския собственик (срв. dominium ex iure Quiritium*) на една вещ, когато той е лишен от нейните практически ползи. Така например този собственик е противопоставен на защитавания от претора узукапионен владелец (срв. usucapio*), който се счита за преторски собственик и притежава вещта в своя патримониум (in bonis esse*).", "cat": "source" }, { "term": "Oratio", "gloss": "principis in senatu) (реч, произнесена от императора пред Сената", "body": "Първоначално това е произнесена от императора или от негов представител реч, която се предлага приемането на сенатусконсулт (senatusconsultum*) от Сената (senatus*). По-късно така се наричат и самите сенатусконсулти, приети по предложение на императора. Oratio Antonini\nСенатусконсулт (senatusconsultum*), приет през 206 г. сл.Хр. по предложение на император Каракала, с което се валидират даренията (donatio*) между съпрузи, забранени до този момент, ако дарителят умре по време на брака, без да промени волята си. Oratio Marci\nСенатусконсулт (senatusconsultum*) по предложение на император Марк Аврелий, с който се уточняват последиците от признанието на ответника пред съда (confessio in iure*) в екс- Oratio Severi: (текстът е отрязан)\nOrdo (съсловие)\n(1) Социална група от лица, притежаващи определен статус и се ползващи с привилегии и задължения.\n(2) Ред, по който се извършват процесуалните действия в съдебния процес (ordo iudiciorum privatorum).", "cat": "source" }, { "term": "Paraphrasis Institutionum Theophili", "gloss": "парафраза на Теофил) Институциите на Юстиниан", "body": "Гръцка адаптация на Институциите на Юстиниан (Institutiones Iustiniani*) под редакцията на Теофил – професор от Бейрутската правна школа (antecessor*). Той е бил член на комисията, създадена за съставянето на Институциите и публикува парафразата няколко месеца след публикуването на официалната латинска версия.", "cat": "source" }, { "term": "Patres conscripti", "gloss": "вписани сенатори", "body": "С този термин се означават сенаторите (срв. senatus*) с плебейски произход (срв. plebs*), които са избрани от цензорите (censores*) при увеличаване на броя на членовете на Сената (и вписани допълнително в списъците на сенаторите). По-късно с този термин се означава всички сенатори, независимо от това дали по произход са патриции или плебеи.", "cat": "source" }, { "term": "Plebiscitum", "gloss": "плебисцит", "body": "Закон, гласуван от плебейското народно събрание (concilia plebis*) по предложение на пребейски трибун (срв. tribuni plebis*). От времето на lex Hortensia* (287 г. пр.Хр.) плебисцитите придобиват сила на закон (lex*), гласуван от центуриатните кумиции (comitia centuriata*).", "cat": "source" }, { "term": "Pontifex", "gloss": "понтифекс", "body": "Член на колегията на жреците, които изпълняват култа към Юпитер. Неговата основна функция е да тълкува сакралното право (fas*).", "cat": "source" }, { "term": "Pontifex maximus", "gloss": "велик /върховен/ понтифекс", "body": "Върховен ръководител на римската религия, който е начело на колегията на понтифиците (pontifex*). Той се избира измежду бившите магистрати (magistratus*) или юрисконсултите (iuriconsulti*) във връзка с правните и политически проблеми, които трябва да разрешава.", "cat": "source" }, { "term": "Praefecti", "gloss": "префекти", "body": "Императорски служители, натоварени с различни административни функции, например да управляват провинция, да ръководят императорска гвардия и пр.", "cat": "source" }, { "term": "Praefectus annonae", "gloss": "префект на аноната /снабдяването/", "body": "Префект, който е отговорен за снабдяването с храни и разпределение на зърното в Рим", "cat": "source" }, { "term": "Princeps", "gloss": "принцепс", "body": "Титла на първия гражданин в Рим. Принцепсът е пръв сред равни, но постепенно изтича в монархическа власт.\n(1) praetor urbanus (градски претор): той е натоварен от 367 г. пр.Хр. да упражнява правораздавателна дейност по спорове между римски граждани (civis Romanus*).\n(2) praetor peregrinus (перегрински претор): той е натоварен с правораздаването по спорове между римски граждани (civis Romanus*) и чужденци (peregrini*), както и само между чужденци", "cat": "source" }, { "term": "Princeps legibus solutus", "gloss": "принцепсът не е обвързан от закона", "body": "Принцип, който се прилага в определени периоди, основан на становище на Улпиан (D. 1,3,31), според което императорът не е подчинен на действие на законите. Всъщност в този фрагмент става въпрос само за неприлагане на lex Papia Poppaea (по отношение на принцепса и неговите роднини).", "cat": "source" }, { "term": "Principatus", "gloss": "Принципат", "body": "Период от развитието на римското право, което включва времето между началото на управление на император Октавиан Август (27 г. пр.Хр.) до заемането на престола от император Диоклециан (284 г. сл.Хр.).", "cat": "source" }, { "term": "Privilegium", "gloss": "привилегия по силата на закон, от „lex privata“, законна привилегия", "body": "В класическото римско право това е норма, която се прилага само за определена категория лица или групи лица.", "cat": "source" }, { "term": "Proconsules", "gloss": "проконсули", "body": "В края на Републиката това са консулите, които, след изтичането на мандата им остават на длъжност за следващата година начело на провинция в качеството на нейни управители по силата на решение на народното събрание или сенатусконсулт. По време на Принципата с този термин се означава управител на сенаторска провинция, който изпълнява функцията си за една година.", "cat": "source" }, { "term": "Proculiani", "gloss": "прокулеанци", "body": "Израз за означаване на юристи от школата на Прокул (I век сл.Хр.), които са последователи на големия юрист от времето на император Октавиан Август Лабеон и творят до средата на II век сл.Хр. На тях се противопоставят юристи – сабинианци (Sabiniani).", "cat": "source" }, { "term": "Promulgatio", "gloss": "промулгиране, обнародване", "body": "Формален акт на императора, с който се придава правна сила на императорската конституция и тя влиза в действие.", "cat": "source" }, { "term": "Propraetores", "gloss": "пропреатори", "body": "Претори, чийто мандат е изтекъл, но е продължен за следващата година, и които са определени за управители на провинция.", "cat": "source" }, { "term": "Prorogatio", "gloss": "пророгация, продължение", "body": "Това е продължаването на длъжностен мандат на магистрата в римската държавна администрация, с цел той да продължи да управлява своята провинция.", "cat": "source" }, { "term": "Prorogatio imperii", "gloss": "пророгация (продължение) на imperium", "body": "Това е републикански институт, свързан с продължаване на правомощията, и най-вече висшата военна власт (imperium) на един магистрат (magistratus) след изтичане на мандата му с цел да довърши военен поход или да уреди управлението на завоеваната територия.", "cat": "source" }, { "term": "Provincia", "gloss": "провинция", "body": "Териториална обособеност извън Италия, която е организирана административно по римското право с lex data (срв. leges datae), издадена по оправомощаване от римския народ от римски пълководец-победител, римски магистрат, а по-късно от самия император. Различават се:\n- provinciae senatoriae (сенаторски провинции), които са под контрола на Сената (senatus);\n- provinciae Caesaris (императорски провинции), които са под контрола на императора (princeps).", "cat": "source" }, { "term": "Prudentes", "gloss": "знаещите правото", "body": "Термин за означаване на римските юристи.", "cat": "source" }, { "term": "Quaestores", "gloss": "квестори", "body": "Низши магистрати, избирани от народните събрания, чиито брой е различен (от двама първоначално, до четиридесет към 45 г. пр.Хр.), които са натоварени да подпомагат консулите (consules*) и преторите (praetor*) при управление на финансите, както и в наказателно правораздаване. Те се занимават и с финансите на войската.", "cat": "source" }, { "term": "Rentio", "gloss": "ретенция, право на задържане", "body": "право на владелца. Виж право на задържане (ius retentionis).", "cat": "source" }, { "term": "Res publica", "gloss": "общо дело, Република", "body": "Политически режим в римската държавна история (509 г. пр.Хр.–27 г. пр.Хр.), който в същински смисъл означава, че управлението на държавата е общо дело на всички римляни, а интересите на отделните лица са подчинени на по-висшия интерес на цялото общество.", "cat": "source" }, { "term": "Rescriptum", "gloss": "рескрипт", "body": "Императорска конституция (constitutiones principis*), която е във формата на писмен отговор, даден от принцепса (princeps*) или от императорски съветник на едно частно лице или магистрат, които са поискали принципна консултация от императора. Различават се subscriptio (по повод на искане на частно лице) от epistula (писмо) — адресирано в отговор на питане на магистрат", "cat": "source" }, { "term": "Respondere", "gloss": "даване на отговори на правни въпроси", "body": "Дейност (iurisprudentia*) на римските юристи (iurisconsulti*) по даване на отговори (responsa*), изразяване на мнение по поставени пред тях правни въпроси.", "cat": "source" }, { "term": "Responsa", "gloss": "отговори, правни мнения", "body": "Становища, мнения по правни въпроси на римски юристи (iurisconsulti*), един от съществените елементи на римската юриспруденция (iurisprudentia*). Те представляват важен и значителен елемент, както за създаване, така и за тълкуване на правото и понякога са скрепени с властта на императора (срв. ius respondendi*).", "cat": "source" }, { "term": "Rex", "gloss": "рекс", "body": "Висша длъжност в политическата организация на архаичен Рим. Според римската традиция т.нар. „царски период“ е политически режим от митичното основаване на града през 753 г. пр.Хр. до провъзгласяване на Републиката през 509 г. пр.Хр.", "cat": "source" }, { "term": "Rogatio", "gloss": "предложение", "body": "Предложение на закон, направено от римски магистрат (magistratus*). Означава също и решение на центуриатните комиции (comitia centuriata*), които се произнасят по наложено смъртно наказание на престъпника (срв. provocatio ad populum*).", "cat": "source" }, { "term": "Roma", "gloss": "Рим", "body": "Град в Лациум, създаден според традицията от Ромул в 753 г. пр.Хр. и останал през цялата римска история център на политическата власт и столица на Римската империя.", "cat": "source" }, { "term": "S.P.Q.R., Senatus populusque Quiritus romanus", "gloss": "Сенатът и римският народ", "body": "Съкращение, което е символ и се използва за означаване на римската държава и включва двата основни органа на власт и управление – Сената (Senatus) и римския народ (на квиритите).", "cat": "source" }, { "term": "Sabiniani", "gloss": "сабинианци", "body": "Израз, с който се означават юристите, които традиционно са свързани със създадената в началото на Империята от А. Капитон, Сабин и Касий правна школа, която съществува до средата на II в. сл.Хр. Тази школа се противопоставя на школата на прокулеанците.", "cat": "source" }, { "term": "Scholiae", "gloss": "схоли", "body": "Глоси (glossa*), добавяни (към автентичните правни текстове) от византийските автори, най-вече във Василиките (Basilicae*).", "cat": "source" }, { "term": "Senatus", "gloss": "Сенат", "body": "Произлиза от древния съвет на старейшините (patres*), наричани също senatores. Сенатът е основен орган на римските политически институции. Състои се от 300 до 600 сенатори (по време на Цезар 900), първоначално само патрициански родове, а по-късно – от сенаторски семейства (patres conscripti*). По време на Републиката сенатът има компетентност: контрол върху финансовото управление на държавата, насочване на външната политика и религията.", "cat": "source" }, { "term": "Senatusconsultum", "gloss": "сенатосконсулт", "body": "Консултативно становище на Сената (Senatus) по поставени пред него въпроси от неговата компетентност. Постепенно сенатусконсулта придобива сила на закон (lex) в първите години на Принципата (principatus) и се превръща в същински източник на правото. Senatusconsultum Claudianum\nСенатусконсулт, с който господарят (dominus) на роб (servus) придобива власт върху свободната жена, която поддържа сексуална връзка с роба, въпреки забраната на неговия господар (52 г. пр.Хр.). В резултат на това се извършва максимално намаляване на правоспособността на жената (capitis deminutio maxima), която загубва свободата си и става робиня (вж. и servus; ancilla). Senatusconsultum Macedonianum\nСенатусконсулт, издаден по времето на император Веспазиан (69–79 г. сл.Хр.), по силата на който се забраняват паричните заеми (mutuum) на подвластните синове alieni iuris. Спазването на сенатусконсулта е осигурено от претора (praetor), който предоставя специално възражение (exceptio senatusconsulti Macedoniani). Senatusconsultum Tertullianum\nСенатусконсулт, издаден по време на император Хадриан (117-138 г. сл.Хр.), с което се призовава към наследство по закон майката (ius liberorum*) по отношение на своето дете заедно с неговите кръвни сестри и преди агнатите (ius liberorum*) от по-далечна степен. Senatusconsultum Velleianum\nСенатусконсулт, издаден по време на император Нерон (54-68 г. сл.Хр.), с което се забранява на жените да обезпечават (intercessio*) чужд дълг и по-специално да поръчителстват чрез fideiussio*. Преторът (praetor*) осигурява спазването на забраната чрез l'exceptio* senatusconsulti Velleiani*.", "cat": "source" }, { "term": "Senatusconsultum Macedonianum", "gloss": "Сенатусконсулт Македонианум", "body": "(dominus*), който има пълна власт (potestas) върху своите синове, не встъпва в персонална връзка с трети лица, а само чрез своя господар, който има роби. В този случай се извършва заем, който се предоставя на способни да върнат дълга лица (filius familias - maxima capitis deminutio), а не на лица, които са роби. Senatusconsultum Orphitianum\nСенатско постановление, прието от император Марк Аврелий, с което се урежда редът, по който децата (mutuus*) наследяват своите майки. Спазва се редът на законното наследяване на претора, като на децата се дава право да наследяват майка си преди роднините на майката (cognati). време на Цезар 900), които произлизат от древните патрициански семейства (patricii), а по-късно – от сенатори и с друг произход (срв. patres conscripti). Този орган е в апогея си по време на Републиката и има значителна компетентност: контрол върху магистратурите, управление на финансите, ръководство на външната политика на римската държава.", "cat": "source" }, { "term": "Sententiae Pauli", "gloss": "Сентенциите на Паул", "body": "Произведение от пет книги, приписвано на класическия юрист Паул, съставено вероятно към края на III в. сл.Хр. и допълвано до средата на VI в. сл.Хр., чиято най-пълна версия е включена в Lex Romana Visigothorum*.", "cat": "source" }, { "term": "Socius", "gloss": "съдружник", "body": "Един от двама или повече участници – страни по договора за дружество (societas*).", "cat": "source" }, { "term": "Subscriptio", "gloss": "букв. „написано отдолу“", "body": "Форма на рескрипт (rescriptum*), при която императорът (princeps*) отговаря на правен въпрос, поставен му от частно лице, с редактиране на отговора под текста на молбата с питането на това лице. Вж. също constitutiones principis*.", "cat": "source" }, { "term": "Tabulae", "gloss": "таблички, табла", "body": "Покрити с восък таблички, върху които се пишат правни актове, например завещания (testamentum*), разписки, а също и текстове на закони (lex*) – в този случай те са от бронз или от камък.", "cat": "source" }, { "term": "Tresviri", "gloss": "колегия на тримата", "body": "Колегия от три лица с различни официални функции, които се определят с добавяне на прилагателно относно дейността, която изпълняват. Така tresviri capitales имат полицейски функции и изпълняват задачи в града и в наказателно правораздаване.", "cat": "source" }, { "term": "Tribunicia potestas", "gloss": "власт на трибун", "body": "Съвкупност от правомощията на пребейските трибуни (tribuni plebis).", "cat": "source" }, { "term": "Tribunus plebis", "gloss": "плебейски трибун", "body": "Създадена през 494 г. пр.Хр. длъжност за избирани от плебса (plebs*) лица, които да защитават неговите интереси (concilia plebis*). Броят на трибуните нараства от два до десет, в зависимост от развитието на ролята на правомощията им.", "cat": "source" }, { "term": "Urbs", "gloss": "град", "body": "По-специално това е градът Рим (Roma*).", "cat": "source" }, { "term": "Vectigalium", "gloss": "вектигал, публична рента", "body": "Дължима на държавата рента за предоставени под аренда обработваеми земи (срв. ager vectigalis*), чието събиране понякога е предоставено на дружествата на публиканите (срв. societas publicanorum*).", "cat": "source" }, { "term": "Veteres", "gloss": "древните", "body": "Термин, използван в класическия период за определяне на юристите от предходните епохи, които са поставили основата на римското право през II–I век пр.Хр. (предкласическите юристи).", "cat": "source" }, { "term": "Via", "gloss": "път, право на преминаване", "body": "Израз, с който се означава едновременно път или преминаване, а също и поземлен селски сервитут (servitus praediorum*), който се състои в правото на собственика на господстващия имот да използва път за преминаване с кола през чужд имот. Той се различава от правото за преминаване пеша (iter) или за прекарване на добитъка (actus) през чужд имот.", "cat": "source" }, { "term": "Alterum non laedere", "gloss": "не вреди другиму", "body": "Един от трите основни принципа на римското право. Другите принципи са „живей честно“ (honeste vivere*) и „отдавай всекиму своето“ (suum cuique tribuere*).", "cat": "general" }, { "term": "Animus", "gloss": "намерение, воля", "body": "Психологически елемент, воля, който обуславя действието на едно лице. Намерението (animus*) заедно с фактическото ефективно господство (corpus*) е един от съставните елементи на владението (possessio*).", "cat": "general" }, { "term": "Bonus vir", "gloss": "добър, честен човек", "body": "Модел за оценка на поведение, сравнимо с това на честните хора. Често се изисква един частен арбитър (arbiter*) да разреши спор между лица като bonus vir.", "cat": "general" }, { "term": "Clam", "gloss": "тайно", "body": "В правно технически смисъл този термин се използва при владелческите интердикти (срв. също interdictum quod clam).", "cat": "general" }, { "term": "Erga omnes", "gloss": "по отношение на всички", "body": "Ефект, последица от упражняването на едно право, което може да бъде противопоставено на всички. Свързано е предимно с характеристиката на вещните права (срв. actiones in rem*).", "cat": "general" }, { "term": "Fas", "gloss": "божествена воля, това, което е позволено от боговете, сакрално право", "body": "Израз за означаване на сакралното право, което се създава предимно от понтифиците (pontifex*) и се отнася до въпроси, свързани с осъществяването на култа към боговете.", "cat": "general" }, { "term": "Fraus legis facta", "gloss": "заобикаляне на закона", "body": "Правен акт, извършен в заобикаляне на закона (lex*), при който, макар и формално да са извършени съобразените със закона действия, те са насочени към забранен резултат.", "cat": "general" }, { "term": "Honeste vivere", "gloss": "живей честно", "body": "Едно от трите основни предписания на римското право. Другите две са: „не вреди другиму“ (alterum non laedere*) и „отдавай всекиму своето“ (suum cuique tribuere*).", "cat": "general" }, { "term": "Ignorantia legis neminem excusat", "gloss": "Незнанието на правото никого не извинява; за никой не е допустимо да не знае правото", "body": "Фактът на незнание на съществуването или на значението на закон или на отделна правна норма не е извинително. В подобен смисъл дори се счита, че незнанието на правото вреди (Ignorantia iuris nocet).", "cat": "general" }, { "term": "In factum", "gloss": "основани на факти", "body": "Израз за определяне на особен вид искове, в които претенцията е основана на факти, а не на права Вж. actiones in factum*.", "cat": "general" }, { "term": "Nefas", "gloss": "няма превод", "body": "Това, което е забранено от боговете, т.нар. dies nefasti са дни, през които не може да се правораздава. Вж. също fas*.", "cat": "general" }, { "term": "Pars", "gloss": "част", "body": "Част от някакво действие или от едно цяло (pars pro toto).", "cat": "general" }, { "term": "Piae causae", "gloss": "за благотворителни цели", "body": "Израз, с който се определят благотворителните фондации и по време на късната Империя, които имат за цел да подпомогнат нуждаещите се лица и учрежденията, които осъществяват социална дейност (например сиропиталища, болници). Виж и universitas bonorum*.", "cat": "general" }, { "term": "Principium", "gloss": "начален", "body": "В Юстиниановата компилация (срв. Corpus Iuris Civilis) това е въводният текст на всеки фрагмент (pr.), който е преди номерираните параграфи. Понякога означава и началните изрази на интердикт (interdictum).", "cat": "general" }, { "term": "Quaestus", "gloss": "полза, приход", "body": "При договора за дружество (societas*) това е реализираният приход в резултат на действие- то на един съдружник (socius*).", "cat": "general" }, { "term": "Ratio iuris", "gloss": "смисълът на правото", "body": "Основание, изведено от действащото право и представено от един римски юрист (iurisconsulti*), с цел уточняване на тълкуването, което той дава на правен принцип или във връзка с дадено от него становище по конкретен казус.", "cat": "general" }, { "term": "Ratio legis", "gloss": "смисълът на закона", "body": "Преследваната от закона (lex*) цел, за която трябва да държат сметка всички, които тълкуват или коментират закона, за да открият действителния смисъла на норми с неясно (двусмислено) съдържание. Това изследване на целите на закона се проявява още в края на Републиката.", "cat": "general" }, { "term": "Ratio naturalis", "gloss": "естествена справедливост", "body": "Принцип, свързан с естествено състояние на нещата в природата, основан на естественото право (ius naturale*).", "cat": "general" }, { "term": "Regula iuris", "gloss": "правно правило, правна норма", "body": "Терминът се използва във връзка с правния принцип, изведен от закона (lex) и прилаган от съдията (iudex) или от юриста (iurisconsulti), въз основа на които се правят по-нататъшните правни разрешения.", "cat": "general" }, { "term": "Superfluum", "gloss": "надвзето", "body": "Сума, която надвишава размера на дълга (pignus) след извършена публична продан от заложния кредитор. Той трябва да върне тази сума на длъжника (debitor), след като е удовлетворил своето вземане. Вж. също ius distrahendi.", "cat": "general" }, { "term": "Suum cuique tribuere", "gloss": "да се отдава всекиму своето", "body": "Един от трите основни предписания от римското право. Другите две са да не се вреди другиму (alterum non laedere) и да се живее честно (honeste vivere).", "cat": "general" }, { "term": "Tempus regit actum", "gloss": "времето определя сделката", "body": "Израз, с който се определя, че правният акт, а също и процесуалните действия, трябва да се преценяват според правното положение в момента на извършването им.", "cat": "general" }, { "term": "Uncia", "gloss": "унция", "body": "Обикновено 1/12 част от наследството\nUnciae usurae (дванадесета част от лихвата)\nЕдна дванадесета част от лихвата usurae centesimae*, т.е. един процент (%) годишно.", "cat": "general" }, { "term": "Vexata quaestio", "gloss": "измъчен въпрос", "body": "Правен въпрос, който се дискутира отдавна, без да се достигне до еднозначен отговор", "cat": "general" }];
const $ = s => document.querySelector(s);
const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const slug = s => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const ids = new Map(DATA.map((e, i) => { e.id = 't-' + slug(e.term) + '-' + i; return [e.term.toLowerCase(), e.id] }));
const firstWord = new Map();
DATA.forEach(e => { const w = e.term.toLowerCase().split(/\s+/)[0]; firstWord.set(w, firstWord.has(w) ? null : e.id) });
const CATS = [{ "key": "person", "name": "Лично право", "icon": "👤" }, { "key": "family", "name": "Семейно право", "icon": "👪" }, { "key": "thing", "name": "Вещно право", "icon": "🏺" }, { "key": "obl", "name": "Облигационно право", "icon": "🤝" }, { "key": "inherit", "name": "Наследствено право", "icon": "📜" }, { "key": "proc", "name": "Процес", "icon": "⚖️" }, { "key": "crim", "name": "Наказателно право", "icon": "🗡️" }, { "key": "source", "name": "Източници на правото и държавно устройство", "icon": "🏛️" }, { "key": "general", "name": "Общи понятия и принципи", "icon": "📖" }];
const catBy = Object.fromEntries(CATS.map(c => [c.key, c]));
let cat = 'all', query = '';
const letterOf = e => (e.term[0] || '#').toUpperCase();

function inline(s) {
    s = esc(s).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>');
    return s.replace(/([A-Za-z\u00C0-\u017F][\w\u00C0-\u017F\-\.]*)\*/g, (m, w) => {
        const k = w.toLowerCase().replace(/\.$/, '');
        const id = ids.get(k) || firstWord.get(k);
        return id ? `<a class="x" href="#${id}">${w}</a>` : `<span class="x">${w}</span>`;
    });
}
function body(txt) {
    const lines = txt.split('\n').map(l => l.trim()).filter(Boolean);
    let out = '', list = [];
    const flush = () => { if (list.length) { out += '<ul>' + list.map(x => `<li>${inline(x)}</li>`).join('') + '</ul>'; list = []; } };
    for (const l of lines) {
        const m = l.match(/^(?:[-–—•]|\(\d+\))\s*(.*)$/);
        if (m && /^[-–—•]/.test(l)) list.push(m[1]); else { flush(); out += `<p>${inline(l)}</p>`; }
    }
    flush(); return out;
}
function card(e, n) {
    return `<article id="${e.id}"><h2><span class="n">${n}</span>${esc(e.term)}</h2>` +
        (e.gloss ? `<div class="gloss">${inline(e.gloss)}</div>` : '') + `<div class="body">${body(e.body)}</div></article>`;
}
function current() {
    const q = query.toLowerCase();
    return DATA.filter(e => (cat === 'all' || e.cat === cat) && (!q || (e.term + ' ' + e.gloss + ' ' + e.body).toLowerCase().includes(q)));
}
function render() {
    const items = current(); let html = '', n = 0;
    if (cat === 'all') {
        for (const c of CATS) {
            const g = items.filter(e => e.cat === c.key); if (!g.length) continue;
            html += `<section id="C-${c.key}"><h3 class="catbar"><span>${c.icon}</span>${esc(c.name)}<small>${g.length} термина</small></h3><div class="catline"></div>` + g.map(e => card(e, ++n)).join('') + '</section>';
        }
    } else {
        const c = catBy[cat]; let cur = '';
        html += `<h3 class="catbar"><span>${c.icon}</span>${esc(c.name)}</h3><div class="catline"></div>`;
        for (const e of items) {
            const L = letterOf(e);
            if (L !== cur) { cur = L; html += `<div class="letter" id="L-${L}">${esc(L)}</div>` }
            html += card(e, ++n);
        }
    }
    $('#list').innerHTML = html;
    $('#cnt').textContent = items.length + ' от ' + DATA.length;
    $('#none').style.display = items.length ? 'none' : 'block';
    buildAZ(items); highlight(query);
}
function buildAZ(items) {
    const az = $('#az');
    if (cat === 'all') {
        const ks = [...new Set(items.map(e => e.cat))];
        az.className = 'az cats';
        az.innerHTML = ks.map(k => `<a href="#C-${k}">${catBy[k].icon} ${esc(catBy[k].name.split(' и ')[0])}</a>`).join('');
    } else {
        az.className = 'az';
        az.innerHTML = [...new Set(items.map(letterOf))].map(l => `<a href="#L-${l}">${esc(l)}</a>`).join('');
    }
}
// dropdown
function buildMenu() {

    const all = [{ 
        key: 'all', name: 'Всички категории', icon: '🗂️' }, ...CATS
    ];

    $('#ddm').innerHTML = all.map(c => {
        const n = c.key === 'all' ? DATA.length : DATA.filter(e => e.cat === c.key).length;
        return `<button class="dd-item" role="menuitem" data-k="${c.key}" aria-selected="${c.key === cat}"><span>${c.icon}</span><span>${esc(c.name)}</span><span class="c">${n}</span></button>`;
    }).join('');
    const c = cat === 'all' ? { icon: '🗂️', name: 'Всички категории' } : catBy[cat];
    $('#ddl').textContent = c.icon + ' ' + c.name;
}
const menu = $('#ddm'), ddb = $('#ddb');
const setOpen = o => { menu.classList.toggle('open', o); ddb.setAttribute('aria-expanded', o) };
ddb.onclick = e => { e.stopPropagation(); setOpen(!menu.classList.contains('open')) };
menu.onclick = e => { const b = e.target.closest('.dd-item'); if (!b) return; cat = b.dataset.k; setOpen(false); buildMenu(); render(); scrollTo({ top: 0 }) };
document.addEventListener('click', () => setOpen(false));
document.addEventListener('keydown', e => { if (e.key === 'Escape') setOpen(false) });
function highlight(q) {
    if (!q) return;
    const re = new RegExp('(' + q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + ')', 'gi');
    const w = document.createTreeWalker($('#list'), NodeFilter.SHOW_TEXT);
    const nodes = []; while (w.nextNode()) nodes.push(w.currentNode);
    nodes.forEach(nd => {
        if (!re.test(nd.nodeValue)) return; re.lastIndex = 0;
        const sp = document.createElement('span');
        sp.innerHTML = esc(nd.nodeValue).replace(new RegExp('(' + esc(q).replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + ')', 'gi'), '<mark>$1</mark>');
        nd.replaceWith(sp);
    });
}
let tm;
$('#q').addEventListener('input', e => {
    clearTimeout(tm); tm = setTimeout(() => { query = e.target.value.trim(); render(); }, 150);
});
// theme
const root = document.documentElement;
try { const s = localStorage.getItem('theme'); if (s) root.dataset.theme = s; } catch (_) { }
$('#theme').onclick = () => {
    const dark = root.dataset.theme ? root.dataset.theme === 'dark' : matchMedia('(prefers-color-scheme:dark)').matches;
    root.dataset.theme = dark ? 'light' : 'dark';
    try { localStorage.setItem('theme', root.dataset.theme) } catch (_) { }
};
// back to top
const topBtn = $('#top');
addEventListener('scroll', () => { topBtn.style.display = scrollY > 800 ? 'block' : 'none' }, { passive: true });
topBtn.onclick = () => scrollTo({ top: 0 });
buildMenu(); render();
if (location.hash) { const el = document.getElementById(location.hash.slice(1)); if (el) el.scrollIntoView(); }